INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fab1c4b-a86f-402a-bcef-60a1bfee11eb', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["曲突徙薪不謂賢，焦頭爛額饗盤筵。","時人多是輕先見，不獨田家國亦然。"]', '["曲突徙薪不謂賢，焦头爛額饗盤筵。","时人多是轻先见，不独田家国亦然。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6aef6ae-4a7f-4ff4-810d-becc4b82e94c', '春秋戰國門 田子奇', '春秋戰国门 田子奇', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["少年爲吏慮非循，一騎奔追委使臣。","使者不追何所對，車中緣見白頭人。"]', '["少年爲吏慮非循，一騎奔追委使臣。","使者不追何所对，车中緣见白头人。"]', '诗', 'shi', '', NULL, '春秋戰國門 田子奇 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67892ebe-6081-4b38-bee6-0dfcd6aacbcc', '春秋戰國門 百里奚', '春秋戰国门 百里奚', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["船驥由來是股肱，在虞虞滅在秦興。","裁量何異刀將尺，秪繫用之能不能。"]', '["船驥由来是股肱，在虞虞滅在秦兴。","裁量何異刀將尺，秪繫用之能不能。"]', '诗', 'shi', '', NULL, '春秋戰國門 百里奚 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c7d52c1-dae4-45eb-8be9-934d44938dcf', '春秋戰國門 孫叔敖', '春秋戰国门 孫叔敖', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["童稚逢蛇歎不祥，慮悲來者爲埋藏。","是知陽報由陰施，天爵昭然契日彰。"]', '["童稚逢蛇歎不祥，慮悲来者爲埋藏。","是知陽報由陰施，天爵昭然契日彰。"]', '诗', 'shi', '', NULL, '春秋戰國門 孫叔敖 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40da12d0-a1cd-44ac-a623-b411fce5ce14', '春秋戰國門 魯仲連', '春秋戰国门 魯仲連', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["昔迸燒牛發戰機，夜奔驚火走燕師。","今來躍馬懷驕惰，十萬如無一撮時。"]', '["昔迸燒牛發戰機，夜奔驚火走燕師。","今来躍马懷驕惰，十万如無一撮时。"]', '诗', 'shi', '', NULL, '春秋戰國門 魯仲連 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5d184fc-ff85-46a1-877d-95bca6ecab45', '春秋戰國門 宋子罕', '春秋戰国门 宋子罕', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["子憐溫潤欲歸仁，吾貴堅廉是寶身。","自有不貪身內寶，玉人徒獻外來珍。"]', '["子怜溫潤欲归仁，吾貴堅廉是寶身。","自有不貪身內寶，玉人徒獻外来珍。"]', '诗', 'shi', '', NULL, '春秋戰國門 宋子罕 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f98123a-ac95-479b-954a-a5e54de00cd8', '春秋戰國門 宮之奇', '春秋戰国门 宮之奇', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["虞虢相依自保安，謀臣吞度不爲難。","貪憐璧馬迷香餌，肯信之奇諭齒寒。"]', '["虞虢相依自保安，謀臣吞度不爲难。","貪怜璧马迷香餌，肯信之奇諭齒寒。"]', '诗', 'shi', '', NULL, '春秋戰國門 宮之奇 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f13ba69c-1ae2-4de7-af08-969eac466071', '春秋戰國門 王孫滿', '春秋戰国门 王孫满', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["九牧金鎔物像成，辭昏去亂祚休明。","興亡在德不在鼎，楚子何勞問重輕。"]', '["九牧金鎔物像成，辞昏去亂祚休明。","兴亡在德不在鼎，楚子何勞问重轻。"]', '诗', 'shi', '', NULL, '春秋戰國門 王孫滿 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('996e3eff-4996-4514-b79e-1bef62c5c6bf', '春秋戰國門 顏叔子', '春秋戰国门 顏叔子', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["夜雨鄰娃告屋傾，一宵從寄念悲驚。","誠知獨處從燒燭，君子行心要自明。"]', '["夜雨鄰娃告屋傾，一宵從寄念悲驚。","誠知独处從燒燭，君子行心要自明。"]', '诗', 'shi', '', NULL, '春秋戰國門 顏叔子 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc8da6d-32b2-4096-a7b1-807ca4933af6', '春秋戰國門 張孟譚', '春秋戰国门 張孟譚', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["強兵四合國將危，賴有謀臣爲發揮。","城內蒿銅誠自有，無謀誰解見玄機。"]', '["強兵四合国將危，賴有謀臣爲發揮。","城內蒿銅誠自有，無謀誰解见玄機。"]', '诗', 'shi', '', NULL, '春秋戰國門 張孟譚 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feb3c844-8f44-437a-b62e-787cae2c9d83', '春秋戰國門 公子無忌', '春秋戰国门 公子無忌', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["按劍臨籠震咄呼，鷂甘梟戮伏鳩辜。","能憐鈍拙誅豪俊，憫弱摧強真丈夫。"]', '["按劍臨籠震咄呼，鷂甘梟戮伏鳩辜。","能怜鈍拙誅豪俊，憫弱摧強真丈夫。"]', '诗', 'shi', '', NULL, '春秋戰國門 公子無忌 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceac5da1-4c73-4680-af3b-ab98521efb3d', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["趙解重圍魏再昌，信陵賢德日馨芳。","昏蒙愚主聽讒說，公子云亡國亦亡。"]', '["趙解重圍魏再昌，信陵賢德日馨芳。","昏蒙愚主听讒说，公子云亡国亦亡。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6effc8aa-cf93-4275-b0ff-ed78d0d16e97', '春秋戰國門 侯嬴朱亥', '春秋戰国门 侯嬴朱亥', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["屠肆監門一賤微，信陵交結國人非。","當時不是二君計，匹馬那能解趙圍。"]', '["屠肆監门一賤微，信陵交結国人非。","當时不是二君計，匹马那能解趙圍。"]', '诗', 'shi', '', NULL, '春秋戰國門 侯嬴朱亥 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a764c6c-1b5f-4b5f-b482-82a41e3d54ae', '春秋戰國門 再吟', '春秋戰国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["走敵存亡義有餘，全由雄勇與英謨。","但如公子能交結，朱亥侯嬴何代無。"]', '["走敵存亡義有餘，全由雄勇與英謨。","但如公子能交結，朱亥侯嬴何代無。"]', '诗', 'shi', '', NULL, '春秋戰國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff5f4b8e-0bf8-4406-822f-aa4290b1865d', '秦門 胡亥', '秦门 胡亥', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["鹿馬何難辨是非，寧勞卜筮問安危。","權臣爲亂多如此，亡國時君不自知。"]', '["鹿马何难辨是非，寧勞卜筮问安危。","權臣爲亂多如此，亡国时君不自知。"]', '诗', 'shi', '', NULL, '秦門 胡亥 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7d0b1fa-40a6-4c47-828f-2b95dc96b390', '秦門 再吟', '秦门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["盜賊縱橫主惡聞，遂爲流矢犯君軒。","怪言何不早言者，若使早言還不存。"]', '["盜賊縱橫主惡闻，遂爲流矢犯君軒。","怪言何不早言者，若使早言還不存。"]', '诗', 'shi', '', NULL, '秦門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dff98bb-93f8-4d9e-bbfe-8765940c23ac', '秦門 趙高', '秦门 趙高', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["趙高胡亥速天誅，率土興兵怨毒痡。","豐沛見機羣小吏，功成兒戲亦何殊。"]', '["趙高胡亥速天誅，率土兴兵怨毒痡。","豐沛见機羣小吏，功成兒戲亦何殊。"]', '诗', 'shi', '', NULL, '秦門 趙高 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c0ba142-d45c-4582-81fd-ac705de1d568', '秦門 陳涉', '秦门 陳涉', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["秦法煩苛霸業隳，一夫攘臂萬夫隨。","王侯無種英雄志，燕雀喧喧安得知。"]', '["秦法煩苛霸業隳，一夫攘臂万夫隨。","王侯無種英雄志，燕雀喧喧安得知。"]', '诗', 'shi', '', NULL, '秦門 陳涉 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b8dd73-a4d4-4d99-b0cb-d7bf8631d352', '秦門 項籍', '秦门 項籍', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["九垓垂定棄謀臣，一陣無功便殺身。","壯士誠知輕性命，不思辜負八千人。"]', '["九垓垂定棄謀臣，一陣無功便殺身。","壯士誠知轻性命，不思辜負八千人。"]', '诗', 'shi', '', NULL, '秦門 項籍 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e07b279-ca07-436d-b182-1ddaca610389', '秦門 范增', '秦门 范增', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["智士寧爲暗主謨，范公曾不讀兵書。","平生心力爲誰盡，一事無成空背疽。"]', '["智士寧爲暗主謨，范公曾不读兵书。","平生心力爲誰尽，一事無成空背疽。"]', '诗', 'shi', '', NULL, '秦門 范增 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad8b67f8-3a82-4b39-aa21-840e94cacd56', '前漢門 高祖', '前漢门 高祖', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["愛子從烹報主時，安知強啜不含悲。","太公懸命臨刀几，忍取桮羹欲爲誰。"]', '["愛子從烹報主时，安知強啜不含悲。","太公懸命臨刀几，忍取桮羹欲爲誰。"]', '诗', 'shi', '', NULL, '前漢門 高祖 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af5af6f9-f7fa-4db7-ab6e-ef2de4b2011f', '前漢門 再吟', '前漢门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["北伐匈奴事可悲，當時將相是其誰。","君臣束手平城裏，三十萬兵能忍飢。"]', '["北伐匈奴事可悲，當时將相是其誰。","君臣束手平城裏，三十万兵能忍飢。"]', '诗', 'shi', '', NULL, '前漢門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('413c12bc-c194-4446-afd3-8c1cb124a62c', '前漢門 周苛紀信', '前漢门 周苛紀信', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["爲主堅能不顧身，赴湯蹈火見忠臣。","後來邦國論心義，誰是君王出熱人。"]', '["爲主堅能不顧身，赴湯蹈火见忠臣。","後来邦国論心義，誰是君王出熱人。"]', '诗', 'shi', '', NULL, '前漢門 周苛紀信 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('880aba7b-f205-479d-beb2-6f77ba39e551', '前漢門 酇侯', '前漢门 酇侯', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["共怪酇侯第一功，咸稱得地合先封。","韓生不是蕭君薦，獵犬何人爲指蹤。"]', '["共怪酇侯第一功，咸稱得地合先封。","韓生不是蕭君薦，獵犬何人爲指蹤。"]', '诗', 'shi', '', NULL, '前漢門 酇侯 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c5980e2-1d88-46e6-8148-3d292c6a65bb', '前漢門 曲逆侯', '前漢门 曲逆侯', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["社肉分平未足奇，須觀大用展無私。","一朝如得宰天下，必使還如宰社時。"]', '["社肉分平未足奇，須观大用展無私。","一朝如得宰天下，必使還如宰社时。"]', '诗', 'shi', '', NULL, '前漢門 曲逆侯 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aaf4a05-ba5b-4148-b32c-737b5b94c82e', '前漢門 薛公', '前漢门 薛公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["黥布稱兵孰敢當，薛公三計爲斟量。","上中良策知非用，南取長沙是死鄉。"]', '["黥布稱兵孰敢當，薛公三計爲斟量。","上中良策知非用，南取长沙是死乡。"]', '诗', 'shi', '', NULL, '前漢門 薛公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f825b203-db49-44a7-bd14-bee7de0d4e1c', '前漢門 條侯', '前漢门 條侯', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["上將風戈賞罰明，矛鋋嚴閉亞夫營。","人君却稟將軍令，按轡垂鞭爲緩行。"]', '["上將风戈賞罰明，矛鋋嚴閉亞夫營。","人君却稟將軍令，按轡垂鞭爲緩行。"]', '诗', 'shi', '', NULL, '前漢門 條侯 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a91dade5-1aca-4bb0-98df-8090c45b768f', '前漢門 平津侯', '前漢门 平津侯', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["儒素逢時得自媒，忽從徒步列公台。","北辰如不延吾輩，東閣何由逐汝開。"]', '["儒素逢时得自媒，忽從徒步列公台。","北辰如不延吾輩，东閣何由逐汝开。"]', '诗', 'shi', '', NULL, '前漢門 平津侯 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0164e1ac-ac4f-4512-bb53-4e65eb61564a', '前漢門 博陸侯', '前漢门 博陸侯', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["棟梁徒自保堅貞，毀穴難防雀鼠爭。","不是主人知詐僞，如何柱石免欹傾。"]', '["棟梁徒自保堅貞，毀穴难防雀鼠爭。","不是主人知詐僞，如何柱石免欹傾。"]', '诗', 'shi', '', NULL, '前漢門 博陸侯 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15b7d55e-48c1-426a-b2dc-87b1a05d1ac7', '前漢門 夏賀良', '前漢门 夏賀良', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["漢代中微亦再昌，忠臣憂國冀修禳。","赤精符讖誠非妄，枉殺無辜夏賀良。"]', '["漢代中微亦再昌，忠臣憂国冀修禳。","赤精符讖誠非妄，枉殺無辜夏賀良。"]', '诗', 'shi', '', NULL, '前漢門 夏賀良 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e231c37-d83f-4669-a9e5-6214a43d4249', '前漢門 王莽', '前漢门 王莽', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["權歸諸呂牝雞鳴，殷鑒昭然詎可輕。","新室不囚崇外戚，水中安敢寄生營。"]', '["權归諸呂牝雞鳴，殷鑒昭然詎可轻。","新室不囚崇外戚，水中安敢寄生營。"]', '诗', 'shi', '', NULL, '前漢門 王莽 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7b54c62-7cd0-42a8-8f84-8405fa15b6ed', '前漢門 再吟', '前漢门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["重賦嚴刑作禍胎，豈知由此亂離媒。","家傳揖讓亦難濟，況是身從傾篡來。"]', '["重賦嚴刑作禍胎，豈知由此亂離媒。","家傳揖讓亦难濟，況是身從傾篡来。"]', '诗', 'shi', '', NULL, '前漢門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a46ea5-6492-4dc7-abe9-4c044acf0ac9', '前漢門 又吟', '前漢门 又吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["銅馬朱眉滿四方，總緣居攝亂天常。","因君多少布衣士，不是公卿即帝王。"]', '["銅马朱眉满四方，總緣居攝亂天常。","因君多少布衣士，不是公卿即帝王。"]', '诗', 'shi', '', NULL, '前漢門 又吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a33afc-b292-4524-9619-d95b7b329025', '前漢門 毛延壽', '前漢门 毛延壽', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["不拔金釵賂漢臣，徒嗟玉豔委胡塵。","能知貨賄移妍醜，豈獨丹青畫美人。"]', '["不拔金釵賂漢臣，徒嗟玉豔委胡塵。","能知貨賄移妍醜，豈独丹青畫美人。"]', '诗', 'shi', '', NULL, '前漢門 毛延壽 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72677656-d14f-4d52-a423-fac723136091', '前漢門 劉聖公', '前漢门 劉聖公', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["不納良謀劉縯言，胡爲銜璧向崇宣。","傷哉亂帝途窮處，何必當時譖福先。"]', '["不納良謀劉縯言，胡爲銜璧向崇宣。","傷哉亂帝途窮处，何必當时譖福先。"]', '诗', 'shi', '', NULL, '前漢門 劉聖公 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba83716-169a-472a-a881-02c3d12517a9', '前漢門 樊崇徐宣', '前漢门 樊崇徐宣', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["庸中佼佼鐵錚錚，百萬長驅入帝京。","首事縱隳三善在，歸仁何慮不全生。"]', '["庸中佼佼鐵錚錚，百万长驱入帝京。","首事縱隳三善在，归仁何慮不全生。"]', '诗', 'shi', '', NULL, '前漢門 樊崇徐宣 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f6e9cc7-21c7-4504-b6d8-98ae44dcb504', '前漢門 僭號公孫述', '前漢门 僭號公孫述', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["劍蜀金湯孰敢爭，子陽才業匪雄英。","方知在德不在險，危棧何曾阻漢兵。"]', '["劍蜀金湯孰敢爭，子陽才業匪雄英。","方知在德不在險，危棧何曾阻漢兵。"]', '诗', 'shi', '', NULL, '前漢門 僭號公孫述 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc57204-d127-4542-a33c-171f73fc204e', '後漢門 光武', '後漢门 光武', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["成敗非儒孰可量，儒生何指指蕭王。","蕭王得衆能寬裕，吳漢歸來帝業昌。"]', '["成敗非儒孰可量，儒生何指指蕭王。","蕭王得衆能寬裕，吳漢归来帝業昌。"]', '诗', 'shi', '', NULL, '後漢門 光武 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b876cb4-6288-483b-b408-272db587fd2f', '後漢門 明帝', '後漢门 明帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["朝臣咸佞孰知非，張佚公忠語獨奇。","博士一言除太傅，謚爲明帝信其宜。"]', '["朝臣咸佞孰知非，張佚公忠語独奇。","博士一言除太傅，謚爲明帝信其宜。"]', '诗', 'shi', '', NULL, '後漢門 明帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb9d95ae-57fe-4902-b671-0b64faf1d0a5', '後漢門 桓帝', '後漢门 桓帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["能嫌跋扈斬梁王，寧便榮枯信段張。","襄楷忠言誰佞惑，忍教奸禍起蕭牆。"]', '["能嫌跋扈斬梁王，寧便榮枯信段張。","襄楷忠言誰佞惑，忍教奸禍起蕭牆。"]', '诗', 'shi', '', NULL, '後漢門 桓帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a4c1380-6558-4297-b81e-2e50221ee85a', '後漢門 靈帝', '後漢门 靈帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["榜懸金價鬻官榮，千萬爲公五百卿。","公瑾孔明窮退者，安知高臥遇雄英。"]', '["榜懸金價鬻官榮，千万爲公五百卿。","公瑾孔明窮退者，安知高臥遇雄英。"]', '诗', 'shi', '', NULL, '後漢門 靈帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c4e6a5e-2d0a-4ea1-b633-0eb9f57a0b43', '後漢門 廢帝', '後漢门 廢帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["亂兵如蝟走王師，社稷顛危孰爲持。","夜逐螢光尋道路，漢家天子步歸時。"]', '["亂兵如蝟走王師，社稷顛危孰爲持。","夜逐螢光尋道路，漢家天子步归时。"]', '诗', 'shi', '', NULL, '後漢門 廢帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c84bcb-bc36-4b2e-8430-6e9de0542b09', '後漢門 獻帝', '後漢门 獻帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["秪爲曹侯數貴人，普天黔首盡黃巾。","漢靈早聽侍中諫，安得獻生稱不辰。"]', '["秪爲曹侯數貴人，普天黔首尽黄巾。","漢靈早听侍中諫，安得獻生稱不辰。"]', '诗', 'shi', '', NULL, '後漢門 獻帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51fa9503-9864-4c86-ad32-d94dd24993c9', '後漢門 再吟', '後漢门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["咸怨刑科有黨偏，耕夫無不事戎旃。","是時老幼飢號處，一斛黃禾五百千。"]', '["咸怨刑科有黨偏，耕夫無不事戎旃。","是时老幼飢號处，一斛黄禾五百千。"]', '诗', 'shi', '', NULL, '後漢門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67d6f5e9-340a-4ae2-b55e-a77bb79ad22a', '後漢門 子密', '後漢门 子密', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["子密封侯豈所宜，能高德義必無爲。","當時若縛還彭氏，率土何憂不自歸。"]', '["子密封侯豈所宜，能高德義必無爲。","當时若縛還彭氏，率土何憂不自归。"]', '诗', 'shi', '', NULL, '後漢門 子密 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e66dc8-8e11-4f44-936f-e9a39e4eeb4f', '後漢門 羊續', '後漢门 羊續', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["魚懸潔白振清風，祿散親賓歲自窮。","單席寒廳慙使者，葛衣何以至三公。"]', '["鱼懸潔白振清风，祿散親賓歲自窮。","單席寒廳慙使者，葛衣何以至三公。"]', '诗', 'shi', '', NULL, '後漢門 羊續 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d64bde6-c523-4e63-accf-97e6f911fb69', '後漢門 楊震', '後漢门 楊震', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["爲國推賢匪惠私，十金爲報遽相危。","無言暗室何人見，咫尺斯須已四知。"]', '["爲国推賢匪惠私，十金爲報遽相危。","無言暗室何人见，咫尺斯須已四知。"]', '诗', 'shi', '', NULL, '後漢門 楊震 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00abd5d5-ed72-4b80-947f-9392b583bd4b', '後漢門 趙孝', '後漢门 趙孝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["綠林清旦正朝飢，豈計行人瘦與肥。","爲感在原哀叫切，鶺鴒休報聽雙飛。"]', '["綠林清旦正朝飢，豈計行人瘦與肥。","爲感在原哀叫切，鶺鴒休報听雙飞。"]', '诗', 'shi', '', NULL, '後漢門 趙孝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0337cdd-1c30-4656-a4c0-0eaa713d9ad7', '後漢門 馬后', '後漢门 马后', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["麄衣閑寂閱羣書，薦達嬪妃廣帝居。","再實傷根嫌貴寵，惠慈勞悴育皇儲。"]', '["麄衣闲寂閱羣书，薦達嬪妃廣帝居。","再實傷根嫌貴寵，惠慈勞悴育皇儲。"]', '诗', 'shi', '', NULL, '後漢門 馬后 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cec5a2f2-50f5-4a08-91d7-77acec511db5', '後漢門 魏博妻', '後漢门 魏博妻', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["蘿挂青松是所依，松凋蘿更改何枝。","操刀必割腕可斷，磐石徒堅心不移。"]', '["蘿挂青松是所依，松凋蘿更改何枝。","操刀必割腕可斷，磐石徒堅心不移。"]', '诗', 'shi', '', NULL, '後漢門 魏博妻 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19371a00-41ef-4dd7-94b0-295b57ee52d4', '後漢門 曹娥', '後漢门 曹娥', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["心摧目斷哭江濆，窺浪無蹤日又昏。","不入重泉尋水底，此生安得見沈魂。"]', '["心摧目斷哭江濆，窺浪無蹤日又昏。","不入重泉尋水底，此生安得见沈魂。"]', '诗', 'shi', '', NULL, '後漢門 曹娥 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13d1d918-3d91-4d2b-aa05-d478fa88aebd', '後漢門 周都妻', '後漢门 周都妻', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["綠水雙鴛一已沈，皇天更欲配何禽。","不將血涕隨霜刃，誰見朱殷未死心。"]', '["綠水雙鴛一已沈，皇天更欲配何禽。","不將血涕隨霜刃，誰见朱殷未死心。"]', '诗', 'shi', '', NULL, '後漢門 周都妻 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c2ed7e-5d9b-4575-ba68-7505bc6b8dfb', '後漢門 鮑宣妻', '後漢门 鲍宣妻', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["君惡奢華意不歡，一言從儉亦何難。","但能和樂同琴瑟，未必恩情在綺紈。"]', '["君惡奢华意不歡，一言從儉亦何难。","但能和乐同琴瑟，未必恩情在綺紈。"]', '诗', 'shi', '', NULL, '後漢門 鮑宣妻 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b957f2e-7117-4b98-a296-ceb7f7c3b055', '後漢門 呂母', '後漢门 呂母', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["獄無良吏雪無由，處處戈鋋自執仇。","呂母銜冤窮老婦，亦能爲帥復私讎。"]', '["獄無良吏雪無由，处处戈鋋自執仇。","呂母銜冤窮老婦，亦能爲帥复私讎。"]', '诗', 'shi', '', NULL, '後漢門 呂母 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeaf9ef2-76b7-4df4-89f9-ce484db8aa94', '三國門 蜀先主', '三国门 蜀先主', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["豫州軍敗信途窮，徐庶推能薦臥龍。","不是卑詞三訪謁，誰令玄德主巴邛。"]', '["豫州軍敗信途窮，徐庶推能薦臥龙。","不是卑词三訪謁，誰令玄德主巴邛。"]', '诗', 'shi', '', NULL, '三國門 蜀先主 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6851d1a6-c1cc-49ca-9714-af6b3df3971f', '三國門 再吟', '三国门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["一家區宇忽三分，齷齪車書曷足論。","定有伊姜爲佐輔，忍教鴻鴈各乾坤。"]', '["一家區宇忽三分，齷齪车书曷足論。","定有伊姜爲佐輔，忍教鴻鴈各乾坤。"]', '诗', 'shi', '', NULL, '三國門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afcd3b8b-ae7d-47ca-a08a-83551e94ece2', '三國門 後主', '三国门 後主', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["萬峯如劍載前來，危閣橫空信險哉。","對此玄休長歎息，方知劉禪是庸才。"]', '["万峯如劍載前来，危閣橫空信險哉。","对此玄休长歎息，方知劉禪是庸才。"]', '诗', 'shi', '', NULL, '三國門 後主 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed7e893-1aad-44d7-857a-43ccf4b6b2c9', '三國門 吳後主', '三国门 吳後主', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["吳宮季主恣驕奢，移盡江南百媚花。","一旦狂風江上起，花隨風散落誰家。"]', '["吳宮季主恣驕奢，移尽江南百媚花。","一旦狂风江上起，花隨风散落誰家。"]', '诗', 'shi', '', NULL, '三國門 吳後主 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df83c9a9-031e-42f3-8908-c155895f839e', '三國門 王表', '三国门 王表', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["王表聞聲莫見身，吳中敬事甚君親。","是知邦國將亡滅，不聽人臣聽鬼神。"]', '["王表闻声莫见身，吳中敬事甚君親。","是知邦国將亡滅，不听人臣听鬼神。"]', '诗', 'shi', '', NULL, '三國門 王表 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f121422a-9e1d-4f8f-aea8-1fcfdad1b9ab', '三國門 魯肅', '三国门 魯肅', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["輕財重義見英奇，聖主賢臣是所依。","公瑾窘飢求子敬，一言纔起數船歸。"]', '["轻財重義见英奇，聖主賢臣是所依。","公瑾窘飢求子敬，一言纔起數船归。"]', '诗', 'shi', '', NULL, '三國門 魯肅 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31c747d7-982b-496c-9ed0-905f73eedb85', '晉門 晉武帝', '晉门 晉武帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["漢貪金帛鬻公卿，財贍羸軍冀國寧。","晉武鬻官私室富，是知猶不及桓靈。"]', '["漢貪金帛鬻公卿，財贍羸軍冀国寧。","晉武鬻官私室富，是知猶不及桓靈。"]', '诗', 'shi', '', NULL, '晉門 晉武帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89b4ace5-82b9-456f-a166-7a5f0489d646', '晉門 再吟', '晉门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["君人爲理在安民，論道求賢德自新。","經國遠圖無所問，何曾言指一何神。"]', '["君人爲理在安民，論道求賢德自新。","經国远圖無所问，何曾言指一何神。"]', '诗', 'shi', '', NULL, '晉門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc5695eb-050f-42c8-9fdd-ff96433ba383', '晉門 惠帝', '晉门 惠帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["蛙鳴堪笑問官私，更勸飢人食肉糜。","蒙昧萬機猶婦女，寇戎安得不紛披。"]', '["蛙鳴堪笑问官私，更勸飢人食肉糜。","蒙昧万機猶婦女，寇戎安得不紛披。"]', '诗', 'shi', '', NULL, '晉門 惠帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdb20aa0-4fe0-4e27-9cbb-3f6140a957a1', '晉門 賈后', '晉门 賈后', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["賈后甘爲廢戮人，齊王還殺趙王倫。","一從天下無真主，瓜割中原四百春。"]', '["賈后甘爲廢戮人，齊王還殺趙王倫。","一從天下無真主，瓜割中原四百春。"]', '诗', 'shi', '', NULL, '晉門 賈后 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0600ad8f-c0a5-4739-96d1-9597d02cc17c', '晉門 懷帝', '晉门 懷帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["蕃漢戈矛遍九垓，兩京簪紱走黃埃。","劉聰大會平陽日，遣帝行觴事可哀。"]', '["蕃漢戈矛遍九垓，兩京簪紱走黄埃。","劉聰大會平陽日，遣帝行觴事可哀。"]', '诗', 'shi', '', NULL, '晉門 懷帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eac0289e-8cad-49e1-83b9-8fddc325aec7', '晉門 愍帝', '晉门 愍帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["耕牛喫盡大田荒，二兩黃金糴斗糧。","御粥又聞無麴屑，不降胡虜奈飢腸。"]', '["耕牛喫尽大田荒，二兩黄金糴斗糧。","御粥又闻無麴屑，不降胡虜奈飢腸。"]', '诗', 'shi', '', NULL, '晉門 愍帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa76d842-dfcc-45e9-8d13-4e91e01e7ec3', '晉門 郭欽', '晉门 郭欽', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["誰疑忠諫郭欽言，不逐戎夷出塞垣。","晉室既無明聖主，果爲胡虜亂中原。"]', '["誰疑忠諫郭欽言，不逐戎夷出塞垣。","晉室既無明聖主，果爲胡虜亂中原。"]', '诗', 'shi', '', NULL, '晉門 郭欽 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d50fc12-5805-4554-af6c-73d0651dc38b', '晉門 王夷甫', '晉门 王夷甫', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["六合誰爲輔弼臣，八風昏處盡胡塵。","是知濟弱扶傾術，不屬高談虛論人。"]', '["六合誰爲輔弼臣，八风昏处尽胡塵。","是知濟弱扶傾術，不屬高談虛論人。"]', '诗', 'shi', '', NULL, '晉門 王夷甫 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2af59070-a112-4659-b7e3-ce416795e208', '晉門 王茂弘', '晉门 王茂弘', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["韓魏荆揚日豈堪，胡風看欲過江南。","中原一片生靈血，誰秉王綱色不慙。"]', '["韓魏荆揚日豈堪，胡风看欲過江南。","中原一片生靈血，誰秉王綱色不慙。"]', '诗', 'shi', '', NULL, '晉門 王茂弘 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f72f9a5-6b91-4d38-ba27-30f1b2fb334f', '晉門 吳隱之', '晉门 吳隐之', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["聞說貪泉近鬱林，隱之今日得深斟。","徒言滴水能穿石，其那堅貞匪石心。"]', '["闻说貪泉近鬱林，隐之今日得深斟。","徒言滴水能穿石，其那堅貞匪石心。"]', '诗', 'shi', '', NULL, '晉門 吳隱之 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33e1714d-9d65-4cad-a492-0d2f22f79799', '晉門 再吟', '晉门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["貪泉何處是泉源，只在靈臺一點間。","必也心源元自有，此泉何必在江山。"]', '["貪泉何处是泉源，只在靈台一点间。","必也心源元自有，此泉何必在江山。"]', '诗', 'shi', '', NULL, '晉門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57e1c8c0-1378-463a-9c75-9fd58acc95b0', '六朝門 前趙劉聰', '六朝门 前趙劉聰', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["戎羯誰令識善言，刑將不捨遽能原。","垂成却罷鳳儀殿，仍改逍遙納諫園。"]', '["戎羯誰令識善言，刑將不捨遽能原。","垂成却罷鳳儀殿，仍改逍遙納諫园。"]', '诗', 'shi', '', NULL, '六朝門 前趙劉聰 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f289a914-f36a-4a58-ae11-ef3d1f0ada3b', '六朝門 前涼張軌', '六朝门 前涼張軌', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["官從主簿至專征，誰遣涼王破趙名。","益信用賢由拔擢，穰苴不是將家生。"]', '["官從主簿至專征，誰遣涼王破趙名。","益信用賢由拔擢，穰苴不是將家生。"]', '诗', 'shi', '', NULL, '六朝門 前涼張軌 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bbf8cb9-779b-40ed-b611-14b3a4881e2e', '六朝門 後魏武帝', '六朝门 後魏武帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["太武南征似卷蓬，徐陽兗蔡殺皆空。","從來弔伐寧如此，千里無煙血草紅。"]', '["太武南征似卷蓬，徐陽兗蔡殺皆空。","從来弔伐寧如此，千里無煙血草紅。"]', '诗', 'shi', '', NULL, '六朝門 後魏武帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5aa8dfb-d520-49bc-8caa-3c253b9c6e23', '六朝門 三廢帝', '六朝门 三廢帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["明莊節閔併罹殃，命在朱高二悖王。","已歎一年三易換，更嗟毆辱下東廊。"]', '["明莊節閔併罹殃，命在朱高二悖王。","已歎一年三易換，更嗟毆辱下东廊。"]', '诗', 'shi', '', NULL, '六朝門 三廢帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb83c083-3fa9-4cdd-8c03-d0ee86f15d55', '六朝門 苻堅', '六朝门 苻堅', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["百萬南征幾馬歸，叛亡如蝟亦何悲。","賓擒敵國諸戎主，更遣權兵過在誰。"]', '["百万南征幾马归，叛亡如蝟亦何悲。","賓擒敵国諸戎主，更遣權兵過在誰。"]', '诗', 'shi', '', NULL, '六朝門 苻堅 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d86c453-ef1f-4bc4-96f5-e3c3848b2001', '六朝門 再吟', '六朝门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["空知勇銳不知兵，困獸孤軍未可輕。","安有長驅百餘萬，身馳幾旅欲先征。"]', '["空知勇銳不知兵，困獸孤軍未可轻。","安有长驱百餘万，身驰幾旅欲先征。"]', '诗', 'shi', '', NULL, '六朝門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca7c741e-bd0d-4d0c-b3f4-7543d1ec806c', '六朝門 又吟', '六朝门 又吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["水影星光怪異多，不思修德事干戈。","無謀拒諫仍輕敵，國破身擒將奈何。"]', '["水影星光怪異多，不思修德事干戈。","無謀拒諫仍轻敵，国破身擒將奈何。"]', '诗', 'shi', '', NULL, '六朝門 又吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fedf4d0-8b7e-477f-95ab-be63da647c80', '六朝門 宋武帝', '六朝门 宋武帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["棲棲老楚未遭時，債主憑陵似迫危。","人傑既爲王謐識，刁逵誅斬獨何悲。"]', '["棲棲老楚未遭时，債主憑陵似迫危。","人傑既爲王謐識，刁逵誅斬独何悲。"]', '诗', 'shi', '', NULL, '六朝門 宋武帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5fa45d9-85ca-4a1f-b3b9-6b117d829ab2', '六朝門 二廢帝', '六朝门 二廢帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["肆意荒狂殺不辜，方嗟廢帝又蒼梧。","自言威震爲英武，肯慮湘東與玉夫。"]', '["肆意荒狂殺不辜，方嗟廢帝又蒼梧。","自言威震爲英武，肯慮湘东與玉夫。"]', '诗', 'shi', '', NULL, '六朝門 二廢帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48eebe21-4bd6-470e-b812-77090804c156', '六朝門 齊廢帝東昏侯', '六朝门 齊廢帝东昏侯', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["定策誰扶捕鼠兒，不憂蕭衍畏潘妃。","長圍既合刀臨項，猶惜金錢對落暉。"]', '["定策誰扶捕鼠兒，不憂蕭衍畏潘妃。","长圍既合刀臨項，猶惜金錢对落暉。"]', '诗', 'shi', '', NULL, '六朝門 齊廢帝東昏侯 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cbadf92-2801-4cd5-8a0e-ca6c88eff08b', '六朝門 梁武帝', '六朝门 梁武帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["梁武年高厭六龍，繁華聲色盡歸空。","不求賢德追堯舜，翻作憂囚一病翁。"]', '["梁武年高厭六龙，繁华声色尽归空。","不求賢德追堯舜，翻作憂囚一病翁。"]', '诗', 'shi', '', NULL, '六朝門 梁武帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d98ca3-7ba6-4bcd-a108-d64134dcbfce', '六朝門 再吟', '六朝门 再吟', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["興亡何故遽環迴，湯紂身爲事可哀。","莫是自長嫌勝己，蔽賢猶執匹夫才。"]', '["兴亡何故遽环迴，湯紂身爲事可哀。","莫是自长嫌勝己，蔽賢猶執匹夫才。"]', '诗', 'shi', '', NULL, '六朝門 再吟 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7220e6a4-002c-4497-951a-b42a9d47f4f5', '六朝門 簡文帝', '六朝门 簡文帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["救兵方至強抽軍，與賊開城是簡文。","曲項琵琶催酒處，不圖爲樂向誰云。"]', '["救兵方至強抽軍，與賊开城是簡文。","曲項琵琶催酒处，不圖爲乐向誰云。"]', '诗', 'shi', '', NULL, '六朝門 簡文帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0150f334-ea7d-4c97-8b2c-d8f8b651eef9', '六朝門 元帝', '六朝门 元帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["木柵江城困魏軍，王褒橫議遏謀臣。","賓降未免俱爲戮，一死安能謝益仁。"]', '["木柵江城困魏軍，王褒橫議遏謀臣。","賓降未免俱爲戮，一死安能謝益仁。"]', '诗', 'shi', '', NULL, '六朝門 元帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e99254b-8aea-41ef-b9aa-90937e815246', '六朝門 謝舉', '六朝门 謝舉', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["叛奴逃數豈堪留，忠節曾無肯到頭。","朱异早能同遠見，青衫寧假帝登樓。"]', '["叛奴逃數豈堪留，忠節曾無肯到头。","朱异早能同远见，青衫寧假帝登楼。"]', '诗', 'shi', '', NULL, '六朝門 謝舉 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271d74cc-219e-4676-9728-30205c1c22ac', '六朝門 朱异', '六朝门 朱异', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["徒覽儒書不學兵，彥和虛得不廉名。","四郊多壘猶相罪，國破將何謝太清。"]', '["徒覽儒书不学兵，彥和虛得不廉名。","四郊多壘猶相罪，国破將何謝太清。"]', '诗', 'shi', '', NULL, '六朝門 朱异 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d08ed9f-4d60-4d6f-b6e4-80841912dd24', '六朝門 傅昭', '六朝门 傅昭', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["爲政殘苛獸亦飢，除飢機在養疲羸。","人能善政獸何暴，焉用勞人以檻爲。"]', '["爲政殘苛獸亦飢，除飢機在養疲羸。","人能善政獸何暴，焉用勞人以檻爲。"]', '诗', 'shi', '', NULL, '六朝門 傅昭 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac2730a-2a63-4d53-8c74-254ddad19137', '六朝門 宣帝', '六朝门 宣帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["宣帝驕奢恣所爲，後宮升降略無時。","乘危自有妻公在，安許鸞凰是尉遲。"]', '["宣帝驕奢恣所爲，後宮升降略無时。","乘危自有妻公在，安許鸾凰是尉遲。"]', '诗', 'shi', '', NULL, '六朝門 宣帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('131a3641-73b6-4ede-a3bf-c5f03d7bcaa2', '六朝門 李集', '六朝门 李集', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["忠諫能堅信正臣，三沈三屈竟何云。","每沈良久方能語，及語還呼桀紂君。"]', '["忠諫能堅信正臣，三沈三屈竟何云。","每沈良久方能語，及語還呼桀紂君。"]', '诗', 'shi', '', NULL, '六朝門 李集 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a84f73-0d63-44ca-9c67-d6b48772b4cf', '隋門 隋文帝', '隋门 隋文帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["孤兒寡婦忍同欺，輔政剛教篡奪爲。","矯詔必能疎昉譯，直臣誠合重顏儀。"]', '["孤兒寡婦忍同欺，輔政剛教篡奪爲。","矯詔必能疎昉譯，直臣誠合重顏儀。"]', '诗', 'shi', '', NULL, '隋門 隋文帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e500a26-ad42-49d2-80bb-a05909d0109e', '隋門 獨孤后', '隋门 独孤后', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["腹生奚強有親疎，憐者爲賢棄者愚。","儲貳不遭讒搆死，隋亡寧便在江都。"]', '["腹生奚強有親疎，怜者爲賢棄者愚。","儲貳不遭讒搆死，隋亡寧便在江都。"]', '诗', 'shi', '', NULL, '隋門 獨孤后 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e5c260c-f9a7-441d-bfd2-bba363d6ff40', '隋門 煬帝', '隋门 煬帝', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["拒諫勞兵作禍基，窮奢極武向戎夷。","兆人疲弊不堪命，天下嗷嗷新主資。"]', '["拒諫勞兵作禍基，窮奢極武向戎夷。","兆人疲弊不堪命，天下嗷嗷新主資。"]', '诗', 'shi', '', NULL, '隋門 煬帝 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c85206-3bff-42fb-93d5-55f42d39b087', '隋門 賀若弼', '隋门 賀若弼', '645e4f07-dbe8-4067-b4bc-7b7f942d7c03', '唐', '["破敵江軍意氣豪，請除傾國斬妖嬈。","紅綃忍染嬌春雪，瞪目看行切玉刀。"]', '["破敵江軍意氣豪，請除傾国斬妖嬈。","紅綃忍染嬌春雪，瞪目看行切玉刀。"]', '诗', 'shi', '', NULL, '隋門 賀若弼 周曇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4d1014e-3925-486d-be40-13c9d856b23b', '上清辭五首 一', '上清辞五首 一', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["入海浮生汗漫秋，紫皇高宴五雲樓。","霓裳曲罷天風起，吹散仙香滿十洲。"]', '["入海浮生汗漫秋，紫皇高宴五云楼。","霓裳曲罷天风起，吹散仙香满十洲。"]', '诗', 'shi', '', NULL, '上清辭五首 一 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e50bf1d4-8483-420d-85ab-424ee4e66a3d', '上清辭五首 二', '上清辞五首 二', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["樓鏁彤霞地絕塵，碧桃花發九天春。","東皇近日慵遊宴，閑煞瑤池五色麟。"]', '["楼鏁彤霞地絕塵，碧桃花發九天春。","东皇近日慵游宴，闲煞瑤池五色麟。"]', '诗', 'shi', '', NULL, '上清辭五首 二 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88b706c5-b2a6-4aa0-8401-b89746c1cb9b', '上清辭五首 三', '上清辞五首 三', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["上清仙路有丹梯，影響行人到即迷。","不會無端箇漁父，阿誰教入武陵溪。"]', '["上清仙路有丹梯，影响行人到即迷。","不會無端箇漁父，阿誰教入武陵溪。"]', '诗', 'shi', '', NULL, '上清辭五首 三 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d0cabc8-868a-4b6e-a6ee-cb40c0980127', '上清辭五首 四', '上清辞五首 四', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["本來方朔是真仙，偶別丹臺未得還。","何事玉皇消息晚，忍教顦顇向人間。"]', '["本来方朔是真仙，偶別丹台未得還。","何事玉皇消息晚，忍教顦顇向人间。"]', '诗', 'shi', '', NULL, '上清辭五首 四 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a17717a-0765-433b-bb1b-019bd24f830d', '上清辭五首 五', '上清辞五首 五', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["新拜天官上玉都，紫皇親授五靈符。","羣仙箇箇來相問，人世風光似此無。"]', '["新拜天官上玉都，紫皇親授五靈符。","羣仙箇箇来相问，人世风光似此無。"]', '诗', 'shi', '', NULL, '上清辭五首 五 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7b39c8f-2511-4f64-a627-f584111e48fa', '讀三國志', '读三国志', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["有國由來在得賢，莫言興廢是循環。","武侯星落周瑜死，平蜀降吳似等閑。"]', '["有国由来在得賢，莫言兴廢是循环。","武侯星落周瑜死，平蜀降吳似等闲。"]', '诗', 'shi', '', NULL, '讀三國志 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f004730-8306-48e8-8842-40088ebfce1f', '山舍南溪小桃花', '山舍南溪小桃花', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["一樹繁英奪眼紅，開時先合占東風。","可憐地僻無人賞，拋擲深山亂木中。"]', '["一樹繁英奪眼紅，开时先合占东风。","可怜地僻無人賞，拋擲深山亂木中。"]', '诗', 'shi', '', NULL, '山舍南溪小桃花 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a7968d7-25df-4105-9be3-bb08960f25f4', '春行遇雨', '春行遇雨', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["夾路輕風撼柳條，雨侵春態動無憀。","採香陌上誰家女，濕損釵頭翡翠翹。"]', '["夾路轻风撼柳條，雨侵春態动無憀。","採香陌上誰家女，濕損釵头翡翠翹。"]', '诗', 'shi', '', NULL, '春行遇雨 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a8c837-3d80-460a-8463-c848e64419bc', '登樓寄遠', '登楼寄远', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["滿城春色花如雪，極目煙光月似鉤。","總是動人鄉思處，更堪容易上高樓。"]', '["满城春色花如雪，極目煙光月似鉤。","總是动人乡思处，更堪容易上高楼。"]', '诗', 'shi', '', NULL, '登樓寄遠 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca00847-6a53-410e-8dbc-417173c2ca92', '望思臺', '望思台', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["漢武年高慢帝圖，任人曾不問賢愚。","直饒四老依前出，消得江充寵佞無。"]', '["漢武年高慢帝圖，任人曾不问賢愚。","直饒四老依前出，消得江充寵佞無。"]', '诗', 'shi', '', NULL, '望思臺 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f409e465-e575-4f57-b1e2-46b24d725b56', '山舍偶題', '山舍偶題', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["門掩松蘿一逕深，偶攜藜杖出前林。","誰知盡日看山坐，萬古興亡總在心。"]', '["门掩松蘿一逕深，偶携藜杖出前林。","誰知尽日看山坐，万古兴亡總在心。"]', '诗', 'shi', '', NULL, '山舍偶題 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfadc7fe-c0bd-4925-ab66-eac8dcfac5d1', '荆溪夜泊', '荆溪夜泊', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["點點漁燈照浪清，水煙疎碧月朧明。","小灘驚起鴛鴦處，一隻採蓮船過聲。"]', '["点点漁灯照浪清，水煙疎碧月朧明。","小灘驚起鴛鴦处，一隻採蓮船過声。"]', '诗', 'shi', '', NULL, '荆溪夜泊 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf93bd56-d49d-4dd3-b450-8a3927987459', '旅舍臥病', '旅舍臥病', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["家隔西秦無遠信，身隨東洛度流年。","病來旅館誰相問，牢落閑庭一樹蟬。"]', '["家隔西秦無远信，身隨东洛度流年。","病来旅館誰相问，牢落闲庭一樹蟬。"]', '诗', 'shi', '', NULL, '旅舍臥病 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6de797c3-85a3-464b-9026-94942a22743f', '登昭福寺樓', '登昭福寺楼', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["旅懷秋興正無涯，獨倚危樓四望賒。","谷變陵遷何處問，滿川空有舊煙霞。"]', '["旅懷秋兴正無涯，独倚危楼四望賒。","谷变陵遷何处问，满川空有旧煙霞。"]', '诗', 'shi', '', NULL, '登昭福寺樓 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cffc9810-afe1-425a-80e1-b3de027497d5', '代邊將', '代邊將', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["雪凍陰河半夜風，戰回狂虜血漂紅。","據鞍遙指長安路，須刻麟臺第一功。"]', '["雪凍陰河半夜风，戰回狂虜血漂紅。","據鞍遙指长安路，須刻麟台第一功。"]', '诗', 'shi', '', NULL, '代邊將 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61d818be-d596-4433-88cf-93cdddd1343a', '夜與張舒話別', '夜與張舒話別', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["愁聽南樓角又吹，曉雞啼後更分離。","如何銷得淒涼思，更勸燈前酒一巵。"]', '["愁听南楼角又吹，晓雞啼後更分離。","如何銷得淒涼思，更勸灯前酒一巵。"]', '诗', 'shi', '', NULL, '夜與張舒話別 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59cc85c8-b661-4084-9e3c-57b2083226df', '寒梅詞', '寒梅词', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["霜梅先拆嶺頭枝，萬卉千花凍不知。","留得和羹滋味在，任他風雪苦相欺。"]', '["霜梅先拆嶺头枝，万卉千花凍不知。","留得和羹滋味在，任他风雪苦相欺。"]', '诗', 'shi', '', NULL, '寒梅詞 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fe6b99a-efd9-4ce1-9a77-40dfbe2bbe1b', '題靈泉寺', '題靈泉寺', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["入谷先生一陣香，異花奇木簇禪堂。","可憐門外高低路，萬轂千蹄日日忙。"]', '["入谷先生一陣香，異花奇木簇禪堂。","可怜门外高低路，万轂千蹄日日忙。"]', '诗', 'shi', '', NULL, '題靈泉寺 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bfd7eaa-a4a8-4664-825f-8c75045f4775', '宿張正字別業', '宿張正字別業', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["茅屋蕭寥煙暗後，松窗寂歷月明初。","此時誰念孤吟客，唯有黃公一帙書。"]', '["茅屋蕭寥煙暗後，松窗寂歷月明初。","此时誰念孤吟客，唯有黄公一帙书。"]', '诗', 'shi', '', NULL, '宿張正字別業 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d54eb837-eed8-48a0-b2ba-4bf13ddad195', '鶴', '鹤', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["天上瑤池覆五雲，玉麟金鳳好爲羣。","不須更飲人間水，直是清流也汗君。"]', '["天上瑤池覆五云，玉麟金鳳好爲羣。","不須更饮人间水，直是清流也汗君。"]', '诗', 'shi', '', NULL, '鶴 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63f48c92-e53c-4aec-8af7-f1ce24ad351c', '過相思谷', '過相思谷', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["悠悠信馬春山曲，芳草和煙鋪嫩綠。","正被離愁著莫人，那堪更過相思谷。"]', '["悠悠信马春山曲，芳草和煙鋪嫩綠。","正被離愁著莫人，那堪更過相思谷。"]', '诗', 'shi', '', NULL, '過相思谷 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af7e395-f69d-42e4-bed5-37e2604388fb', '寫莊子', '寫莊子', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["聖澤安排當散地，賢侯優貸借新居。","閑中亦有閑生計，寫得南華一部書。"]', '["聖澤安排當散地，賢侯優貸借新居。","闲中亦有闲生計，寫得南华一部书。"]', '诗', 'shi', '', NULL, '寫莊子 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78496197-daf3-40b2-a468-a50f1acc6751', '山中寄友人', '山中寄友人', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["亂雲堆裏結茅廬，已共紅塵跡漸疎。","莫問野人生計事，窗前流水枕前書。"]', '["亂云堆裏結茅廬，已共紅塵跡漸疎。","莫问野人生計事，窗前流水枕前书。"]', '诗', 'shi', '', NULL, '山中寄友人 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaf798a7-fea9-4bcc-8ee5-697224d2bcd1', '津亭', '津亭', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["津亭欲闋戒棠舟，五兩風來不暫留。","西北浮雲連魏闕，東南初日滿秦樓。","層城渺渺人傷別，芳草萋萋客倦遊。","平樂舊歡收不得，更憑飛夢到瀛洲。"]', '["津亭欲闋戒棠舟，五兩风来不暫留。","西北浮云連魏闕，东南初日满秦楼。","層城渺渺人傷別，芳草萋萋客倦游。","平乐旧歡收不得，更憑飞梦到瀛洲。"]', '诗', 'shi', '', NULL, '津亭 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c9a3e8f-f293-4757-bf40-5b13cd4b3d47', '古別', '古別', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["長道何年祖軷休，風帆不斷岳陽樓。","佳人挾瑟漳河曉，壯士悲歌易水秋。","九帳[青]油徒自負，百壺芳醑豈消憂。","至今長樂坡前水，不啻秦人怨隴頭。"]', '["长道何年祖軷休，风帆不斷岳陽楼。","佳人挾瑟漳河晓，壯士悲歌易水秋。","九帳[青]油徒自負，百壺芳醑豈消憂。","至今长乐坡前水，不啻秦人怨隴头。"]', '诗', 'shi', '', NULL, '古別 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e703ceb8-ba4c-47c8-810d-cb95f3c5dae9', '塞上', '塞上', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["漢家神箭定天山，煙火相望萬里間。","契利請盟金匕酒，將軍歸臥玉門關。","雲沈老上妖氛斷，雪照回中探騎閑。","五餌已行王道勝，絕無刁斗至闐顏。"]', '["漢家神箭定天山，煙火相望万里间。","契利請盟金匕酒，將軍归臥玉门关。","云沈老上妖氛斷，雪照回中探騎闲。","五餌已行王道勝，絕無刁斗至闐顏。"]', '诗', 'shi', '', NULL, '塞上 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e59dfb2-ade3-4f63-9fc6-66a1e34534da', '寄昭潭王中立', '寄昭潭王中立', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["高弦一弄武陵深，六幕天空萬里心。","吳苑歌驪成久別，楚峰回雁好歸音。","十千美酒花期隔，三百枯棋弈思沈。","莫上孤城頻送目，浮雲西北是家林。"]', '["高弦一弄武陵深，六幕天空万里心。","吳苑歌驪成久別，楚峰回雁好归音。","十千美酒花期隔，三百枯棋弈思沈。","莫上孤城頻送目，浮云西北是家林。"]', '诗', 'shi', '', NULL, '寄昭潭王中立 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67916e82-f4c6-4438-addb-1ad5a77160ba', '雪', '雪', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["屏翳驅雲結夜陰，素花飄墜惡氛沈。","色欺曹國麻衣淺，寒入荆王翠被深。","天上明河銀作水，海中仙樹玉爲林。","日高獨擁鸘裘臥，誰乞長安取酒金。"]', '["屏翳驱云結夜陰，素花飄墜惡氛沈。","色欺曹国麻衣淺，寒入荆王翠被深。","天上明河銀作水，海中仙樹玉爲林。","日高独擁鸘裘臥，誰乞长安取酒金。"]', '诗', 'shi', '', NULL, '雪 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56afb14b-8657-4692-9e0e-980ccc638f4c', '沖虛觀', '沖虛观', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["五粒青松護翠苔，石門岑寂斷纖埃。","水浮花片知仙路，風遞鸞聲認嘯臺。","桐井曉寒千乳歛，茗園春嫩一旗開。","馳煙未勒山亭字，可是英靈許再來。"]', '["五粒青松護翠苔，石门岑寂斷纖埃。","水浮花片知仙路，风遞鸾声認嘯台。","桐井晓寒千乳歛，茗园春嫩一旗开。","驰煙未勒山亭字，可是英靈許再来。"]', '诗', 'shi', '', NULL, '沖虛觀 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('389a537d-3e98-47a9-b31d-91531df9c0c2', '淮南發運趙邢州被詔歸闕', '淮南發運趙邢州被詔归闕', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["天臺封詔紫泥馨，馬首前瞻北斗城。","人在函關先望氣，帝於京兆最知名。","一區東第趨晨近，數刻西廂接晝榮。","正是兩宮裁化日，百金雙璧拜虞卿。"]', '["天台封詔紫泥馨，马首前瞻北斗城。","人在函关先望氣，帝於京兆最知名。","一區东第趨晨近，數刻西廂接晝榮。","正是兩宮裁化日，百金雙璧拜虞卿。"]', '诗', 'shi', '', NULL, '淮南發運趙邢州被詔歸闕 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01afb5a7-318f-455b-bf37-d6d6c7ff86c2', '天街曉望', '天街晓望', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["長樂才聞一叩鐘，百官初謁未央宮。","金波穆穆沙隄月，玉樹琤琤上苑風。","香重椒蘭橫結霧，氣寒龍虎遠浮空。","嗟余索米無人問，行避霜臺御史驄。"]', '["长乐才闻一叩鐘，百官初謁未央宮。","金波穆穆沙隄月，玉樹琤琤上苑风。","香重椒蘭橫結霧，氣寒龙虎远浮空。","嗟余索米無人问，行避霜台御史驄。"]', '诗', 'shi', '', NULL, '天街曉望 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d40576b3-4499-41f3-a5bd-5961dab87947', '淮南王', '淮南王', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["貪鑄金錢盜寫符，何曾七國戒前車。","長生不待爐中藥，鴻寶誰收篋裏書。","碧井牀空天影在，小山人去桂叢疎。","雲中雞犬無消息，麥秀漸漸徧故墟。"]', '["貪鑄金錢盜寫符，何曾七国戒前车。","长生不待爐中藥，鴻寶誰收篋裏书。","碧井牀空天影在，小山人去桂叢疎。","云中雞犬無消息，麦秀漸漸徧故墟。"]', '诗', 'shi', '', NULL, '淮南王 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d1b305d-a24e-4793-9878-48495be840f0', '趙宗道歸輦下', '趙宗道归輦下', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["沿牒相逢楚水湄，竹林文酒此攀嵇。","半氈未暖還傷別，一臂初交又解攜。","江浦嘔啞風送樐，河橋勃窣柳垂隄。","明年四月秦關到，洗眼揚州看馬[蹄]。"]', '["沿牒相逢楚水湄，竹林文酒此攀嵇。","半氈未暖還傷別，一臂初交又解携。","江浦嘔啞风送樐，河橋勃窣柳垂隄。","明年四月秦关到，洗眼揚州看马[蹄]。"]', '诗', 'shi', '', NULL, '趙宗道歸輦下 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25db79dc-94ef-489c-a2c8-bc7b1d683f1f', '憶薦福寺牡丹', '憶薦福寺牡丹', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["十日春風隔翠岑，秪應繁朵自成陰。","樽前可要人頹玉，樹底遙知地側金。","花界三千春渺渺，銅槃十二夜沈沈。","雕槃分篸何由得，空作西州擁鼻吟。"]', '["十日春风隔翠岑，秪應繁朵自成陰。","樽前可要人頹玉，樹底遙知地側金。","花界三千春渺渺，銅槃十二夜沈沈。","雕槃分篸何由得，空作西州擁鼻吟。"]', '诗', 'shi', '', NULL, '憶薦福寺牡丹 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ba4506a-3e07-4f05-8b56-ad3833954ba3', '次韻和朱況雨中之什', '次韻和朱況雨中之什', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["蒼野迷雲黯不歸，遠風吹雨入巖扉。","石牀潤極琴絲緩，水閣寒多酒力微。","夕夢將成還滴滴，春心欲斷正霏霏。","憂花惜月長如此，爭得東陽病骨肥。"]', '["蒼野迷云黯不归，远风吹雨入巖扉。","石牀潤極琴絲緩，水閣寒多酒力微。","夕梦將成還滴滴，春心欲斷正霏霏。","憂花惜月长如此，爭得东陽病骨肥。"]', '诗', 'shi', '', NULL, '次韻和朱況雨中之什 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6005f1-54ef-42f5-9fd7-859d7ae6b45d', '感舊', '感旧', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["千里青雲未致身，馬蹄空踏幾年塵。","曾迷玉洞花光老，欲過金城柳眼新。","粉壁已沈題鳳字，酒壚猶記姓黃人。","塢中橫笛偏多感，一涕闌干白角巾。"]', '["千里青云未致身，马蹄空踏幾年塵。","曾迷玉洞花光老，欲過金城柳眼新。","粉壁已沈題鳳字，酒壚猶記姓黄人。","塢中橫笛偏多感，一涕闌干白角巾。"]', '诗', 'shi', '', NULL, '感舊 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dc1d189-6f69-4723-9aae-a49cbb1575f4', '城南', '城南', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["昨夜輕陰結夕霏，城南十里有香泥。","初聞山鳥驚新哢，遙見林花識舊蹊。","蕩槳遠從芳草渡，墊巾還傍綠楊隄。","羅敷正苦桑蠶事，惆悵南來五馬蹄。"]', '["昨夜轻陰結夕霏，城南十里有香泥。","初闻山鸟驚新哢，遙见林花識旧蹊。","蕩槳远從芳草渡，墊巾還傍綠楊隄。","羅敷正苦桑蠶事，惆悵南来五马蹄。"]', '诗', 'shi', '', NULL, '城南 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3972d5f3-df6a-4659-882a-0c525e7ba3fc', '早夏', '早夏', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["井轄投多思不禁，密垂珠箔晝沈沈。","睡驚燕語頻移枕，病起蛛絲半在琴。","雨徑亂花埋宿豔，月軒修竹轉涼陰。","一春酒費知多少，探盡囊中換賦金。"]', '["井轄投多思不禁，密垂珠箔晝沈沈。","睡驚燕語頻移枕，病起蛛絲半在琴。","雨徑亂花埋宿豔，月軒修竹轉涼陰。","一春酒費知多少，探尽囊中換賦金。"]', '诗', 'shi', '', NULL, '早夏 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1252e7e-437a-4da5-b233-ec08facccce4', '侯家', '侯家', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["洞戶春遲漏箭長，短轅初返雒陽傍。","綵雲按曲青岑醴，沈水薰衣白璧堂。","前檻蘭苕依玉樹，後園桐葉護銀牀。","宴殘紅燭長庚爛，還促朝珂謁未央。"]', '["洞戶春遲漏箭长，短轅初返雒陽傍。","綵云按曲青岑醴，沈水薰衣白璧堂。","前檻蘭苕依玉樹，後园桐葉護銀牀。","宴殘紅燭长庚爛，還促朝珂謁未央。"]', '诗', 'shi', '', NULL, '侯家 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbd42ad5-932b-4b0b-99e2-a74c27a5bdb3', '函谷關', '函谷关', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["天開函谷壯關中，萬古驚塵向此空。","望氣竟能知老子，棄繻何不識終童。","慢持白馬先生論，未抵鳴雞下客功。","符命已歸如掌地，一丸曾誤隗王東。"]', '["天开函谷壯关中，万古驚塵向此空。","望氣竟能知老子，棄繻何不識終童。","慢持白马先生論，未抵鳴雞下客功。","符命已归如掌地，一丸曾誤隗王东。"]', '诗', 'shi', '', NULL, '函谷關 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45bc85b7-5ac3-4313-b031-00742be47065', '殘花', '殘花', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["雨壓殘紅一夜凋，曉來簾外正飄搖。","數枝翠葉空相對，萬片香魂不可招。","長樂夢回春寂寂，武陵人去水迢迢。","愁將玉笛傳遺恨，苦被芳風透綺寮。"]', '["雨壓殘紅一夜凋，晓来簾外正飄搖。","數枝翠葉空相对，万片香魂不可招。","长乐梦回春寂寂，武陵人去水迢迢。","愁將玉笛傳遺恨，苦被芳风透綺寮。"]', '诗', 'shi', '', NULL, '殘花 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25066ec7-1250-4395-b4a5-429c0294da0d', '次韻徐爽見寄', '次韻徐爽见寄', '2109fcb9-db94-44d0-a59a-45522ec7a95e', '唐', '["五兩青絲帝渥深，平時可敢嘆英沈。","侏儒自是長三尺，澼絖都來直數金。","寂寞死灰人喪偶，婆娑生意樹交陰。","年來想見瓊枝色，久夢蘧蘧到竹林。"]', '["五兩青絲帝渥深，平时可敢嘆英沈。","侏儒自是长三尺，澼絖都来直數金。","寂寞死灰人喪偶，婆娑生意樹交陰。","年来想见瓊枝色，久梦蘧蘧到竹林。"]', '诗', 'shi', '', NULL, '次韻徐爽見寄 胡宿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5ebf3d8-cd1c-4527-8c41-d157fe15b680', '華清宮', '华清宮', '8b2fb737-6d2f-420e-93c1-87628c89ec0b', '唐', '["行盡江南數十程，曉星殘月入華清。","朝元閣上西風急，都入長楊作雨聲。"]', '["行尽江南數十程，晓星殘月入华清。","朝元閣上西风急，都入长楊作雨声。"]', '诗', 'shi', '', NULL, '華清宮 杜常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf02202a-3ff7-4f75-b18e-ab5c6f7dc47f', '華清宮', '华清宮', '8b2fb737-6d2f-420e-93c1-87628c89ec0b', '唐', '["一別家山十六程，曉来和月到華清。","朝元閣上西風急，都入長楊作雨聲。"]', '["一別家山十六程，晓来和月到华清。","朝元閣上西风急，都入长楊作雨声。"]', '诗', 'shi', '', NULL, '華清宮 杜常 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4910aa66-39ef-46b3-9202-fb0202d488ac', '題文川村居', '題文川村居', 'a5755444-515d-47e0-bf97-c202d2bee503', '唐', '["種茶巖接紅霞塢，灌稻泉生白石根。","皤腹老翁眉似雪，海棠花下戲兒孫。"]', '["種茶巖接紅霞塢，灌稻泉生白石根。","皤腹老翁眉似雪，海棠花下戲兒孫。"]', '诗', 'shi', '', NULL, '題文川村居 滕白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b7f1b46-e431-4fac-bf59-90fdb6d9301b', '燕', '燕', 'a5755444-515d-47e0-bf97-c202d2bee503', '唐', '["短羽新來別海陽，真珠高卷語雕梁。","佳人未必全聽爾，正把金針繡鳳凰。"]', '["短羽新来別海陽，真珠高卷語雕梁。","佳人未必全听爾，正把金針繡鳳凰。"]', '诗', 'shi', '', NULL, '燕 滕白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f5ae17d-840e-4036-a305-7c06d4f417fe', '題嚴君觀', '題嚴君观', '19354e01-2a65-4f82-af9a-1970377462df', '唐', '["寒雲古木罩星臺，凡骨仙蹤信可哀。","二十年前曾此到，一千年內未歸來。"]', '["寒云古木罩星台，凡骨仙蹤信可哀。","二十年前曾此到，一千年內未归来。"]', '诗', 'shi', '', NULL, '題嚴君觀 王嵒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9143dc9a-a4ee-447e-b5c8-d060fb2c9879', '山中有所思', '山中有所思', '19354e01-2a65-4f82-af9a-1970377462df', '唐', '["零零夜雨漬愁根，觸物傷離好斷魂。","莫怪杜鵑飛去盡，紫微花裏有啼猨。"]', '["零零夜雨漬愁根，觸物傷離好斷魂。","莫怪杜鵑飞去尽，紫微花裏有啼猨。"]', '诗', 'shi', '', NULL, '山中有所思 王嵒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c447be74-4d94-46c0-bc7f-61e8a5b73409', '燕', '燕', '19354e01-2a65-4f82-af9a-1970377462df', '唐', '["一巢功績破春光，絮落花殘兩翅狂。","月樹風枝不棲去，強來言語泥雕梁。"]', '["一巢功績破春光，絮落花殘兩翅狂。","月樹风枝不棲去，強来言語泥雕梁。"]', '诗', 'shi', '', NULL, '燕 王嵒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b13f0a3-0100-4661-abd6-6ae42d55d972', '貧女', '貧女', '19354e01-2a65-4f82-af9a-1970377462df', '唐', '["難把菱花照素顏，試臨春水插花看。","木蘭船上遊春子，笑指荆釵下遠灘。"]', '["难把菱花照素顏，試臨春水插花看。","木蘭船上游春子，笑指荆釵下远灘。"]', '诗', 'shi', '', NULL, '貧女 王嵒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f414c01-c548-442b-b737-5bf2c4bebd8b', '杪春寄友人', '杪春寄友人', '19354e01-2a65-4f82-af9a-1970377462df', '唐', '["何處相逢萬事忙，卓家樓上百淘香。","明朝漸近山僧寺，更爲殘花醉一場。"]', '["何处相逢万事忙，卓家楼上百淘香。","明朝漸近山僧寺，更爲殘花醉一場。"]', '诗', 'shi', '', NULL, '杪春寄友人 王嵒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d93c8f0-0a34-4e21-b4b5-e34e7c244019', '回舊山', '回旧山', '19354e01-2a65-4f82-af9a-1970377462df', '唐', '["庾家樓上謝家池，處處風煙少舊知。","明日落花誰共醉，野溪猨鳥恨歸遲。"]', '["庾家楼上謝家池，处处风煙少旧知。","明日落花誰共醉，野溪猨鸟恨归遲。"]', '诗', 'shi', '', NULL, '回舊山 王嵒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f0b925d-4d38-486a-b708-5e6f6d8e2962', '感巫州薺菜', '感巫州薺菜', 'aad0ea12-3a1b-43c4-8646-fa98263e9d04', '唐', '["兩京作觔賣，五谿無人采。","夷夏雖有殊，氣味都不改。"]', '["兩京作觔賣，五谿無人采。","夷夏雖有殊，氣味都不改。"]', '诗', 'shi', '', NULL, '感巫州薺菜 高力士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf729a6e-e368-4a65-affb-8bd646385303', '句', '句', 'aad0ea12-3a1b-43c4-8646-fa98263e9d04', '唐', '["煙燻眼落膜，瘴染面朱虞。"]', '["煙燻眼落膜，瘴染面朱虞。"]', '诗', 'shi', '', NULL, '句 高力士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31876e9d-837c-4b5b-9135-e00fd13ab34f', '使至灊山', '使至灊山', '056d41a9-dc53-4e1c-8896-089da0d702fc', '唐', '["碧塢煙霞晝未開，游人到處盡裴回。","憑誰借問巖前叟，曾託吾皇一夢來。"]', '["碧塢煙霞晝未开，游人到处尽裴回。","憑誰借问巖前叟，曾託吾皇一梦来。"]', '诗', 'shi', '', NULL, '使至灊山 王越賓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79a76939-637c-4985-b8ee-ec9e2c8ef62e', '和武相公中秋夜西蜀錦樓望月得清字', '和武相公中秋夜西蜀錦楼望月得清字', '9d7e25d8-ba11-4e7c-9a48-d038a2a617dd', '唐', '["德星搖此夜，珥月滿重城。","杳靄煙氛色，飄颻砧杵聲。","令行秋氣爽，樂感素風輕。","共賞千年聖，長歌四海清。"]', '["德星搖此夜，珥月满重城。","杳靄煙氛色，飄颻砧杵声。","令行秋氣爽，乐感素风轻。","共賞千年聖，长歌四海清。"]', '诗', 'shi', '', NULL, '和武相公中秋夜西蜀錦樓望月得清字 王良會 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4dfbf6c-dfce-4db0-b47f-900f03fff9f3', '星回節游避風臺與清平官賦', '星回節游避风台與清平官賦', 'b9915ee7-1016-4f89-9fd0-426455ba45eb', '唐', '["避風善闡臺，極目見藤越。","悲哉古與今，依然煙與月。","自我居震旦，翊衛類夔契。","伊昔頸皇運，艱難仰忠烈。","不覺歲云暮，感極星回節。","元昶同一心，子孫堪貽厥。"]', '["避风善闡台，極目见藤越。","悲哉古與今，依然煙與月。","自我居震旦，翊衛類夔契。","伊昔頸皇運，艱难仰忠烈。","不覺歲云暮，感極星回節。","元昶同一心，子孫堪貽厥。"]', '诗', 'shi', '', NULL, '星回節游避風臺與清平官賦 南詔驃信 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b08e85f-3ce5-4ee7-b632-ebeb3911d3a0', '星回節避風臺驃信命賦', '星回節避风台驃信命賦', '77bc048a-b41f-4bc7-a117-da2d70cd39b5', '唐', '["法駕避星回，波羅毘勇猜。","河潤冰難合，地暖梅先開。","下令俚柔洽，獻賝弄棟來。","願將不才質，千載侍游臺。"]', '["法駕避星回，波羅毘勇猜。","河潤冰难合，地暖梅先开。","下令俚柔洽，獻賝弄棟来。","願將不才質，千載侍游台。"]', '诗', 'shi', '', NULL, '星回節避風臺驃信命賦 趙叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66fe78b8-9324-481d-8134-4be027e7c882', '途中詩', '途中诗', 'b5c0b21e-517c-4c29-979d-a8177925fb64', '唐', '["□□□□□□□，□□□□□□□。","風裏浪花吹更白，雨中山色洗還青。","海鷗聚處窗前見，林狖啼時枕上聽。","此際自然無限趣，王程不敢暫留停。"]', '["□□□□□□□，□□□□□□□。","风裏浪花吹更白，雨中山色洗還青。","海鷗聚处窗前见，林狖啼时枕上听。","此際自然無限趣，王程不敢暫留停。"]', '诗', 'shi', '', NULL, '途中詩 楊奇鯤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ddc5d05-2e72-45d1-b682-97ff77cc44d9', '聽妓洞雲歌', '听妓洞云歌', '358fa76d-b52e-4bbb-a98e-e327205d1f9c', '唐', '["嵇叔夜，鼓琴飲酒無閑暇。","若使當時聞此歌，拋擲廣陵都不藉。","劉伯倫，虛生浪死過青春。","一飲一碩猶自醉，無人爲爾卜深塵。"]', '["嵇叔夜，鼓琴饮酒無闲暇。","若使當时闻此歌，拋擲廣陵都不藉。","劉伯倫，虛生浪死過青春。","一饮一碩猶自醉，無人爲爾卜深塵。"]', '诗', 'shi', '', NULL, '聽妓洞雲歌 布燮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('568b053f-50f2-4f54-8366-1bcbf56bd56a', '思鄉作', '思乡作', '358fa76d-b52e-4bbb-a98e-e327205d1f9c', '唐', '["瀘北行人絕，雲南信未還。","庭前花不埽，門外柳誰攀。","坐久銷銀燭，愁多減玉顏。","懸心秋夜月，萬里照關山。"]', '["瀘北行人絕，云南信未還。","庭前花不埽，门外柳誰攀。","坐久銷銀燭，愁多減玉顏。","懸心秋夜月，万里照关山。"]', '诗', 'shi', '', NULL, '思鄉作 布燮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2146f106-49cf-4481-9520-a3b06c55fb08', '銜命還國作', '銜命還国作', '87267fcd-e8dc-475a-aac1-ee59a0b07ac1', '唐', '["銜命將辭國，非才忝侍臣。","天中戀明主，海外憶慈親。","伏奏違金闕，騑驂去玉津。","蓬萊鄉路遠，若木故園林。","西望懷恩日，東歸感義辰。","平生一寶劒，留贈結交人。"]', '["銜命將辞国，非才忝侍臣。","天中戀明主，海外憶慈親。","伏奏違金闕，騑驂去玉津。","蓬萊乡路远，若木故园林。","西望懷恩日，东归感義辰。","平生一寶劒，留贈結交人。"]', '诗', 'shi', '', NULL, '銜命還國作 朝衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('887e37c0-7878-4078-9f37-f30c0b85d5e8', '繡袈裟衣緣', '繡袈裟衣緣', '1ac8d077-f2f4-47b5-b3c9-bf9d8e2f0f1f', '唐', '["山川異域，風月同天。","寄諸佛子，共結來緣。"]', '["山川異域，风月同天。","寄諸佛子，共結来緣。"]', '诗', 'shi', '', NULL, '繡袈裟衣緣 長屋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01813f10-27a6-49e9-9ba4-18a75b8b31fe', '憤怨詩', '憤怨诗', 'bfb0e70a-ca51-450c-b24b-a6753a90197c', '唐', '["于公慟哭三年旱，鄒衍含愁五月霜。","今我幽愁還似古，皇天無語但蒼蒼。"]', '["于公慟哭三年旱，鄒衍含愁五月霜。","今我幽愁還似古，皇天無語但蒼蒼。"]', '诗', 'shi', '', NULL, '憤怨詩 王巨仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6de2910-2263-43e1-a829-33c2e458a434', '立木海上刻詩', '立木海上刻诗', '40a695fa-e897-430c-9577-cf87b5db42d2', '唐', '["小山壓大山，大山全無力。","羞見故鄉人，從此投外國。"]', '["小山壓大山，大山全無力。","羞见故乡人，從此投外国。"]', '诗', 'shi', '', NULL, '立木海上刻詩 李贊華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3107d287-37fc-4d27-8ac8-a6ac2c890014', '戲語', '戲語', '0c3fbc1a-0719-4d25-8362-998ac83f832b', '唐', '["秦地城池二百年，何期如此賤田園。","一頃麥苗碩伍米，三間堂屋二千錢。"]', '["秦地城池二百年，何期如此賤田园。","一頃麦苗碩伍米，三间堂屋二千錢。"]', '诗', 'shi', '', NULL, '戲語 成輔端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23a35503-2f15-45a3-a46e-54f189b1ab4d', '萬壽寺歌詞', '万壽寺歌词', 'de96f500-283c-4616-a0d1-e72509a62584', '唐', '["位乖燮理致傷殘，四面牆匡不忍看。","正是花時堪下淚，相公何必更追歡。"]', '["位乖燮理致傷殘，四面牆匡不忍看。","正是花时堪下泪，相公何必更追歡。"]', '诗', 'shi', '', NULL, '萬壽寺歌詞 張隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2a54f85-16d9-4b63-9465-13d497558ce3', '迎孫刺史', '迎孫刺史', 'dfe4acf6-9f95-4665-b87e-841bfd564ade', '唐', '["昔日郎君今刺史，朱元依舊守朱門。","今朝竹馬諸童子，盡是當時竹馬孫。"]', '["昔日郎君今刺史，朱元依旧守朱门。","今朝竹马諸童子，尽是當时竹马孫。"]', '诗', 'shi', '', NULL, '迎孫刺史 朱元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de3b5f15-1a1d-423e-b3b0-aa612e693247', '臨刑詩', '臨刑诗', '48bb2b9b-4149-4a36-84f8-bd11b872e5ca', '唐', '["積玉堆金官又崇，禍來倏忽變成空。","五年榮貴今何在，不異南柯一夢中。"]', '["積玉堆金官又崇，禍来倏忽变成空。","五年榮貴今何在，不異南柯一梦中。"]', '诗', 'shi', '', NULL, '臨刑詩 陳璠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b300ad66-301d-4b9a-b903-63a1350010d3', '詩', '诗', 'c9c76a36-33d8-4c16-a485-a694363eef3e', '唐', '["青鳥銜葡萄，飛上金井欄。","美人恐驚去，不敢捲簾看。"]', '["青鸟銜葡萄，飞上金井欄。","美人恐驚去，不敢捲簾看。"]', '诗', 'shi', '', NULL, '詩 捧劒僕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('955572f1-5c58-4f75-958a-ae824f049a8c', '題牡丹', '題牡丹', 'c9c76a36-33d8-4c16-a485-a694363eef3e', '唐', '["一種芳菲出後庭，却輸桃李得佳名。","誰能爲向天人說，從此移根近太清。"]', '["一種芳菲出後庭，却輸桃李得佳名。","誰能爲向天人说，從此移根近太清。"]', '诗', 'shi', '', NULL, '題牡丹 捧劒僕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbdcc1a3-f685-483d-bba4-ec8ca33802dc', '將竄留詩', '將竄留诗', 'c9c76a36-33d8-4c16-a485-a694363eef3e', '唐', '["珍重郭四郎，臨行不得別。","曉漏動離心，輕車冒殘雪。","欲出主人門，零涕暗嗚咽。","萬里隔關山，一心思漢月。"]', '["珍重郭四郎，臨行不得別。","晓漏动離心，轻车冒殘雪。","欲出主人门，零涕暗嗚咽。","万里隔关山，一心思漢月。"]', '诗', 'shi', '', NULL, '將竄留詩 捧劒僕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1010f9b1-01b2-44a9-a499-ecc0dad48405', '淮陽感懷', '淮陽感懷', '1fccc8e1-ef90-40bb-845e-224b3beaa74e', '唐', '["金風蕩初節，玉露凋晚林。","此夕窮塗士，鬱陶傷寸心。","野平葭葦合，村荒藜藿深。","眺聽良多感，徙倚獨霑襟。","霑襟何所爲，悵然懷古意。","秦俗猶未平，漢道將何翼。","樊噲市井徒，蕭何刀筆吏。","一朝時運會，千古傳名諡。","寄言世上雄，虛生真可媿。"]', '["金风蕩初節，玉露凋晚林。","此夕窮塗士，鬱陶傷寸心。","野平葭葦合，村荒藜藿深。","眺听良多感，徙倚独霑襟。","霑襟何所爲，悵然懷古意。","秦俗猶未平，漢道將何翼。","樊噲市井徒，蕭何刀笔吏。","一朝时運會，千古傳名諡。","寄言世上雄，虛生真可媿。"]', '诗', 'shi', '', NULL, '淮陽感懷 李密 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3299eb9b-32bb-4bfc-862b-7c577921db27', '南隱遊泉山', '南隐游泉山', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["名山狎招隱，俗外遠相求。","還如倒景望，忽似閬風遊。","臨崖俯大壑，披霧仰飛流。","歲積松方偃，年深椿欲秋。","野花開石鏡，雲葉掩山樓。","何須問方士，此處即瀛洲。"]', '["名山狎招隐，俗外远相求。","還如倒景望，忽似閬风游。","臨崖俯大壑，披霧仰飞流。","歲積松方偃，年深椿欲秋。","野花开石镜，云葉掩山楼。","何須问方士，此处即瀛洲。"]', '诗', 'shi', '', NULL, '南隱遊泉山 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c266c8b-bb64-4902-87c7-c2e405588092', '行經太華', '行經太华', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["紛吾世網暇，靈岳展幽尋。","寥廊風塵遠，杳冥川谷深。","山昏五里霧，日落二華陰。","疎峰起蓮葉，危塞隱桃林。","何必東都外，此處可抽簪。"]', '["紛吾世網暇，靈岳展幽尋。","寥廊风塵远，杳冥川谷深。","山昏五里霧，日落二华陰。","疎峰起蓮葉，危塞隐桃林。","何必东都外，此处可抽簪。"]', '诗', 'shi', '', NULL, '行經太華 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96978520-b66d-433a-82bb-0b54fc559183', '夜宿荒村', '夜宿荒村', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["綿綿夕漏深，客恨轉傷心。","撫弦無人聽，對酒時獨斟。","故鄉萬里絕，窮愁百慮侵。","秋草思邊馬，遶枝驚夜禽。","風度谷餘響，月斜山半陰。","勞歌欲敘意，終是白頭吟。"]', '["綿綿夕漏深，客恨轉傷心。","撫弦無人听，对酒时独斟。","故乡万里絕，窮愁百慮侵。","秋草思邊马，遶枝驚夜禽。","风度谷餘响，月斜山半陰。","勞歌欲敘意，終是白头吟。"]', '诗', 'shi', '', NULL, '夜宿荒村 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8789dec-8a0f-4334-abca-5e4622a6f70b', '王澤嶺遭洪水', '王澤嶺遭洪水', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["地籟風聲急，天津雲色愁。","悠然萬頃滿，俄爾百川浮。","遠似金堤溢，翻如碧海流。","驚濤遙起鷺，迴岸不分牛。","徒知懷趙景，終是倦陽侯。","木梗誠無託，蘆灰豈暇求。","思得乘槎便，蕭然河漢遊。"]', '["地籟风声急，天津云色愁。","悠然万頃满，俄爾百川浮。","远似金堤溢，翻如碧海流。","驚濤遙起鷺，迴岸不分牛。","徒知懷趙景，終是倦陽侯。","木梗誠無託，蘆灰豈暇求。","思得乘槎便，蕭然河漢游。"]', '诗', 'shi', '', NULL, '王澤嶺遭洪水 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f4c09bc-65c6-4f17-a7be-a5d6359c747b', '登白馬山護明寺', '登白马山護明寺', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["名岳標形勝，危峰遠鬱紆。","成象建環極，大壯闡規模。","層臺從靈鷲，高殿邇陽烏。","暫同遊閬苑，還類入仙都。","三休開碧嶺，萬戶洞金鋪。","攝心罄前禮，訪道挹中虛。","遙瞻盡地軸，長望極天隅。","白雲起梁棟，丹霞映栱櫨。","露花疑濯錦，泉月似沈珠。","今日桃源客，相顧失歸塗。"]', '["名岳標形勝，危峰远鬱紆。","成象建环極，大壯闡規模。","層台從靈鷲，高殿邇陽烏。","暫同游閬苑，還類入仙都。","三休开碧嶺，万戶洞金鋪。","攝心罄前禮，訪道挹中虛。","遙瞻尽地軸，长望極天隅。","白云起梁棟，丹霞映栱櫨。","露花疑濯錦，泉月似沈珠。","今日桃源客，相顧失归塗。"]', '诗', 'shi', '', NULL, '登白馬山護明寺 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a74c09-0fb7-4705-973d-eba7241be475', '送舍利宿定普巖', '送舍利宿定普巖', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["仁祠表虛曠，祗園展肅恭。","棲息翠微嶺，登頓白雲峰。","映流看夜月，臨峰聽曉鐘。","澗芳十步草，崖陰百丈松。","蕭然遙路絕，無復市朝蹤。"]', '["仁祠表虛曠，祗园展肅恭。","棲息翠微嶺，登頓白云峰。","映流看夜月，臨峰听晓鐘。","澗芳十步草，崖陰百丈松。","蕭然遙路絕，無复市朝蹤。"]', '诗', 'shi', '', NULL, '送舍利宿定普巖 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d2b797e-4492-4bf5-80f2-41963cf4e5ef', '觀太常奏新樂', '观太常奏新乐', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["大君膺寶曆，出豫表功成。","鈞天金石響，洞庭弦管清。","八音動繁會，九變叶希聲。","和雲留睿賞，熏風悅聖情。","盛烈光韶濩，易俗邁咸英。","竊吹良無取，率舞抃羣生。"]', '["大君膺寶曆，出豫表功成。","鈞天金石响，洞庭弦管清。","八音动繁會，九变叶希声。","和云留睿賞，熏风悅聖情。","盛烈光韶濩，易俗邁咸英。","竊吹良無取，率舞抃羣生。"]', '诗', 'shi', '', NULL, '觀太常奏新樂 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('861d5fd9-d498-4beb-b16e-4a4a9e15bea1', '賦得涉江采芙蓉', '賦得涉江采芙蓉', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["蓮舟泛錦磧，極目眺江干。","沿流渡檝易，逆浪取花難。","有霧疑川廣，無風見水寬。","朝來採摘倦，詎得久盤桓。"]', '["蓮舟泛錦磧，極目眺江干。","沿流渡檝易，逆浪取花难。","有霧疑川廣，無风见水寬。","朝来採摘倦，詎得久盤桓。"]', '诗', 'shi', '', NULL, '賦得涉江采芙蓉 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3797664-352d-40cd-b10a-1adb0947710f', '賦得華亭鶴', '賦得华亭鹤', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["華亭失侶鶴，乘軒寵遂終。","三山凌苦霧，千里激悲風。","心危白露下，聲斷綵弦中。","何言斯物變，翻復似遼東。"]', '["华亭失侶鹤，乘軒寵遂終。","三山凌苦霧，千里激悲风。","心危白露下，声斷綵弦中。","何言斯物变，翻复似遼东。"]', '诗', 'shi', '', NULL, '賦得華亭鶴 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48543b6f-b767-4421-b93f-60070e0c4ec6', '送蔡君知入蜀二首 一', '送蔡君知入蜀二首 一', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["金陵已去國，銅梁忽背飛。","失路遠相送，他鄉何日歸。"]', '["金陵已去国，銅梁忽背飞。","失路远相送，他乡何日归。"]', '诗', 'shi', '', NULL, '送蔡君知入蜀二首 一 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71b1b257-1bc0-4a62-9c19-dbdd25c86910', '送蔡君知入蜀二首 二', '送蔡君知入蜀二首 二', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["靈關九折險，蜀道二星遙。","乘槎若有便，希泛廣陵潮。"]', '["靈关九折險，蜀道二星遙。","乘槎若有便，希泛廣陵潮。"]', '诗', 'shi', '', NULL, '送蔡君知入蜀二首 二 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afb9c85b-d867-4bda-8c84-516d90b554e0', '落葉', '落葉', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["早秋驚葉落，飄零似客心。","翻飛未肯下，猶言惜故林。"]', '["早秋驚葉落，飄零似客心。","翻飞未肯下，猶言惜故林。"]', '诗', 'shi', '', NULL, '落葉 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0913c25-e918-4952-b798-44f0a09389cf', '句', '句', '6812090d-0daa-4f9d-942c-4114faed0a18', '唐', '["誰分菱花影，還看蓬鬢秋。"]', '["誰分菱花影，還看蓬鬢秋。"]', '诗', 'shi', '', NULL, '句 孔德紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('209365b3-4cbc-430d-987a-056b27ce10b0', '臨刑詩', '臨刑诗', '2750278a-27ee-4667-8bcc-f22cbd2df2a0', '唐', '["幻生還幻滅，大幻莫過身。","安心自有處，求人無有人。"]', '["幻生還幻滅，大幻莫過身。","安心自有处，求人無有人。"]', '诗', 'shi', '', NULL, '臨刑詩 鄭頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab76c0fc-144b-4884-a054-efec2987e260', '和謁孔子廟', '和謁孔子廟', 'a1c8b208-0c11-4848-aed0-ed264aafd373', '唐', '["性與雖天縱，主世乃無由。","何言泰山毀，空驚逝水流。","及門思往烈，入室想前修。","寂寞荒堦暮，摧殘古木秋。","遺風曖如此，聊以慰蒸求。"]', '["性與雖天縱，主世乃無由。","何言泰山毀，空驚逝水流。","及门思往烈，入室想前修。","寂寞荒堦暮，摧殘古木秋。","遺风曖如此，聊以慰蒸求。"]', '诗', 'shi', '', NULL, '和謁孔子廟 劉斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0412bbd4-4dcc-42dd-95d2-40c53e1ef120', '和許給事傷牛尚書', '和許給事傷牛尚书', 'a1c8b208-0c11-4848-aed0-ed264aafd373', '唐', '["名臣不世出，百工之所求。","況乃非常器，遭逢興運秋。","符彩照千里，銓衡綜九流。","經綸資百物，樽俎寄皇猷。","韶濩傾復理，典禮紊還修。","雖貞棟梁任，兼好藝文游。","佇聞和鼎實，行當奉介丘。","高衢翻稅駕，閱水遽遷舟。","傳呼更何日，曳履聞無由。","歸魂藐脩路，征櫂艤邗溝。","林薄長風慘，江上寒雲愁。","夜臺終不曙，遺芳徒自留。"]', '["名臣不世出，百工之所求。","況乃非常器，遭逢兴運秋。","符彩照千里，銓衡綜九流。","經綸資百物，樽俎寄皇猷。","韶濩傾复理，典禮紊還修。","雖貞棟梁任，兼好藝文游。","佇闻和鼎實，行當奉介丘。","高衢翻稅駕，閱水遽遷舟。","傳呼更何日，曳履闻無由。","归魂藐脩路，征櫂艤邗溝。","林薄长风慘，江上寒云愁。","夜台終不曙，遺芳徒自留。"]', '诗', 'shi', '', NULL, '和許給事傷牛尚書 劉斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9971af6-ff43-4a0c-9659-c4690ea261fd', '送劉散員同賦陳思王詩得好鳥鳴高枝', '送劉散員同賦陳思王诗得好鸟鳴高枝', 'a1c8b208-0c11-4848-aed0-ed264aafd373', '唐', '["春林已自好，時鳥復和鳴。","枝交難奮翼，谷靜易流聲。","間關纔得性，[矰]繳遽相驚。","安知背飛遠，拂霧獨晨征。"]', '["春林已自好，时鸟复和鳴。","枝交难奮翼，谷静易流声。","间关纔得性，[矰]繳遽相驚。","安知背飞远，拂霧独晨征。"]', '诗', 'shi', '', NULL, '送劉散員同賦陳思王詩得好鳥鳴高枝 劉斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83f4859-18c6-481b-b9ef-5aef52e35602', '詠山', '詠山', 'a1c8b208-0c11-4848-aed0-ed264aafd373', '唐', '["靈山峙千仞，蔽日且嵯峨。","紫蓋雲陰遠，香爐煙氣多。","石梁高鳥路，瀑水近天河。","欲知聞道里，別自有仙歌。"]', '["靈山峙千仞，蔽日且嵯峨。","紫蓋云陰远，香爐煙氣多。","石梁高鸟路，瀑水近天河。","欲知闻道里，別自有仙歌。"]', '诗', 'shi', '', NULL, '詠山 劉斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77ec8e4f-8eba-49b9-8ae3-f5e9925f44d8', '登樓望月二首 一', '登楼望月二首 一', 'a1c8b208-0c11-4848-aed0-ed264aafd373', '唐', '["圓月當新霽，高樓見最明。","素波流粉壁，丹桂拂飛甍。","下瞰千門靜，旁觀萬象生。","梧桐窗下影，鳥鵲檻前聲。","嘯逸劉琨興，吟資庾亮情。","遊人莫登眺，迢遞故鄉程。"]', '["圓月當新霽，高楼见最明。","素波流粉壁，丹桂拂飞甍。","下瞰千门静，旁观万象生。","梧桐窗下影，鸟鵲檻前声。","嘯逸劉琨兴，吟資庾亮情。","游人莫登眺，迢遞故乡程。"]', '诗', 'shi', '', NULL, '登樓望月二首 一 劉斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bb587ba-21d0-4437-a519-6bc7a7317fa0', '登樓望月二首 二', '登楼望月二首 二', 'a1c8b208-0c11-4848-aed0-ed264aafd373', '唐', '["皎潔三秋月，巍峨百丈樓。","下分征客路，上有美人愁。","帳卷芙蓉帶，簾褰玳瑁鉤。","倚窗情渺渺，憑檻思悠悠。","末得金波轉，俄成玉筯流。","不堪三五夕，夫壻在邊州。"]', '["皎潔三秋月，巍峨百丈楼。","下分征客路，上有美人愁。","帳卷芙蓉带，簾褰玳瑁鉤。","倚窗情渺渺，憑檻思悠悠。","末得金波轉，俄成玉筯流。","不堪三五夕，夫壻在邊州。"]', '诗', 'shi', '', NULL, '登樓望月二首 二 劉斌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0939af03-3cbb-4f62-bbcf-d5dcaed9c2ea', '題菊花', '題菊花', 'a062b987-27d8-4706-acac-8707dd87cd89', '唐', '["颯颯西風滿院栽，蘂寒香冷蝶難來。","他年我若爲青帝，報與桃花一處開。"]', '["颯颯西风满院栽，蘂寒香冷蝶难来。","他年我若爲青帝，報與桃花一处开。"]', '诗', 'shi', '', NULL, '題菊花 黃巢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a38ccaa-e3e3-4920-9f22-3a686c934000', '不第後賦菊', '不第後賦菊', 'a062b987-27d8-4706-acac-8707dd87cd89', '唐', '["待到秋來九月八，我花開後百花殺。","衝天香陣透長安，滿城盡帶黃金甲。"]', '["待到秋来九月八，我花开後百花殺。","衝天香陣透长安，满城尽带黄金甲。"]', '诗', 'shi', '', NULL, '不第後賦菊 黃巢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e90727d6-db93-49ba-8850-13629dcec59a', '自題像', '自題像', 'a062b987-27d8-4706-acac-8707dd87cd89', '唐', '["記得當年草上飛，鐵衣著盡著僧衣。","天津橋上無人識，獨倚欄干看落暉。"]', '["記得當年草上飞，鐵衣著尽著僧衣。","天津橋上無人識，独倚欄干看落暉。"]', '诗', 'shi', '', NULL, '自題像 黃巢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af71473-30cc-45f1-bbf5-dbc548c8a611', '柳', '柳', 'a14517f7-62ed-4099-83d0-ed84131af31f', '唐', '["妝點青春更有誰，青春常許占先知。","亞夫營畔風輕處，元亮門前日暖時。","花密宛如飄六出，葉繁何惜借雙眉。","交情別緒論多少，好向仁人贈一枝。"]', '["妝点青春更有誰，青春常許占先知。","亞夫營畔风轻处，元亮门前日暖时。","花密宛如飄六出，葉繁何惜借雙眉。","交情別緒論多少，好向仁人贈一枝。"]', '诗', 'shi', '', NULL, '柳 羅紹威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94f6a5a6-3e3a-49cb-98ad-06e288f3ca3f', '白菊', '白菊', 'a14517f7-62ed-4099-83d0-ed84131af31f', '唐', '["雖被風霜競欲催，皎然顏色不低摧。","已疑素手能妝出，又似金錢未染來。","香散自宜飄淥酒，葉交仍得蔭蒼苔。","尋思閉戶中宵見，應認寒窗雪一堆。"]', '["雖被风霜競欲催，皎然顏色不低摧。","已疑素手能妝出，又似金錢未染来。","香散自宜飄淥酒，葉交仍得蔭蒼苔。","尋思閉戶中宵见，應認寒窗雪一堆。"]', '诗', 'shi', '', NULL, '白菊 羅紹威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d492634f-f9c7-460d-ac55-940178c624a2', '句', '句', 'a14517f7-62ed-4099-83d0-ed84131af31f', '唐', '["樓前澹澹雲頭日，簾外蕭蕭雨脚風。"]', '["楼前澹澹云头日，簾外蕭蕭雨脚风。"]', '诗', 'shi', '', NULL, '句 羅紹威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37f35117-c17b-469d-b3aa-9774e47ef532', '清明登奉先城樓', '清明登奉先城楼', '072120df-54f7-409f-9e46-33227c1b44d0', '唐', '["年來年去只艱危，春半堯山草尚衰。","四海清平耆舊見，五陵寒食小臣悲。","煙銷井邑隈樓檻，雪滿川原泥酒巵。","拭盡賈生無限淚，一行歸雁遠參差。"]', '["年来年去只艱危，春半堯山草尚衰。","四海清平耆旧见，五陵寒食小臣悲。","煙銷井邑隈楼檻，雪满川原泥酒巵。","拭尽賈生無限泪，一行归雁远參差。"]', '诗', 'shi', '', NULL, '清明登奉先城樓 羅衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5932ce9-aae5-4200-ab22-d88fc81e7d96', '清明赤水寺居', '清明赤水寺居', '072120df-54f7-409f-9e46-33227c1b44d0', '唐', '["榆火輕煙處處新，旋從閑望到諸鄰。","浮生浮世祗多事，野水野花娛病身。","濁酒不禁雲外景，碧峰猶冷寺前春。","蓑衣毳衲誠吾黨，自結村園一社貧。"]', '["榆火轻煙处处新，旋從闲望到諸鄰。","浮生浮世祗多事，野水野花娛病身。","濁酒不禁云外景，碧峰猶冷寺前春。","蓑衣毳衲誠吾黨，自結村园一社貧。"]', '诗', 'shi', '', NULL, '清明赤水寺居 羅衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4602a50-d302-413b-9fca-07c7aeb05f9c', '贈羅隱', '贈羅隐', '072120df-54f7-409f-9e46-33227c1b44d0', '唐', '["平日時風好涕流，讒書雖盛一名休。","寰區歎屈瞻天問，夷貊聞詩過海求。","向夕便思青瑣拜，近年尋伴赤松遊。","何當世祖從人望，早以公台命卓侯。"]', '["平日时风好涕流，讒书雖盛一名休。","寰區歎屈瞻天问，夷貊闻诗過海求。","向夕便思青瑣拜，近年尋伴赤松游。","何當世祖從人望，早以公台命卓侯。"]', '诗', 'shi', '', NULL, '贈羅隱 羅衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4e53053-451e-4a40-9997-e879e4d8df66', '哭趙州和尚二首 一', '哭趙州和尚二首 一', '283bf1d8-180b-49c2-82e7-db7f944f1817', '唐', '["師離㴲水動王侯，心印光潛麈尾收。","碧落霧霾松嶺月，滄溟浪覆濟人舟。","一燈乍滅波旬喜，雙眼重昏道侶愁。","縱是了然雲外客，每瞻缾几淚還流。"]', '["師離㴲水动王侯，心印光潛麈尾收。","碧落霧霾松嶺月，滄溟浪覆濟人舟。","一灯乍滅波旬喜，雙眼重昏道侶愁。","縱是了然云外客，每瞻缾几泪還流。"]', '诗', 'shi', '', NULL, '哭趙州和尚二首 一 王鎔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d894a481-af39-4b7d-9e5a-2aa62aa71dd5', '哭趙州和尚二首 二', '哭趙州和尚二首 二', '283bf1d8-180b-49c2-82e7-db7f944f1817', '唐', '["佛日西傾祖印隳，珠沈丹沼月沈輝。","影敷丈室爐煙慘，風起禪堂松韻微。","隻履乍來留化跡，五天何處又逢歸。","解空弟子絕悲喜，猶自潸然對雪幃。"]', '["佛日西傾祖印隳，珠沈丹沼月沈輝。","影敷丈室爐煙慘，风起禪堂松韻微。","隻履乍来留化跡，五天何处又逢归。","解空弟子絕悲喜，猶自潸然对雪幃。"]', '诗', 'shi', '', NULL, '哭趙州和尚二首 二 王鎔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('272300a0-b692-4c21-a18c-3ed56547c867', '荅同年李昉見贈次韻', '荅同年李昉见贈次韻', 'fba9c66d-a391-4983-a736-90ff7066f736', '唐', '["詞場幾度讓長鞭，又向清朝賀九遷。","品秩雖然殊此日，歲寒終不改當年。","馳名早已超三院，侍直仍忻步八磚。","今日相逢翻自媿，閑吟對酒倍潸然。"]', '["词場幾度讓长鞭，又向清朝賀九遷。","品秩雖然殊此日，歲寒終不改當年。","驰名早已超三院，侍直仍忻步八磚。","今日相逢翻自媿，闲吟对酒倍潸然。"]', '诗', 'shi', '', NULL, '荅同年李昉見贈次韻 鄧洵美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0522e427-d0fd-4297-b951-b49d6fecb260', '除夜長安作', '除夜长安作', '4a62416e-ec40-47a2-883d-16c1a3274329', '唐', '["長安朔風起，窮巷掩雙扉。","新歲明朝是，故鄉何路歸。","鬢絲饒鏡色，隙雪奪燈輝。","却羨秦州雁，逢春盡北飛。"]', '["长安朔风起，窮巷掩雙扉。","新歲明朝是，故乡何路归。","鬢絲饒镜色，隙雪奪灯輝。","却羨秦州雁，逢春尽北飞。"]', '诗', 'shi', '', NULL, '除夜長安作 李京 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de02ac5-cdd6-497f-8b77-4857a3567202', '登嶺望', '登嶺望', '045d4d85-337a-47e7-81ec-4142469c0902', '唐', '["淼淼三江水，悠悠五嶺關。","雁飛猶不度，人去若爲還。"]', '["淼淼三江水，悠悠五嶺关。","雁飞猶不度，人去若爲還。"]', '诗', 'shi', '', NULL, '登嶺望 許鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dac9f65e-2498-4818-8ec7-61e0594493a7', '㟧嶺四望', '㟧嶺四望', '045d4d85-337a-47e7-81ec-4142469c0902', '唐', '["漢家仙仗在咸陽，洛水東流出建章。","野老至今猶望辛，離宮秋樹獨蒼蒼。"]', '["漢家仙仗在咸陽，洛水东流出建章。","野老至今猶望辛，離宮秋樹独蒼蒼。"]', '诗', 'shi', '', NULL, '㟧嶺四望 許鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b51815e-1a80-46ec-adb5-fd0c03e11c71', '官左拾遺歸隱作', '官左拾遺归隐作', '32f6a45e-ab0e-4b2a-af48-6497d32e4f1a', '唐', '["汨沒朝班媿不才，誰能低折向塵埃。","青山得去且歸去，官職有來還自來。"]', '["汨沒朝班媿不才，誰能低折向塵埃。","青山得去且归去，官職有来還自来。"]', '诗', 'shi', '', NULL, '官左拾遺歸隱作 王易簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f2ca905-f6f9-430a-9d92-98842e2cd081', '悼楊氏妓琴弦', '悼楊氏妓琴弦', '3c88a1f3-5297-4712-9249-de88c752b884', '唐', '["魂歸寥廊魄歸泉，只住人間十五年。","昨日施僧裙帶上，斷腸猶繫琵琶弦。"]', '["魂归寥廊魄归泉，只住人间十五年。","昨日施僧裙带上，斷腸猶繫琵琶弦。"]', '诗', 'shi', '', NULL, '悼楊氏妓琴弦 朱褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('483abfe4-ae97-42bb-a0f8-c92752d51df3', '公子行', '公子行', 'c018fc2a-1fdb-4a62-a894-f62bb5bbfb7a', '唐', '["春草綠綿綿，驕驂驟煖煙。","微風飄樂韻，半日醉花邊。","打鵲拋金盞，招人舉玉鞭。","田翁與蠶婦，平地看神仙。"]', '["春草綠綿綿，驕驂驟煖煙。","微风飄乐韻，半日醉花邊。","打鵲拋金盞，招人舉玉鞭。","田翁與蠶婦，平地看神仙。"]', '诗', 'shi', '', NULL, '公子行 黃損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b517a5c3-3975-4638-8a1f-5c51eddcd8c2', '讀史', '读史', 'c018fc2a-1fdb-4a62-a894-f62bb5bbfb7a', '唐', '["逐鹿走紅塵，炎炎火德新。","家肥生孝子，國霸有餘臣。","帝道雲龍合，民心草木春。","須知煙閣上，一半老儒真。"]', '["逐鹿走紅塵，炎炎火德新。","家肥生孝子，国霸有餘臣。","帝道云龙合，民心草木春。","須知煙閣上，一半老儒真。"]', '诗', 'shi', '', NULL, '讀史 黃損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42fab1cf-ad7f-4c48-be72-f4a1f215aca2', '出山吟', '出山吟', 'c018fc2a-1fdb-4a62-a894-f62bb5bbfb7a', '唐', '["來書初出白雲扃，乍躡秋風馬走輕。","遠近留連分岳色，別離嗚咽亂泉聲。","休將巢許爭喧雜，自共伊臯論太平。","昨夜細看雲色裏，進賢星座甚分明。"]', '["来书初出白云扃，乍躡秋风马走轻。","远近留連分岳色，別離嗚咽亂泉声。","休將巢許爭喧杂，自共伊臯論太平。","昨夜細看云色裏，進賢星座甚分明。"]', '诗', 'shi', '', NULL, '出山吟 黃損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77af18b1-1de2-4000-860f-6d6da8349e2f', '書壁', '书壁', 'c018fc2a-1fdb-4a62-a894-f62bb5bbfb7a', '唐', '["一別人間歲月多，歸來人事已銷磨。","惟有門前鑑池水，春風不改舊時波。"]', '["一別人间歲月多，归来人事已銷磨。","惟有门前鑑池水，春风不改旧时波。"]', '诗', 'shi', '', NULL, '書壁 黃損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1ffb563-e56f-46de-8667-9c6e3562b55a', '句', '句', 'c018fc2a-1fdb-4a62-a894-f62bb5bbfb7a', '唐', '["機關纔運動，勝敗便相隨。","忽遇南遷客，若爲西入心。","往來三島近，活計一囊空。","三通明主詔，一片白雲心。","掃地待明月，踏花迎野僧。","水諳彭澤闊，山憶武陵深。","金鐙冷光風宛轉，錦袍紅潤雨霏微。","高齊日月方爲道，動合乾坤始是心。","傍水野禽通體白，飣盤山菓半邊紅。","而今世上多離別，莫向相思樹下啼。"]', '["機关纔運动，勝敗便相隨。","忽遇南遷客，若爲西入心。","往来三島近，活計一囊空。","三通明主詔，一片白云心。","掃地待明月，踏花迎野僧。","水諳彭澤闊，山憶武陵深。","金鐙冷光风宛轉，錦袍紅潤雨霏微。","高齊日月方爲道，动合乾坤始是心。","傍水野禽通體白，飣盤山菓半邊紅。","而今世上多離別，莫向相思樹下啼。"]', '诗', 'shi', '', NULL, '句 黃損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('684bc1a4-1b63-497b-9df6-93e387f45752', '梁郊祀樂章 慶肅', '梁郊祀乐章 慶肅', '5af4eba8-819b-4d40-8cd5-9b31b49eaa7e', '唐', '["籩豆簠簋，黍稷非馨。","懿茲彝器，厥德惟明。","金石匏革，以和以平。","由此無疆，期乎永寧。"]', '["籩豆簠簋，黍稷非馨。","懿茲彝器，厥德惟明。","金石匏革，以和以平。","由此無疆，期乎永寧。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶肅 張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64aaf38c-58b2-4b25-a2d2-d03388c2c215', '梁郊祀樂章 慶熙', '梁郊祀乐章 慶熙', '5af4eba8-819b-4d40-8cd5-9b31b49eaa7e', '唐', '["哲后躬享，旨酒斯陳。","王恭無斁，嚴祀惟寅。","皇祖以配，大孝以振。","宜錫景福，永休下民。"]', '["哲后躬享，旨酒斯陳。","王恭無斁，嚴祀惟寅。","皇祖以配，大孝以振。","宜錫景福，永休下民。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶熙 張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02122e2d-f7f5-47b5-9e42-0924f4e45acc', '梁郊祀樂章 慶隆', '梁郊祀乐章 慶隆', '5af4eba8-819b-4d40-8cd5-9b31b49eaa7e', '唐', '["恭祀上帝，于國之陽。","爵醴是荷，鴻基永昌。"]', '["恭祀上帝，于国之陽。","爵醴是荷，鴻基永昌。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶隆 張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19ffb32-9417-4fcf-9a88-0365f13e78ba', '梁郊祀樂章 慶融', '梁郊祀乐章 慶融', '5af4eba8-819b-4d40-8cd5-9b31b49eaa7e', '唐', '["導和氣兮襲氤氳，宣皇使兮彰聖神。","服遐裔兮敷質文，格苗扈兮息煙塵。"]', '["導和氣兮襲氤氳，宣皇使兮彰聖神。","服遐裔兮敷質文，格苗扈兮息煙塵。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶融 張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf741e0-5fdc-4608-bac9-0ba36f47de03', '梁郊祀樂章 慶休', '梁郊祀乐章 慶休', '5af4eba8-819b-4d40-8cd5-9b31b49eaa7e', '唐', '["大業來四夷，仁風和萬國。","白日體無私，皇天輔有德。","七旬罪已服，六旬師方克。","偉哉帝道隆，終始常作則。"]', '["大業来四夷，仁风和万国。","白日體無私，皇天輔有德。","七旬罪已服，六旬師方克。","偉哉帝道隆，終始常作則。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶休 張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2533cef0-3afa-4c02-995d-109b62814792', '梁郊祀樂章 慶和', '梁郊祀乐章 慶和', '5af4eba8-819b-4d40-8cd5-9b31b49eaa7e', '唐', '["煙燎昇，禮容徹。","誠感達，人神悅。","靈貺彰，聖情結。","玉座寂，金罏歇。"]', '["煙燎昇，禮容徹。","誠感達，人神悅。","靈貺彰，聖情結。","玉座寂，金罏歇。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶和 張衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cbda0f3-35f6-4a45-ac70-b08a79eec38c', '梁郊祀樂章 慶和 一', '梁郊祀乐章 慶和 一', '9bbccabd-b835-44ac-8c05-c12f7bc67767', '唐', '["就陽位，昇圜丘。","佩雙玉，御大裘。","膺天命，擁神休。","萬靈感，百祿遒。"]', '["就陽位，昇圜丘。","佩雙玉，御大裘。","膺天命，擁神休。","万靈感，百祿遒。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶和 一 趙光逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d512676d-d05d-43ba-a2dc-387c41b5f8f7', '梁郊祀樂章 慶和 二', '梁郊祀乐章 慶和 二', '9bbccabd-b835-44ac-8c05-c12f7bc67767', '唐', '["秉黃鉞，建朱旗。","震八表，清二儀。","帝業顯，王道夷。","受景命，啓皇基。"]', '["秉黄鉞，建朱旗。","震八表，清二儀。","帝業显，王道夷。","受景命，啓皇基。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶和 二 趙光逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2e7e2a-c8b1-49a4-9c81-ad84d3000fa8', '梁郊祀樂章 慶和 三', '梁郊祀乐章 慶和 三', '9bbccabd-b835-44ac-8c05-c12f7bc67767', '唐', '["開九門，懷百神。","通肸蠁，接氤氳。","明粢薦，廣樂陳。","奠嘉璧，燎芳薪。"]', '["开九门，懷百神。","通肸蠁，接氤氳。","明粢薦，廣乐陳。","奠嘉璧，燎芳薪。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶和 三 趙光逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b51eef9-6a73-4e67-a878-a42ba109cb39', '梁郊祀樂章 慶和 四', '梁郊祀乐章 慶和 四', '9bbccabd-b835-44ac-8c05-c12f7bc67767', '唐', '["膺寶圖，執左契。","德應天，聖饗帝。","薦表衷，荷靈惠。","壽萬年，祚百世。"]', '["膺寶圖，執左契。","德應天，聖饗帝。","薦表衷，荷靈惠。","壽万年，祚百世。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶和 四 趙光逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d152f46d-9fa4-403d-ab40-672416710ee1', '梁郊祀樂章 慶和 五', '梁郊祀乐章 慶和 五', '9bbccabd-b835-44ac-8c05-c12f7bc67767', '唐', '["惟德動天，有感必通。","秉茲一德，禋於六宗。","欽夤寶命，恭肅禮容。","來顧來享，永穆皇風。"]', '["惟德动天，有感必通。","秉茲一德，禋於六宗。","欽夤寶命，恭肅禮容。","来顧来享，永穆皇风。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶和 五 趙光逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87792c2e-d2b7-4eac-8d2d-2aa1fa6240a2', '梁郊祀樂章 慶和 六', '梁郊祀乐章 慶和 六', '9bbccabd-b835-44ac-8c05-c12f7bc67767', '唐', '["天惟佑德，辟乃奉天。","交感斯在，昭事罔愆。","歲功已就，王道無偏。","於焉報本，是用告虔。"]', '["天惟佑德，辟乃奉天。","交感斯在，昭事罔愆。","歲功已就，王道無偏。","於焉報本，是用告虔。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶和 六 趙光逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f5202c1-6836-4721-bce6-06bdb058466b', '梁郊祀樂章 慶順', '梁郊祀乐章 慶順', '9bbccabd-b835-44ac-8c05-c12f7bc67767', '唐', '["聖皇戾止，天步舒遲。","乾乾睿相，穆穆皇儀。","進退必肅，陟降是祗。","六變克協，萬靈協隨。"]', '["聖皇戾止，天步舒遲。","乾乾睿相，穆穆皇儀。","進退必肅，陟降是祗。","六变克協，万靈協隨。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶順 趙光逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b3e7d3-dbc8-403f-80bd-432b02ac60ca', '梁郊祀樂章 慶平', '梁郊祀乐章 慶平', '9bbccabd-b835-44ac-8c05-c12f7bc67767', '唐', '["天命降鑒，帝德惟馨。","享祀不忒，禮容孔明。","奠璧布幣，薦純獻精。","神祐以荅，敷錫永寧。"]', '["天命降鑒，帝德惟馨。","享祀不忒，禮容孔明。","奠璧布幣，薦純獻精。","神祐以荅，敷錫永寧。"]', '诗', 'shi', '', NULL, '梁郊祀樂章 慶平 趙光逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a55092e8-0ff9-4291-89a9-085f5ea53724', '宮詞百首 一', '宮词百首 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["紫燎光銷大駕歸，御樓初見赭黃衣。","千聲鼓定將宣赦，竿上金雞翅欲飛。"]', '["紫燎光銷大駕归，御楼初见赭黄衣。","千声鼓定將宣赦，竿上金雞翅欲飞。"]', '诗', 'shi', '', NULL, '宮詞百首 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9962a1b2-55f8-4aac-a8f7-8150f5ea6d32', '宮詞百首 二', '宮词百首 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["北闕晴分五鳳樓，嵩山秀色護神州。","洛河自契千年運，更擬波中出九疇。"]', '["北闕晴分五鳳楼，嵩山秀色護神州。","洛河自契千年運，更擬波中出九疇。"]', '诗', 'shi', '', NULL, '宮詞百首 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d806ecc3-fec4-4995-bc77-2588deca4ba0', '宮詞百首 三', '宮词百首 三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["中興殿上曉光融，一炷天香舞瑞風。","百辟虔心齊稽首，捲簾遙見御衣紅。"]', '["中兴殿上晓光融，一炷天香舞瑞风。","百辟虔心齊稽首，捲簾遙见御衣紅。"]', '诗', 'shi', '', NULL, '宮詞百首 三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bccda39f-8653-4646-98e2-c2b1a9b699b2', '宮詞百首 四', '宮词百首 四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["日和風暖御樓時，萬姓齊瞻八彩眉。","瑞氣祥烟籠細仗，閤門宣赦四方知。"]', '["日和风暖御楼时，万姓齊瞻八彩眉。","瑞氣祥烟籠細仗，閤门宣赦四方知。"]', '诗', 'shi', '', NULL, '宮詞百首 四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d47db8c4-ad10-4c53-abc1-768716215c98', '宮詞百首 五', '宮词百首 五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["鳳吹鸞歌曉日明，豐年觀稼出神京。","封人爭獻南山壽，五色雲中御輦平。"]', '["鳳吹鸾歌晓日明，豐年观稼出神京。","封人爭獻南山壽，五色云中御輦平。"]', '诗', 'shi', '', NULL, '宮詞百首 五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bf0edf7-f8f5-4abb-84f8-b0f0adea887b', '宮詞百首 六', '宮词百首 六', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["聖主臨軒待曉時，穿花宮漏正遲遲。","雞人一唱乾坤曉，百辟分班儼羽儀。"]', '["聖主臨軒待晓时，穿花宮漏正遲遲。","雞人一唱乾坤晓，百辟分班儼羽儀。"]', '诗', 'shi', '', NULL, '宮詞百首 六 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('886a47d9-bdde-41be-a827-e2072c705f40', '宮詞百首 七', '宮词百首 七', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["朦朧西月照池亭，初夜椒房掩畫屏。","宮女相呼有何事，上樓同看老人星。"]', '["朦朧西月照池亭，初夜椒房掩畫屏。","宮女相呼有何事，上楼同看老人星。"]', '诗', 'shi', '', NULL, '宮詞百首 七 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2c40fb-62a7-43cb-b0d2-e33d11b8da9e', '宮詞百首 八', '宮词百首 八', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["紅泥椒殿綴珠璫，帳蹙金龍窣地長。","紅獸慢然天色暖，鳳爐時復爇沈香。"]', '["紅泥椒殿綴珠璫，帳蹙金龙窣地长。","紅獸慢然天色暖，鳳爐时复爇沈香。"]', '诗', 'shi', '', NULL, '宮詞百首 八 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff00e8da-9f3c-453b-9584-ae7246131fa0', '宮詞百首 九', '宮词百首 九', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["九重樓殿簇丹青，高柳含烟覆井亭。","宮內不知今日幾，自來階下數堯蓂。"]', '["九重楼殿簇丹青，高柳含烟覆井亭。","宮內不知今日幾，自来階下數堯蓂。"]', '诗', 'shi', '', NULL, '宮詞百首 九 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('798f19b6-66eb-411f-b8cc-c4c7178d47d1', '宮詞百首 十', '宮词百首 十', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["寢殿香濃玉漏嚴，雲隨涼月下西南。","帳前宮女低聲道，主上還應夢傅巖。"]', '["寢殿香濃玉漏嚴，云隨涼月下西南。","帳前宮女低声道，主上還應梦傅巖。"]', '诗', 'shi', '', NULL, '宮詞百首 十 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7133c7f-b36f-4bde-a65e-2c3096342cb5', '宮詞百首 十一', '宮词百首 十一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["遶殿鉤欄壓玉階，內人輕語凭蔥薹。","皆言明主垂衣理，不假朱雲傍檻來。"]', '["遶殿鉤欄壓玉階，內人轻語凭蔥薹。","皆言明主垂衣理，不假朱云傍檻来。"]', '诗', 'shi', '', NULL, '宮詞百首 十一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2006fd35-62b4-49e6-acd5-8fe7a8857379', '宮詞百首 十二', '宮词百首 十二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["顢頇冰面瑩池心，風刮瑤階臘雪深。","怪得宮中無獸炭，步搖釵是辟寒金。"]', '["顢頇冰面瑩池心，风刮瑤階臘雪深。","怪得宮中無獸炭，步搖釵是辟寒金。"]', '诗', 'shi', '', NULL, '宮詞百首 十二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aee17ffc-eba8-415d-b08b-c5a342f6e59c', '宮詞百首 十三', '宮词百首 十三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["蘭殿春融自靘笙，玉顏風透象紗明。","金簧如語鶯聲滑，可使雲和獨得名。"]', '["蘭殿春融自靘笙，玉顏风透象紗明。","金簧如語鶯声滑，可使云和独得名。"]', '诗', 'shi', '', NULL, '宮詞百首 十三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd4d993b-7808-418e-8725-b582e707201a', '宮詞百首 十四', '宮词百首 十四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["蘭燭時將鳳髓添，寒星遙映夜光簾。","龍樓露著鴛鴦瓦，誰近螭頭擲玉籤。"]', '["蘭燭时將鳳髓添，寒星遙映夜光簾。","龙楼露著鴛鴦瓦，誰近螭头擲玉籤。"]', '诗', 'shi', '', NULL, '宮詞百首 十四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eecfb756-93c5-41fd-b5c3-2f6cfabbca56', '宮詞百首 十五', '宮词百首 十五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["玉甃蓮池春水平，小魚雙竝錦鱗行。","內中知是黃河樣，九曲今年徹底清。"]', '["玉甃蓮池春水平，小鱼雙竝錦鱗行。","內中知是黄河樣，九曲今年徹底清。"]', '诗', 'shi', '', NULL, '宮詞百首 十五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4908530-bd4b-4664-bbf6-ec6e6cedf0f9', '宮詞百首 十六', '宮词百首 十六', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["真珠簾外靜無塵，耿耿涼天景象新。","金殿夜深銀燭晃，宮嬪來奏月重輪。"]', '["真珠簾外静無塵，耿耿涼天景象新。","金殿夜深銀燭晃，宮嬪来奏月重輪。"]', '诗', 'shi', '', NULL, '宮詞百首 十六 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f156b9f-d033-44cc-8a3b-57dc28f2a825', '宮詞百首 十七', '宮词百首 十七', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["魚犀月掌夜通頭，自著盤鶯錦臂韝。","多把沈檀配龍麝，宮中掌浸十香油。"]', '["鱼犀月掌夜通头，自著盤鶯錦臂韝。","多把沈檀配龙麝，宮中掌浸十香油。"]', '诗', 'shi', '', NULL, '宮詞百首 十七 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e545b86-8026-4d49-843d-4bb2f2d979d1', '宮詞百首 十八', '宮词百首 十八', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["香雲雙颭玉蟬輕，侍從君王苑裏行。","嘉瑞忽逢連理木，一時跪拜賀文明。"]', '["香云雙颭玉蟬轻，侍從君王苑裏行。","嘉瑞忽逢連理木，一时跪拜賀文明。"]', '诗', 'shi', '', NULL, '宮詞百首 十八 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd80718b-1764-439b-b605-7f14622de429', '宮詞百首 十九', '宮词百首 十九', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["金鸞雙立紫檀槽，暖殿無風韻自高。","含笑試彈紅蘂調，君王宣賜酪櫻桃。"]', '["金鸾雙立紫檀槽，暖殿無风韻自高。","含笑試彈紅蘂調，君王宣賜酪櫻桃。"]', '诗', 'shi', '', NULL, '宮詞百首 十九 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec9c2ae1-b5dc-4334-aea7-a3bf422a6ebf', '宮詞百首 二十', '宮词百首 二十', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["斑簟如霞可殿鋪，更開新進瑞蓮圖。","誰人築損珊瑚架，子細看時認瀝蘇。"]', '["斑簟如霞可殿鋪，更开新進瑞蓮圖。","誰人築損珊瑚架，子細看时認瀝蘇。"]', '诗', 'shi', '', NULL, '宮詞百首 二十 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4983b102-f06d-479b-b5d5-a897f19f89c1', '宮詞百首 二十一', '宮词百首 二十一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["金盆初曉洗纖纖，銀鴨香焦特地添。","出戶忽看春雪下，六宮齊捲水晶簾。"]', '["金盆初晓洗纖纖，銀鴨香焦特地添。","出戶忽看春雪下，六宮齊捲水晶簾。"]', '诗', 'shi', '', NULL, '宮詞百首 二十一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad15ec0-9b1f-4126-aa61-24a3ad2f7570', '宮詞百首 二十二', '宮词百首 二十二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["暖金盤裏點酥山，擬望君王子細看。","更向眉中分曉黛，巖邊染出碧琅玕。"]', '["暖金盤裏点酥山，擬望君王子細看。","更向眉中分晓黛，巖邊染出碧琅玕。"]', '诗', 'shi', '', NULL, '宮詞百首 二十二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55168d9-3cc8-471e-970e-c98a2c3c6139', '宮詞百首 二十三', '宮词百首 二十三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["雲母屏前繡柱衣，龍牀閑卷諫書幃。","黃金檻外螭頭活，日照紅蘭露未晞。"]', '["云母屏前繡柱衣，龙牀闲卷諫书幃。","黄金檻外螭头活，日照紅蘭露未晞。"]', '诗', 'shi', '', NULL, '宮詞百首 二十三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2be5e48-2b13-4f93-b547-f440af96ab9f', '宮詞百首 二十四', '宮词百首 二十四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["樓西殘月尚朧明，中禁雞人報曉聲。","清旦司天臺進狀，夜來晴霽泰階平。"]', '["楼西殘月尚朧明，中禁雞人報晓声。","清旦司天台進狀，夜来晴霽泰階平。"]', '诗', 'shi', '', NULL, '宮詞百首 二十四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b3da3a0-3d67-42f1-bd5a-3eb293b69c75', '宮詞百首 二十五', '宮词百首 二十五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["纖轡摩軒響佩環，銀臺門外集鴛鸞。","三鐘五鼓祥烟歛，日照仙人捧露盤。"]', '["纖轡摩軒响佩环，銀台门外集鴛鸾。","三鐘五鼓祥烟歛，日照仙人捧露盤。"]', '诗', 'shi', '', NULL, '宮詞百首 二十五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54651f4d-ed98-42fe-8cad-4a8a4d65a4c6', '宮詞百首 二十六', '宮词百首 二十六', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["司膳廚中也禁烟，春宮相對畫秋千。","清明節日頒新火，蠟炬星飛下九天。"]', '["司膳廚中也禁烟，春宮相对畫秋千。","清明節日頒新火，蠟炬星飞下九天。"]', '诗', 'shi', '', NULL, '宮詞百首 二十六 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6134b65-35e0-43e6-b8d9-ce0119906190', '宮詞百首 二十七', '宮词百首 二十七', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["宮木交芳色盡深，和風輕舞早鶯吟。","侍臣不異東方朔，應喜仙桃滿禁林。"]', '["宮木交芳色尽深，和风轻舞早鶯吟。","侍臣不異东方朔，應喜仙桃满禁林。"]', '诗', 'shi', '', NULL, '宮詞百首 二十七 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d5be5c3-d894-4148-bbf0-287feb6ecaee', '宮詞百首 二十八', '宮词百首 二十八', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["貢橘香勻䩋𩉙容，星光初滿小金籠。","近臣押賜諸王宅，拜了方開敕字封。"]', '["貢橘香勻䩋𩉙容，星光初满小金籠。","近臣押賜諸王宅，拜了方开敕字封。"]', '诗', 'shi', '', NULL, '宮詞百首 二十八 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac5aee3-394e-4bb8-b427-abe5d0206f13', '宮詞百首 二十九', '宮词百首 二十九', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["獻壽朝元欲偃戈，航深梯險競駢羅。","若論萬國來朝日，比竝塗山更較多。"]', '["獻壽朝元欲偃戈，航深梯險競駢羅。","若論万国来朝日，比竝塗山更較多。"]', '诗', 'shi', '', NULL, '宮詞百首 二十九 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f280a12-b84e-4eda-bc9d-87add378de33', '宮詞百首 三十', '宮词百首 三十', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["豔陽風景簇神州，杏蘂桃心照鳳樓。","遙望青青河畔草，幾多歸馬與休牛。"]', '["豔陽风景簇神州，杏蘂桃心照鳳楼。","遙望青青河畔草，幾多归马與休牛。"]', '诗', 'shi', '', NULL, '宮詞百首 三十 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b70481ef-25bd-4961-9ce6-2a569bcfb8ea', '宮詞百首 三十一', '宮词百首 三十一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["鑾輿觀稼晚方歸，日月旗中見御衣。","萬姓焚香惟頂禮，瑞雪隨繖入宮闈。"]', '["鑾輿观稼晚方归，日月旗中见御衣。","万姓焚香惟頂禮，瑞雪隨繖入宮闈。"]', '诗', 'shi', '', NULL, '宮詞百首 三十一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e63e56bd-a0bb-42f2-97be-597712edabea', '宮詞百首 三十二', '宮词百首 三十二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["宮庭皆應紫微垣，壯麗宸居顯至尊。","赤子顒顒瞻父母，已將仁德比乾坤。"]', '["宮庭皆應紫微垣，壯丽宸居显至尊。","赤子顒顒瞻父母，已將仁德比乾坤。"]', '诗', 'shi', '', NULL, '宮詞百首 三十二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ad589f-8ba0-4588-b5c7-c0b37f436652', '宮詞百首 三十三', '宮词百首 三十三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["三農皆已闢田疇，又見金門出土牛。","塊雨條風符聖化，嘉禾看却報新秋。"]', '["三農皆已闢田疇，又见金门出土牛。","塊雨條风符聖化，嘉禾看却報新秋。"]', '诗', 'shi', '', NULL, '宮詞百首 三十三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c9bcebb-a1b8-4d1f-b9f2-cbfcc7381246', '宮詞百首 三十四', '宮词百首 三十四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["進食門前水陸陳，大官齋潔貢時新。","明君宵旰分甘處，便索金盤賜重臣。"]', '["進食门前水陸陳，大官斋潔貢时新。","明君宵旰分甘处，便索金盤賜重臣。"]', '诗', 'shi', '', NULL, '宮詞百首 三十四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b92ceb0-5d1b-48d3-ad24-ef19494e7b61', '宮詞百首 三十五', '宮词百首 三十五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["層臺金碧惹紅霞，仙掌亭亭對月華。","昨夜盤中甘露滿，婕妤爭去奏官家。"]', '["層台金碧惹紅霞，仙掌亭亭对月华。","昨夜盤中甘露满，婕妤爭去奏官家。"]', '诗', 'shi', '', NULL, '宮詞百首 三十五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('363f0def-382a-489e-b0f5-bcbc5eae07b9', '宮詞百首 三十六', '宮词百首 三十六', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["水殿垂簾冷色凝，一牀珍簟展春冰。","才人侍立持團扇，金縷雙龍貼碧藤。"]', '["水殿垂簾冷色凝，一牀珍簟展春冰。","才人侍立持團扇，金縷雙龙貼碧藤。"]', '诗', 'shi', '', NULL, '宮詞百首 三十六 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('229f5468-6e5e-4001-b3fe-1b073f4764c0', '宮詞百首 三十七', '宮词百首 三十七', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["香鴨烟輕爇水沈，雲鬟閑墜鳳犀簪。","珠簾半捲開花雨，又見芭蕉展半心。"]', '["香鴨烟轻爇水沈，云鬟闲墜鳳犀簪。","珠簾半捲开花雨，又见芭蕉展半心。"]', '诗', 'shi', '', NULL, '宮詞百首 三十七 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d55f62f2-1ad1-4e6a-8aeb-55cb0c081955', '宮詞百首 三十八', '宮词百首 三十八', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["鶯錦蟬羅撒麝臍，狻猊輕噴瑞烟迷。","紅酥點得香山小，卷上珠簾日未西。"]', '["鶯錦蟬羅撒麝臍，狻猊轻噴瑞烟迷。","紅酥点得香山小，卷上珠簾日未西。"]', '诗', 'shi', '', NULL, '宮詞百首 三十八 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0597fcbc-9109-408b-b5e7-c39cbe2d185c', '宮詞百首 三十九', '宮词百首 三十九', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["錦褥花明滿殿鋪，宮娥分坐學樗蒲。","欲教官馬衝關過，呪願纖纖早擲盧。"]', '["錦褥花明满殿鋪，宮娥分坐学樗蒲。","欲教官马衝关過，呪願纖纖早擲盧。"]', '诗', 'shi', '', NULL, '宮詞百首 三十九 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de3d7761-5202-457f-9572-5b5d69cb8d27', '宮詞百首 四十', '宮词百首 四十', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["小樓花簇鈿山低，金雉雙來蹋馬齊。","誇向傍人能彩戲，朝來贏得鷺鷥犀。"]', '["小楼花簇鈿山低，金雉雙来蹋马齊。","誇向傍人能彩戲，朝来贏得鷺鷥犀。"]', '诗', 'shi', '', NULL, '宮詞百首 四十 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('520c8b4a-cada-4ca2-9292-7bb137e13049', '宮詞百首 四十一', '宮词百首 四十一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["紅鬃白馬嫩龍飛，天廐供來入紫微。","遙見玉階嘶不已，應緣識得赭黃衣。"]', '["紅鬃白马嫩龙飞，天廐供来入紫微。","遙见玉階嘶不已，應緣識得赭黄衣。"]', '诗', 'shi', '', NULL, '宮詞百首 四十一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6fe10b0-b27b-4eeb-87de-656cca3d85f7', '宮詞百首 四十二', '宮词百首 四十二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["班定千牛立受宣，佩刀搢笏鳳墀前。","一聲不坐祥雲合，鴛鷺依行拜兩邊。"]', '["班定千牛立受宣，佩刀搢笏鳳墀前。","一声不坐祥云合，鴛鷺依行拜兩邊。"]', '诗', 'shi', '', NULL, '宮詞百首 四十二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad08479d-e6cb-4e89-b145-dde38b9f396d', '宮詞百首 四十三', '宮词百首 四十三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["三殿香濃曉色來，祥鸞威鳳待門開。","鏘金佩玉趨丹陛，總是和羹作礪才。"]', '["三殿香濃晓色来，祥鸾威鳳待门开。","鏘金佩玉趨丹陛，總是和羹作礪才。"]', '诗', 'shi', '', NULL, '宮詞百首 四十三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd030a3b-1cd4-4031-a2c0-cbd983438060', '宮詞百首 四十四', '宮词百首 四十四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["兩番供奉打毬時，鸞鳳分廂錦繡衣。","虎驟龍騰宮殿響，驊騮爭趂一星飛。"]', '["兩番供奉打毬时，鸾鳳分廂錦繡衣。","虎驟龙腾宮殿响，驊騮爭趂一星飞。"]', '诗', 'shi', '', NULL, '宮詞百首 四十四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce1747d-d625-4433-a356-b6337a26b75e', '宮詞百首 四十五', '宮词百首 四十五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["鳳池冰泮岸莎勻，柳眼花心雪裏新。","都是九重和暖地，東風先報禁園春。"]', '["鳳池冰泮岸莎勻，柳眼花心雪裏新。","都是九重和暖地，东风先報禁园春。"]', '诗', 'shi', '', NULL, '宮詞百首 四十五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7640ae7-cead-4d2c-be81-156bc2d9a696', '宮詞百首 四十六', '宮词百首 四十六', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["紫氣氤氳滿帝都，映樓明月鎖金鋪。","銀泥殿裏嫌紅燭，教近龍牀著火珠。"]', '["紫氣氤氳满帝都，映楼明月鎖金鋪。","銀泥殿裏嫌紅燭，教近龙牀著火珠。"]', '诗', 'shi', '', NULL, '宮詞百首 四十六 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4101b89-17e4-4c2d-a084-a1966120427e', '宮詞百首 四十七', '宮词百首 四十七', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["地衣初展瑞霞融，繡帽金鈴舞舜風。","吹竹彈絲珠殿響，墜仙雙降五雲中。"]', '["地衣初展瑞霞融，繡帽金鈴舞舜风。","吹竹彈絲珠殿响，墜仙雙降五云中。"]', '诗', 'shi', '', NULL, '宮詞百首 四十七 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea3582c-eead-4a30-8e33-84dfdf944556', '宮詞百首 四十八', '宮词百首 四十八', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["錦策勻鋪寒玉齊，星鎚高運日通犀。","鏗金曲罷春冰碎，跪拜君王粉面低。"]', '["錦策勻鋪寒玉齊，星鎚高運日通犀。","鏗金曲罷春冰碎，跪拜君王粉面低。"]', '诗', 'shi', '', NULL, '宮詞百首 四十八 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96876501-ed4a-48d5-be12-3882f5b75321', '宮詞百首 四十九', '宮词百首 四十九', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["珠簾靜卷水亭涼，玉蘂風飄小檻香。","幾處按歌齊入破，雙雙雛燕出宮墻。"]', '["珠簾静卷水亭涼，玉蘂风飄小檻香。","幾处按歌齊入破，雙雙雛燕出宮墻。"]', '诗', 'shi', '', NULL, '宮詞百首 四十九 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2912095-825f-4442-92e6-8b040845545b', '宮詞百首 五十', '宮词百首 五十', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["宮娥解禊豔陽時，鷁舸蘭橈滿鳳池。","春水如藍垂柳醉，和風無力褭金絲。"]', '["宮娥解禊豔陽时，鷁舸蘭橈满鳳池。","春水如藍垂柳醉，和风無力褭金絲。"]', '诗', 'shi', '', NULL, '宮詞百首 五十 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2117ca2b-c495-4f58-bc71-3a906f4527dd', '宮詞百首 五十一', '宮词百首 五十一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["白玉階前菊蘂香，金盃仙醞賞重陽。","層臺雲集梨園樂，獻壽聲聲祝萬康。"]', '["白玉階前菊蘂香，金盃仙醞賞重陽。","層台云集梨园乐，獻壽声声祝万康。"]', '诗', 'shi', '', NULL, '宮詞百首 五十一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9694c0fd-cb05-4feb-a493-c4804da7d0ce', '宮詞百首 五十二', '宮词百首 五十二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["天籟吟風社燕歸，渚蓮香老碧苔肥。","夜來霜墜梧桐葉，諸殿平明進御衣。"]', '["天籟吟风社燕归，渚蓮香老碧苔肥。","夜来霜墜梧桐葉，諸殿平明進御衣。"]', '诗', 'shi', '', NULL, '宮詞百首 五十二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5df674a-f665-4c17-a00f-3cad423dfd48', '宮詞百首 五十三', '宮词百首 五十三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["鑪爇香檀獸炭癡，真珠簾外雪花飛。","六宮進酒堯眉壽，舞鳳盤龍滿御衣。"]', '["鑪爇香檀獸炭癡，真珠簾外雪花飞。","六宮進酒堯眉壽，舞鳳盤龙满御衣。"]', '诗', 'shi', '', NULL, '宮詞百首 五十三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f277909c-f523-44f6-a8e6-395226aedce5', '宮詞百首 五十四', '宮词百首 五十四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["雲行風靜早秋天，競遶盆池蹋采蓮。","罨畫披袍從窣地，更尋宮柳看鳴蟬。"]', '["云行风静早秋天，競遶盆池蹋采蓮。","罨畫披袍從窣地，更尋宮柳看鳴蟬。"]', '诗', 'shi', '', NULL, '宮詞百首 五十四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d78941c4-cfd9-45f5-8e59-5ae1fe0ae8e8', '宮詞百首 五十五', '宮词百首 五十五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["闌珊星斗綴珠光，七夕宮嬪乞巧忙。","總上穿針樓上去，競看銀漢灑瓊槳。"]', '["闌珊星斗綴珠光，七夕宮嬪乞巧忙。","總上穿針楼上去，競看銀漢灑瓊槳。"]', '诗', 'shi', '', NULL, '宮詞百首 五十五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e612ccbf-4e9c-4f9a-bcc5-4329659b4eac', '宮詞百首 五十六', '宮词百首 五十六', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["寶瑟淒鏘夜漏餘，玉階閑作對蟾蜍。","秋光寂歷銀河轉，已見宮花露滴疎。"]', '["寶瑟淒鏘夜漏餘，玉階闲作对蟾蜍。","秋光寂歷銀河轉，已见宮花露滴疎。"]', '诗', 'shi', '', NULL, '宮詞百首 五十六 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd10ff7-abc8-477e-b65f-04dd708aceb0', '宮詞百首 五十七', '宮词百首 五十七', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["春風金褭萬年枝，簇白團紅爛熳時。","宮女競思遊御苑，大家齊奏聖人知。"]', '["春风金褭万年枝，簇白團紅爛熳时。","宮女競思游御苑，大家齊奏聖人知。"]', '诗', 'shi', '', NULL, '宮詞百首 五十七 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4218179e-9be3-4cd3-9085-b001298c8499', '宮詞百首 五十八', '宮词百首 五十八', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["乾文初見泰階平，日月常遵閣道行。","昨夜仰觀垂象正，拱辰星宿轉分明。"]', '["乾文初见泰階平，日月常遵閣道行。","昨夜仰观垂象正，拱辰星宿轉分明。"]', '诗', 'shi', '', NULL, '宮詞百首 五十八 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7faa6fd-fa3d-442c-9e65-0079bd2864d5', '宮詞百首 五十九', '宮词百首 五十九', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["鏘鏘濟濟赴延英，漸近重瞳目轉明。","君聖臣賢魚水契，鴻基須賀永清平。"]', '["鏘鏘濟濟赴延英，漸近重瞳目轉明。","君聖臣賢鱼水契，鴻基須賀永清平。"]', '诗', 'shi', '', NULL, '宮詞百首 五十九 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('059eede5-38c7-4705-ad6a-e5e6b682dc43', '宮詞百首 六十', '宮词百首 六十', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["天廐驂騑集嫩龍，雪光相照曉嘶風。","昂頭步步金鞍穩，掌扇花前御路中。"]', '["天廐驂騑集嫩龙，雪光相照晓嘶风。","昂头步步金鞍穩，掌扇花前御路中。"]', '诗', 'shi', '', NULL, '宮詞百首 六十 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f6a9b12-faa7-4346-b3a0-5b556be28e36', '宮詞百首 六十一', '宮词百首 六十一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["金吾細仗儼威儀，聖旨凝旒對遠夷。","曉日曈曨瞻玉案，丁冬環珮滿彤墀。"]', '["金吾細仗儼威儀，聖旨凝旒对远夷。","晓日曈曨瞻玉案，丁冬环珮满彤墀。"]', '诗', 'shi', '', NULL, '宮詞百首 六十一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2a82481-1ace-4bd2-a0bf-dfe0fb0c69c9', '宮詞百首 六十二', '宮词百首 六十二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["正旦垂旒御八方，蠻夷無不奉梯航。","羣臣舞蹈稱觴處，雷動山呼萬歲長。"]', '["正旦垂旒御八方，蠻夷無不奉梯航。","羣臣舞蹈稱觴处，雷动山呼万歲长。"]', '诗', 'shi', '', NULL, '宮詞百首 六十二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b559b4d-d1e2-4635-9a47-89c40d1b6f0e', '宮詞百首 六十三', '宮词百首 六十三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["聖主躬耕在籍田，公卿環衛待豐年。","五風十雨餘糧在，金殿惟聞奏舜弦。"]', '["聖主躬耕在籍田，公卿环衛待豐年。","五风十雨餘糧在，金殿惟闻奏舜弦。"]', '诗', 'shi', '', NULL, '宮詞百首 六十三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b29622a2-4a36-40e2-9491-b8642ad54485', '宮詞百首 六十四', '宮词百首 六十四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["聖日垂科委所司，英才咸喜遇明時。","春宮進榜鶯離谷，月殿香殘桂魄枝。"]', '["聖日垂科委所司，英才咸喜遇明时。","春宮進榜鶯離谷，月殿香殘桂魄枝。"]', '诗', 'shi', '', NULL, '宮詞百首 六十四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94c81275-e60e-4584-ad91-230f21a4d006', '宮詞百首 六十五', '宮词百首 六十五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["天街香滿瑞雲生，紅繖凝空景日明。","先遣五坊排獵騎，爲民除害出神京。"]', '["天街香满瑞云生，紅繖凝空景日明。","先遣五坊排獵騎，爲民除害出神京。"]', '诗', 'shi', '', NULL, '宮詞百首 六十五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1043224c-4175-4cc2-b79e-793b0c1a3a8b', '宮詞百首 六十六', '宮词百首 六十六', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["內宴初開錦繡攢，教坊齊奏萬年歡。","簫韶響亮春雲合，日照堯階舞瑞鸞。"]', '["內宴初开錦繡攢，教坊齊奏万年歡。","簫韶响亮春云合，日照堯階舞瑞鸾。"]', '诗', 'shi', '', NULL, '宮詞百首 六十六 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26aa95a2-0ce1-46d9-9c1f-b456ece3da76', '宮詞百首 六十七', '宮词百首 六十七', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["視草詞臣直玉堂，對來新賜錦袍香。","班資最在雲霄上，長是先迎日月光。"]', '["視草词臣直玉堂，对来新賜錦袍香。","班資最在云霄上，长是先迎日月光。"]', '诗', 'shi', '', NULL, '宮詞百首 六十七 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b45df08-0e60-4432-af84-75c44e52adec', '宮詞百首 六十八', '宮词百首 六十八', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["玉殿朦朧散曉光，金龍高噴九天香。","摵鞭聲定初開扇，百辟齊呼萬歲長。"]', '["玉殿朦朧散晓光，金龙高噴九天香。","摵鞭声定初开扇，百辟齊呼万歲长。"]', '诗', 'shi', '', NULL, '宮詞百首 六十八 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e859019-c295-47cd-8d60-e3db82d7af27', '宮詞百首 六十九', '宮词百首 六十九', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["五色卿雲復九重，香烟高舞御鑪中。","含元殿裏行仁德，四海車書已混同。"]', '["五色卿云复九重，香烟高舞御鑪中。","含元殿裏行仁德，四海车书已混同。"]', '诗', 'shi', '', NULL, '宮詞百首 六十九 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d5e701-0c4f-4d70-a1e6-805b40fac44a', '宮詞百首 七十', '宮词百首 七十', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["欲封丹詔紫泥香，朱篆龍文御印光。","汗渙絲綸出丹禁，便從天上鳳銜將。"]', '["欲封丹詔紫泥香，朱篆龙文御印光。","汗渙絲綸出丹禁，便從天上鳳銜將。"]', '诗', 'shi', '', NULL, '宮詞百首 七十 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3149101-2c23-4a1a-82fd-6c0b8cfaa2ed', '宮詞百首 七十一', '宮词百首 七十一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["越溪姝麗入深宮，儉素皆持馬后風。","盡道君王修聖德，不勞辭輦與當熊。"]', '["越溪姝丽入深宮，儉素皆持马后风。","尽道君王修聖德，不勞辞輦與當熊。"]', '诗', 'shi', '', NULL, '宮詞百首 七十一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe9539a6-3ca2-4640-8310-c8a692b2774c', '宮詞百首 七十二', '宮词百首 七十二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["早梅初向雪中明，風惹奇香粉蘂輕。","誰道落花堪靧面，競來枝上采繁英。"]', '["早梅初向雪中明，风惹奇香粉蘂轻。","誰道落花堪靧面，競来枝上采繁英。"]', '诗', 'shi', '', NULL, '宮詞百首 七十二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d4499d2-74b2-4c70-ad9f-f59e545c1485', '宮詞百首 七十三', '宮词百首 七十三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["暖殿奇香馥綺羅，窗間初學繡金鵝。","纔經冬至陽生後，今日工夫一綫多。"]', '["暖殿奇香馥綺羅，窗间初学繡金鵝。","纔經冬至陽生後，今日工夫一綫多。"]', '诗', 'shi', '', NULL, '宮詞百首 七十三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('028fd9cb-aae9-467b-9ec9-a874049d7cfd', '宮詞百首 七十四', '宮词百首 七十四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["金井澄泉玉液香，瑠璃深殿自清涼。","溫湯頭進瓜初熟，後至宮嬪未得嘗。"]', '["金井澄泉玉液香，瑠璃深殿自清涼。","溫湯头進瓜初熟，後至宮嬪未得嘗。"]', '诗', 'shi', '', NULL, '宮詞百首 七十四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e18ef0-e374-4aa5-8d66-1283eb4a21d2', '宮詞百首 七十五', '宮词百首 七十五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["繡闥雕甍列錦閨，珍奇惟待鳳凰棲。","杏梁烜赫晴霞展，時見空虛墜燕泥。"]', '["繡闥雕甍列錦閨，珍奇惟待鳳凰棲。","杏梁烜赫晴霞展，时见空虛墜燕泥。"]', '诗', 'shi', '', NULL, '宮詞百首 七十五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09bfb573-c6f8-4735-8f2b-2692bd6428b2', '宮詞百首 七十六', '宮词百首 七十六', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["龍鳳金鞍軟玉緶，雪花光照錦連乾。","駕頭直指西郊去，曉日寒生講武天。"]', '["龙鳳金鞍軟玉緶，雪花光照錦連乾。","駕头直指西郊去，晓日寒生講武天。"]', '诗', 'shi', '', NULL, '宮詞百首 七十六 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e903f796-2526-4e5a-b457-14b8809e9a72', '宮詞百首 七十七', '宮词百首 七十七', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["戛雲樓上定風盤，雀躍猨跳總不難。","要對君王逞輕捷，御樓時擬上雞竿。"]', '["戛云楼上定风盤，雀躍猨跳總不难。","要对君王逞轻捷，御楼时擬上雞竿。"]', '诗', 'shi', '', NULL, '宮詞百首 七十七 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5535fedb-4dea-49bc-a28d-9f5d04b259c6', '宮詞百首 七十八', '宮词百首 七十八', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["停穩春衫窣地長，通天犀帶綴金章。","近臣銜命離丹禁，高捧恩波灑萬方。"]', '["停穩春衫窣地长，通天犀带綴金章。","近臣銜命離丹禁，高捧恩波灑万方。"]', '诗', 'shi', '', NULL, '宮詞百首 七十八 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b64f4cd3-b066-41aa-a7be-3e636ab2a855', '宮詞百首 七十九', '宮词百首 七十九', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["垂黎玉押春簾卷，不夜珠樓曉鑑開。","袍袴宮人走迎駕，東風吹送御香來。"]', '["垂黎玉押春簾卷，不夜珠楼晓鑑开。","袍袴宮人走迎駕，东风吹送御香来。"]', '诗', 'shi', '', NULL, '宮詞百首 七十九 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88f70686-fed1-4970-8b0a-3439826865df', '宮詞百首 八十', '宮词百首 八十', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["金吾勘契自通宮，樓上初聞唱刻閑。","金殿香高初喚仗，數行鴛鷺各趨班。"]', '["金吾勘契自通宮，楼上初闻唱刻闲。","金殿香高初喚仗，數行鴛鷺各趨班。"]', '诗', 'shi', '', NULL, '宮詞百首 八十 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86bfef90-3d8a-4b6e-93ab-e3d512d8b2ed', '宮詞百首 八十一', '宮词百首 八十一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["螺髻凝香曉黛濃，水精鸂鶒颭輕風。","金釵斜戴宜春勝，萬歲千秋遶鬢紅。"]', '["螺髻凝香晓黛濃，水精鸂鶒颭轻风。","金釵斜戴宜春勝，万歲千秋遶鬢紅。"]', '诗', 'shi', '', NULL, '宮詞百首 八十一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a66b1a8-17b5-4e0f-b63f-f0967375beb7', '宮詞百首 八十二', '宮词百首 八十二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["縷金團扇對纖絺，正是深宮捧日時。","要對君王說幽意，低頭佯念婕妤詩。"]', '["縷金團扇对纖絺，正是深宮捧日时。","要对君王说幽意，低头佯念婕妤诗。"]', '诗', 'shi', '', NULL, '宮詞百首 八十二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa46013-017c-4655-a3cf-416e36a27947', '宮詞百首 八十三', '宮词百首 八十三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["結金冠子學梳蟬，碾玉蜻蜓綴鬢偏。","寢殿垂簾悄無事，試香閑立御爐前。"]', '["結金冠子学梳蟬，碾玉蜻蜓綴鬢偏。","寢殿垂簾悄無事，試香闲立御爐前。"]', '诗', 'shi', '', NULL, '宮詞百首 八十三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0719c042-94f4-4154-be48-f54a75958260', '宮詞百首 八十四', '宮词百首 八十四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["金馬詞臣夜受宣，授毫交直八花磚。","白麻草了初呈進，稱旨絲綸下九天。"]', '["金马词臣夜受宣，授毫交直八花磚。","白麻草了初呈進，稱旨絲綸下九天。"]', '诗', 'shi', '', NULL, '宮詞百首 八十四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('657183f1-cea5-4745-a251-31bb5024b22b', '宮詞百首 八十五', '宮词百首 八十五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["平明光政便門開，已見忠臣早入來。","自是樞機符造化，大羅天上曜三台。"]', '["平明光政便门开，已见忠臣早入来。","自是樞機符造化，大羅天上曜三台。"]', '诗', 'shi', '', NULL, '宮詞百首 八十五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb4d7727-0ead-43ce-b640-e9fd3a9f4925', '宮詞百首 八十六', '宮词百首 八十六', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["紅羅窗裏繡偏慵，嚲袖閑隈碧玉籠。","蘭殿春晴鸚鵡睡，結條釵颭落花風。"]', '["紅羅窗裏繡偏慵，嚲袖闲隈碧玉籠。","蘭殿春晴鸚鵡睡，結條釵颭落花风。"]', '诗', 'shi', '', NULL, '宮詞百首 八十六 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6985155d-71c3-4dc2-aa77-c3cd0e5233d0', '宮詞百首 八十七', '宮词百首 八十七', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["曉光初入右銀臺，鴛鷺分班啓沃來。","如水如魚何際會，盡言金鼎得鹽梅。"]', '["晓光初入右銀台，鴛鷺分班啓沃来。","如水如鱼何際會，尽言金鼎得鹽梅。"]', '诗', 'shi', '', NULL, '宮詞百首 八十七 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c63c2e-7743-4a99-8382-547a3aca7ea5', '宮詞百首 八十八', '宮词百首 八十八', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["立名金馬近堯階，盡是家傳八斗才。","麻尾尚猶龍字濕，便從天上鳳銜來。"]', '["立名金马近堯階，尽是家傳八斗才。","麻尾尚猶龙字濕，便從天上鳳銜来。"]', '诗', 'shi', '', NULL, '宮詞百首 八十八 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ad98ae-09a1-46c6-a310-812929321678', '宮詞百首 八十九', '宮词百首 八十九', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["狻猊鎮角舞筵張，鸞鳳花分十六行。","輕動玉纖歌遍慢，時時偷眼看君王。"]', '["狻猊鎮角舞筵張，鸾鳳花分十六行。","轻动玉纖歌遍慢，时时偷眼看君王。"]', '诗', 'shi', '', NULL, '宮詞百首 八十九 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9768b94c-defb-46dc-835b-8e1742c09487', '宮詞百首 九十', '宮词百首 九十', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["邊藩□宴賀休征，細仗初排舜日明。","坐定兩軍呈百戲，樂臣低折賀昇平。"]', '["邊藩□宴賀休征，細仗初排舜日明。","坐定兩軍呈百戲，乐臣低折賀昇平。"]', '诗', 'shi', '', NULL, '宮詞百首 九十 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c1c79a0-506f-40d8-be6d-6c202147d13a', '宮詞百首 九十一', '宮词百首 九十一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["碧羅冠子簇香蓮，結勝雙銜利市錢。","花下貪忙尋百草，不知遺却蹙金蟬。"]', '["碧羅冠子簇香蓮，結勝雙銜利市錢。","花下貪忙尋百草，不知遺却蹙金蟬。"]', '诗', 'shi', '', NULL, '宮詞百首 九十一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4202f1c5-bd01-4969-9bc8-2184bb1aec4f', '宮詞百首 九十二', '宮词百首 九十二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["蘭省初除傅粉郎，靜端霜簡入鴛行。","明庭轉制渾無事，朝下空餘雞舌香。"]', '["蘭省初除傅粉郎，静端霜簡入鴛行。","明庭轉制渾無事，朝下空餘雞舌香。"]', '诗', 'shi', '', NULL, '宮詞百首 九十二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c76c529-a6a0-4456-9627-f5fec91a7785', '宮詞百首 九十三', '宮词百首 九十三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["采訪寧遺草澤人，詔搜無不降蒲輪。","集賢殿裏開爐冶，待把黃金鑄重臣。"]', '["采訪寧遺草澤人，詔搜無不降蒲輪。","集賢殿裏开爐冶，待把黄金鑄重臣。"]', '诗', 'shi', '', NULL, '宮詞百首 九十三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daef5f15-9e75-4232-b8a0-5393102e3586', '宮詞百首 九十四', '宮词百首 九十四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["紅玉纖纖捧暖笙，絳唇呼吸引春鶯。","霓裳曲罷君王笑，宜近前來與改名。"]', '["紅玉纖纖捧暖笙，絳唇呼吸引春鶯。","霓裳曲罷君王笑，宜近前来與改名。"]', '诗', 'shi', '', NULL, '宮詞百首 九十四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea6c080-b1a6-4684-bf23-e3bafa73e732', '宮詞百首 九十五', '宮词百首 九十五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["繡額朱門插艾人，羞將角黍近香唇。","平明朝下誇宣賜，五色香絲繫臂新。"]', '["繡額朱门插艾人，羞將角黍近香唇。","平明朝下誇宣賜，五色香絲繫臂新。"]', '诗', 'shi', '', NULL, '宮詞百首 九十五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7112dbd-9e83-45c5-ac23-bf534a0939ff', '宮詞百首 九十六', '宮词百首 九十六', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["芙蓉冠子水精簪，閑對君王理玉琴。","鷺頸鶯脣勝仙子，步虛聲細象窗深。"]', '["芙蓉冠子水精簪，闲对君王理玉琴。","鷺頸鶯脣勝仙子，步虛声細象窗深。"]', '诗', 'shi', '', NULL, '宮詞百首 九十六 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20d84435-a921-4dba-879d-5ec136ad2aeb', '宮詞百首 九十七', '宮词百首 九十七', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["金馬門開侍從歸，御香猶惹賜來衣。","曉光滿院金魚冷，紅藥花擎宿露飛。"]', '["金马门开侍從归，御香猶惹賜来衣。","晓光满院金鱼冷，紅藥花擎宿露飞。"]', '诗', 'shi', '', NULL, '宮詞百首 九十七 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aa35cdf-cfb3-40fe-83c9-ee0b142e7f21', '宮詞百首 九十八', '宮词百首 九十八', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["便殿朝回卸玉簪，競來芳檻摘花心。","風和難捉花中蝶，却向窗間弄繡針。"]', '["便殿朝回卸玉簪，競来芳檻摘花心。","风和难捉花中蝶，却向窗间弄繡針。"]', '诗', 'shi', '', NULL, '宮詞百首 九十八 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df2fdfdd-5d47-4ff3-8e3b-e4f37256693e', '宮詞百首 九十九', '宮词百首 九十九', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["君王朝下未梳頭，長暈殘眉侍鑑樓。","扼臂交光紅玉軟，起來重擬理箜篌。"]', '["君王朝下未梳头，长暈殘眉侍鑑楼。","扼臂交光紅玉軟，起来重擬理箜篌。"]', '诗', 'shi', '', NULL, '宮詞百首 九十九 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7c620e5-fb8c-45d8-ac8b-8b7da59b8bd4', '宮詞百首 一百', '宮词百首 一百', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["九重天上實難知，空遣微臣役夢思。","葵藿一心期捧日，強搜狂斐擬宮詞。"]', '["九重天上實难知，空遣微臣役梦思。","葵藿一心期捧日，強搜狂斐擬宮词。"]', '诗', 'shi', '', NULL, '宮詞百首 一百 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d616544a-58e5-4e84-9bb6-e60549e48ce8', '漁父歌', '漁父歌', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["白芷汀寒立鷺鷥，蘋風輕翦浪花時。","煙羃羃，日遲遲，香引芙蓉惹釣絲。"]', '["白芷汀寒立鷺鷥，蘋风轻翦浪花时。","煙羃羃，日遲遲，香引芙蓉惹釣絲。"]', '诗', 'shi', '', NULL, '漁父歌 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54b7ac35-fd28-4b79-8064-2fa92d69a8f7', '楊柳枝 一', '楊柳枝 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["軟碧搖烟似送人，映花時把翠眉嚬。","青青自是風流主，慢颭金絲待洛神。"]', '["軟碧搖烟似送人，映花时把翠眉嚬。","青青自是风流主，慢颭金絲待洛神。"]', '诗', 'shi', '', NULL, '楊柳枝 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f901b1c-e4d4-48ef-9221-fb88a2e61aef', '楊柳枝 二', '楊柳枝 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["瑟瑟羅裙金縷腰，黛眉隈破未重描。","醉來齩損新花子，拽住仙郎盡放嬌。"]', '["瑟瑟羅裙金縷腰，黛眉隈破未重描。","醉来齩損新花子，拽住仙郎尽放嬌。"]', '诗', 'shi', '', NULL, '楊柳枝 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac980cbc-d0f9-473c-b4b3-33589ac78b55', '楊柳枝 三', '楊柳枝 三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["鵲橋初就咽銀河，今夜仙郎自姓和。","不是昔年攀桂樹，豈能月裏索姮娥。"]', '["鵲橋初就咽銀河，今夜仙郎自姓和。","不是昔年攀桂樹，豈能月裏索姮娥。"]', '诗', 'shi', '', NULL, '楊柳枝 三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aa80578-413a-4eee-8bc3-43b03b0d002a', '解紅歌', '解紅歌', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["百戲罷，五音清，解紅一曲新教成。","兩個瑤池小仙子，此時奪却柘枝名。"]', '["百戲罷，五音清，解紅一曲新教成。","兩個瑤池小仙子，此时奪却柘枝名。"]', '诗', 'shi', '', NULL, '解紅歌 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81402442-de07-4c52-9dd1-be8da36819ad', '題鷹獵兔畫', '題鷹獵兔畫', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["雖是丹青物，沈吟亦可傷。","君誇鷹眼疾，我憫兔心忙。","豈動騷人興，惟增獵客狂。","鮫綃百餘尺，爭及製衣裳。"]', '["雖是丹青物，沈吟亦可傷。","君誇鷹眼疾，我憫兔心忙。","豈动騷人兴，惟增獵客狂。","鮫綃百餘尺，爭及製衣裳。"]', '诗', 'shi', '', NULL, '題鷹獵兔畫 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1efc81-76ee-4de1-9790-903686d5e018', '醴泉院', '醴泉院', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["萬山嵐靄簇洋城，數處禪齋盡有名。","古柏八株堆翠色，靈泉一派逗寒聲。","暫遊頗愛閑滋味，久住翻嫌俗性情。","珍重支公每相勉，我于儒行也修行。"]', '["万山嵐靄簇洋城，數处禪斋尽有名。","古柏八株堆翠色，靈泉一派逗寒声。","暫游頗愛闲滋味，久住翻嫌俗性情。","珍重支公每相勉，我于儒行也修行。"]', '诗', 'shi', '', NULL, '醴泉院 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c01be0d9-71cf-4733-90bb-97fca42039fd', '興勢觀', '兴勢观', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["山名興勢鎮梁洋，儼有真風福此方。","瘦柏握盤籠殿紫，靈泉澄潔浸花香。","暫遊頗愛閑人少，久住翻嫌白日忙。","只向五千文字內，願成金骨住仙鄉。"]', '["山名兴勢鎮梁洋，儼有真风福此方。","瘦柏握盤籠殿紫，靈泉澄潔浸花香。","暫游頗愛闲人少，久住翻嫌白日忙。","只向五千文字內，願成金骨住仙乡。"]', '诗', 'shi', '', NULL, '興勢觀 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('961503a7-cf65-4ae9-a873-03f9dee1f343', '洋川', '洋川', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["華夷圖上見洋川，知在青山綠水邊。","官閑最好遊僧舍，江近應須買釣船。"]', '["华夷圖上见洋川，知在青山綠水邊。","官闲最好游僧舍，江近應須買釣船。"]', '诗', 'shi', '', NULL, '洋川 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8d02e2d-8b03-4e1a-aaba-a1b6fe33b429', '句', '句', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["先生自舞琴。","波上人如潘玉兒，掌中花似趙飛燕。"]', '["先生自舞琴。","波上人如潘玉兒，掌中花似趙飞燕。"]', '诗', 'shi', '', NULL, '句 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd11f8f2-028a-4479-ba65-f988e7ddef7b', '從蜀後主幸秦川上梓潼山', '從蜀後主幸秦川上梓潼山', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["綵仗拂寒煙，鳴騶在半天。","黃雲生馬足，白日下松巔。","盛德安疲俗，仁風扇極邊。","前程問成紀，此去尚三千。"]', '["綵仗拂寒煙，鳴騶在半天。","黄云生马足，白日下松巔。","盛德安疲俗，仁风扇極邊。","前程问成紀，此去尚三千。"]', '诗', 'shi', '', NULL, '從蜀後主幸秦川上梓潼山 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0d401a3-d85b-45f5-9b51-9245a0b29340', '和蜀後主題劒門', '和蜀後主題劒门', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["孟陽曾有語，刊在白雲稜。","李杜常挨托，孫劉亦恃憑。","庸才安可守，上德始堪矜。","暗指長天路，濃巒蔽幾層。"]', '["孟陽曾有語，刊在白云稜。","李杜常挨托，孫劉亦恃憑。","庸才安可守，上德始堪矜。","暗指长天路，濃巒蔽幾層。"]', '诗', 'shi', '', NULL, '和蜀後主題劒門 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37c93c13-19ca-49ce-890e-b2a1073c7694', '荆南席上詠胡琴妓二首 一', '荆南席上詠胡琴妓二首 一', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["紅妝齊抱紫檀槽，一抹朱弦四十條。","湘水淩波慚鼓瑟，秦樓明月罷吹簫。","寒敲白玉聲偏婉，暖逼黃鶯語自嬌。","丹禁舊臣來側耳，骨清神爽似聞韶。"]', '["紅妝齊抱紫檀槽，一抹朱弦四十條。","湘水淩波慚鼓瑟，秦楼明月罷吹簫。","寒敲白玉声偏婉，暖逼黄鶯語自嬌。","丹禁旧臣来側耳，骨清神爽似闻韶。"]', '诗', 'shi', '', NULL, '荆南席上詠胡琴妓二首 一 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72b8a953-409b-40a5-a8ad-883b4d0e3d4e', '荆南席上詠胡琴妓二首 二', '荆南席上詠胡琴妓二首 二', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["玉纖挑落折冰聲，散入秋空韻轉清。","二五指中句塞雁，十三弦上囀春鶯。","譜從陶室偷將妙，曲向秦樓寫得成。","無限細腰宮裏女，就中偏愜楚王情。"]', '["玉纖挑落折冰声，散入秋空韻轉清。","二五指中句塞雁，十三弦上囀春鶯。","譜從陶室偷將妙，曲向秦楼寫得成。","無限細腰宮裏女，就中偏愜楚王情。"]', '诗', 'shi', '', NULL, '荆南席上詠胡琴妓二首 二 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6247b20-a2c9-4850-93ce-f0d11aedb09e', '題麥積山天堂', '題麦積山天堂', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["躡盡懸空萬仞梯，等閑身共白雲齊。","簷前下視羣山小，堂上平分落日低。","絕頂路危人少到，古巖松健鶴頻棲。","天邊爲要留名姓，拂石殷勤身自題。"]', '["躡尽懸空万仞梯，等闲身共白云齊。","簷前下視羣山小，堂上平分落日低。","絕頂路危人少到，古巖松健鹤頻棲。","天邊爲要留名姓，拂石殷勤身自題。"]', '诗', 'shi', '', NULL, '題麥積山天堂 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e06d0ab0-a6aa-4523-acc7-e5e6f05c37a7', '題斗山觀', '題斗山观', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["霞衣欲舉醉陶陶，不覺全家住絳霄。","拔宅只知雞犬在，上天誰信路岐遙。","三清遼廊拋塵夢，八景雲煙事早朝。","爲有故林蒼柏健，露華涼葉鎖金飆。"]', '["霞衣欲舉醉陶陶，不覺全家住絳霄。","拔宅只知雞犬在，上天誰信路岐遙。","三清遼廊拋塵梦，八景云煙事早朝。","爲有故林蒼柏健，露华涼葉鎖金飆。"]', '诗', 'shi', '', NULL, '題斗山觀 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e081164-bdc3-4f92-93b1-9fe47045ebf7', '題孤雲絶頂淮陰祠', '題孤云絶頂淮陰祠', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["一握寒天古木深，路人猶說漢淮陰。","孤雲不掩興亡策，兩角曾懸去住心。","不是冕旒輕布素，豈勞丞相遠追尋。","當時若放還西楚，尺寸中華未可侵。"]', '["一握寒天古木深，路人猶说漢淮陰。","孤云不掩兴亡策，兩角曾懸去住心。","不是冕旒轻布素，豈勞丞相远追尋。","當时若放還西楚，尺寸中华未可侵。"]', '诗', 'shi', '', NULL, '題孤雲絶頂淮陰祠 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ecc63b6-9fda-4e5a-8e4f-be38e38150b2', '和韓昭從駕過白衛嶺', '和韓昭從駕過白衛嶺', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["龍斾飄颻指極邊，到時猶更二三千。","登高曉蹋巉巖石，冒冷朝衝斷續煙。","自學漢皇開土宇，不同周穆好神仙。","秦民莫遣無恩及，大散關東別有天。"]', '["龙斾飄颻指極邊，到时猶更二三千。","登高晓蹋巉巖石，冒冷朝衝斷續煙。","自学漢皇开土宇，不同周穆好神仙。","秦民莫遣無恩及，大散关东別有天。"]', '诗', 'shi', '', NULL, '和韓昭從駕過白衛嶺 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6804fe1d-98d6-45de-8cb7-69acdd2a38d4', '賀王溥入相', '賀王溥入相', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["一戰文場拔趙旗，便調金鼎佐無爲。","白麻驟降恩何極，黃髮初聞喜可知。","跋勅案前人到少，築沙堤上馬歸遲。","立班始得遙相見，親洽爭如未貴時。"]', '["一戰文場拔趙旗，便調金鼎佐無爲。","白麻驟降恩何極，黄髮初闻喜可知。","跋勅案前人到少，築沙堤上马归遲。","立班始得遙相见，親洽爭如未貴时。"]', '诗', 'shi', '', NULL, '賀王溥入相 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f0ca4a-62f6-4c68-8a81-96a1561ca05c', '與諸門生春日會飲繁臺賦', '與諸门生春日會饮繁台賦', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["柳陰如霧絮成堆，又引門生飲古臺。","淑景即隨風雨去，芳樽宜命管弦開。","謾誇列鼎鳴鐘貴，寧免朝烏夜兔催。","爛醉也須詩一首，不能空放馬頭回。"]', '["柳陰如霧絮成堆，又引门生饮古台。","淑景即隨风雨去，芳樽宜命管弦开。","謾誇列鼎鳴鐘貴，寧免朝烏夜兔催。","爛醉也須诗一首，不能空放马头回。"]', '诗', 'shi', '', NULL, '與諸門生春日會飲繁臺賦 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce95e775-7127-4a40-acab-439564dd1d8e', '示諸門生', '示諸门生', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["二百一十四門生，春風初長羽毛成。","擲金換得天邊桂，鑿壁偷將榜上名。","何辛不才逢聖世，偶將疎網罩羣英。","衰翁漸老兒孫小，異日知誰略有情。"]', '["二百一十四门生，春风初长羽毛成。","擲金換得天邊桂，鑿壁偷將榜上名。","何辛不才逢聖世，偶將疎網罩羣英。","衰翁漸老兒孫小，異日知誰略有情。"]', '诗', 'shi', '', NULL, '示諸門生 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('948b988f-b7b3-428a-b6a4-d5f9bac17dc5', '過平戎谷弔胡翽', '過平戎谷弔胡翽', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["立馬荒郊滿目愁，伊人何罪死林丘。","風號古木悲長在，雨濕寒莎淚暗流。","莫道文章爲衆嫉，只應輕薄是身讐。","不緣魂寄孤山下，此地堪名鸚鵡洲。"]', '["立马荒郊满目愁，伊人何罪死林丘。","风號古木悲长在，雨濕寒莎泪暗流。","莫道文章爲衆嫉，只應轻薄是身讐。","不緣魂寄孤山下，此地堪名鸚鵡洲。"]', '诗', 'shi', '', NULL, '過平戎谷弔胡翽 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('593d8f0a-774f-45c2-a38c-1593144c1d5a', '奉詔賦劒州途中鷙獸', '奉詔賦劒州途中鷙獸', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["劒牙釘舌血毛腥，窺算勞心豈暫停。","不與大朝除患難，惟餘當路食生靈。","從將戶口資嚵口，未委三丁稅幾丁。","今日帝王親出狩，白雲巖下好藏形。"]', '["劒牙釘舌血毛腥，窺算勞心豈暫停。","不與大朝除患难，惟餘當路食生靈。","從將戶口資嚵口，未委三丁稅幾丁。","今日帝王親出狩，白云巖下好藏形。"]', '诗', 'shi', '', NULL, '奉詔賦劒州途中鷙獸 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85683f0a-98d9-472c-9988-7fbd46cd61ed', '放猿', '放猿', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["放爾丁寧復故林，舊來行處好追尋。","月明巫峽堪憐靜，路隔巴山莫厭深。","棲宿免勞青嶂夢，躋攀應愜白雲心。","三秋果熟松梢健，任抱高枝徹曉吟。"]', '["放爾丁寧复故林，旧来行处好追尋。","月明巫峽堪怜静，路隔巴山莫厭深。","棲宿免勞青嶂梦，躋攀應愜白云心。","三秋果熟松梢健，任抱高枝徹晓吟。"]', '诗', 'shi', '', NULL, '放猿 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43d1a72b-348f-4231-b98a-c9b03ffdeba8', '遇放猿再作', '遇放猿再作', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["嶓冢祠前漢水濱，飲猿連臂下嶙峋。","漸來子細窺行客，認得依稀是野賓。","月宿從勞羈絏夢，松餐非復稻粱身。","數聲腸斷和雲呌，識是前時舊主人。"]', '["嶓冢祠前漢水濱，饮猿連臂下嶙峋。","漸来子細窺行客，認得依稀是野賓。","月宿從勞羈絏梦，松餐非复稻粱身。","數声腸斷和云呌，識是前时旧主人。"]', '诗', 'shi', '', NULL, '遇放猿再作 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6cb87a3-68af-48b3-921a-dca670fd2d9a', '句', '句', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["鐵鎖寨門扃白日，大張旗幟插青天。"]', '["鐵鎖寨门扃白日，大張旗幟插青天。"]', '诗', 'shi', '', NULL, '句 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fd804ba-2f5d-4176-a481-1f63620452f3', '天道', '天道', '1753125f-3024-4c68-9740-55d160b396e0', '唐', '["窮達皆由命，何勞發歎聲。","但知行好事，莫要問前程。","冬去冰須泮，春來草自生。","請君觀此理，天道甚分明。"]', '["窮達皆由命，何勞發歎声。","但知行好事，莫要问前程。","冬去冰須泮，春来草自生。","請君观此理，天道甚分明。"]', '诗', 'shi', '', NULL, '天道 馮道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('505ac72c-43b4-4a40-a307-3e26980c6789', '偶作', '偶作', '1753125f-3024-4c68-9740-55d160b396e0', '唐', '["莫爲危時便愴神，前程往往有期因。","須知海嶽歸明主，未必乾坤陷吉人。","道德幾時曾去世，舟車何處不通津？","但教方寸無諸惡，狼虎叢中也立身。"]', '["莫爲危时便愴神，前程往往有期因。","須知海嶽归明主，未必乾坤陷吉人。","道德幾时曾去世，舟车何处不通津？","但教方寸無諸惡，狼虎叢中也立身。"]', '诗', 'shi', '', NULL, '偶作 馮道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f02b511-c2d6-492c-87bb-d5e3d44170c0', '北使還京作', '北使還京作', '1753125f-3024-4c68-9740-55d160b396e0', '唐', '["去年今日奉皇華，只爲朝廷不爲家。","殿上一杯天子泣，門前雙節國人嗟。","龍荒冬往時時雪，兔苑春歸處處花。","上下一行如骨肉，幾人身死掩風沙。"]', '["去年今日奉皇华，只爲朝廷不爲家。","殿上一杯天子泣，门前雙節国人嗟。","龙荒冬往时时雪，兔苑春归处处花。","上下一行如骨肉，幾人身死掩风沙。"]', '诗', 'shi', '', NULL, '北使還京作 馮道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a43fae35-3168-4909-aa05-9c7342e1169c', '贈竇十', '贈竇十', '1753125f-3024-4c68-9740-55d160b396e0', '唐', '["燕山竇十郎，教子有義方。","靈椿一株老，丹桂五枝芳。"]', '["燕山竇十郎，教子有義方。","靈椿一株老，丹桂五枝芳。"]', '诗', 'shi', '', NULL, '贈竇十 馮道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('635822c3-e7b0-4ef8-95bf-b0aa2bb092f4', '放魚書所鑰戶', '放鱼书所鑰戶', '1753125f-3024-4c68-9740-55d160b396e0', '唐', '["高卻垣牆鑰却門，監丞從此罷垂綸。","池中魚鱉應相賀，從此方知有主人。"]', '["高卻垣牆鑰却门，監丞從此罷垂綸。","池中鱼鱉應相賀，從此方知有主人。"]', '诗', 'shi', '', NULL, '放魚書所鑰戶 馮道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6231bb7f-5249-4221-b07c-7ee2639bb836', '句', '句', '1753125f-3024-4c68-9740-55d160b396e0', '唐', '["朝披四襖專藏手，夜覆三衾怕露頭。","牛頭偏得賜，象笏更容持。","已落地花方遣埽，未經霜草莫教鋤。","視草北來唐學士，擁旄西去漢將軍。"]', '["朝披四襖專藏手，夜覆三衾怕露头。","牛头偏得賜，象笏更容持。","已落地花方遣埽，未經霜草莫教鋤。","視草北来唐学士，擁旄西去漢將軍。"]', '诗', 'shi', '', NULL, '句 馮道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3db7e75-942e-4c0b-825e-2e2e5b8d7228', '後唐宗廟樂舞辭', '後唐宗廟乐舞辞', 'd04e60e7-ecff-472d-9848-8d812e8a6701', '唐', '["仁君御宇，環海謐清。","運符武德，道協文明。","九成式敍，百度惟成。","金門積慶，玉葉傳榮。"]', '["仁君御宇，环海謐清。","運符武德，道協文明。","九成式敍，百度惟成。","金门積慶，玉葉傳榮。"]', '诗', 'shi', '', NULL, '後唐宗廟樂舞辭 盧文紀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a28ed34d-c456-4d7b-826b-17a56bf62763', '後唐宗廟樂舞辭', '後唐宗廟乐舞辞', '820374c7-0668-4f9f-8b1a-d8fdb83372bd', '唐', '["艱難王業，返正皇唐。","先天在造，却日重光。","漢紹世祖，夏資少康。","功成德茂，率祀無疆。"]', '["艱难王業，返正皇唐。","先天在造，却日重光。","漢紹世祖，夏資少康。","功成德茂，率祀無疆。"]', '诗', 'shi', '', NULL, '後唐宗廟樂舞辭 崔居儉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d0c1e3d-f33b-4a0e-aeed-8d1b8417141e', '春社從李昉乞酒', '春社從李昉乞酒', 'b5d2ead8-ce44-47da-a2af-94bc6846601c', '唐', '["社公今日沒心情，爲乞治聾酒一瓶。","惱亂玉堂將欲徧，依稀巡到第三廳。"]', '["社公今日沒心情，爲乞治聾酒一瓶。","惱亂玉堂將欲徧，依稀巡到第三廳。"]', '诗', 'shi', '', NULL, '春社從李昉乞酒 李濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ec66820-1403-4d24-aaa1-52cbca88ab14', '句', '句', 'b5d2ead8-ce44-47da-a2af-94bc6846601c', '唐', '["溪聲長在耳，山色不離門。","掃地樹留影，拂妝琴有聲。","一言寤主寧復聽，三諫不從歸去來。"]', '["溪声长在耳，山色不離门。","掃地樹留影，拂妝琴有声。","一言寤主寧复听，三諫不從归去来。"]', '诗', 'shi', '', NULL, '句 李濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f9043ab-563f-43fa-adf1-e7a2e5767c1d', '靈溪老松歌', '靈溪老松歌', '530991f4-f560-47e7-be37-b98d750da856', '唐', '["靈溪古觀壇西角，千尺鱗皴棟梁樸。","橫出一枝戛樓閣，直上一枝掃寥廊。","白石蒼苔擁根脚，月明風憾寒光落。","有時風雨晦瞑，擺撼若黑龍之騰躍。","合生於象外峰巒，枉滯乎人間山岳。","安得巨靈受請託，拔向青桂白榆邊安著。"]', '["靈溪古观壇西角，千尺鱗皴棟梁樸。","橫出一枝戛楼閣，直上一枝掃寥廊。","白石蒼苔擁根脚，月明风憾寒光落。","有时风雨晦瞑，擺撼若黑龙之腾躍。","合生於象外峰巒，枉滯乎人间山岳。","安得巨靈受請託，拔向青桂白榆邊安著。"]', '诗', 'shi', '', NULL, '靈溪老松歌 盧士衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('184d43de-20af-46d2-b72b-46f6cb30fb95', '遊靈溪觀', '游靈溪观', '530991f4-f560-47e7-be37-b98d750da856', '唐', '["雲藏寶殿風塵外，粉壁松軒入看初。","話久仙童顏色老，病來玄鶴羽毛疎。","樵翁接引尋紅朮，道士留連說紫書。","不爲壯心降未得，便堪從此翫清虛。"]', '["云藏寶殿风塵外，粉壁松軒入看初。","話久仙童顏色老，病来玄鹤羽毛疎。","樵翁接引尋紅朮，道士留連说紫书。","不爲壯心降未得，便堪從此翫清虛。"]', '诗', 'shi', '', NULL, '遊靈溪觀 盧士衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baec7927-fed9-4872-ad3a-4d4b6096577a', '寄天台道友', '寄天台道友', '530991f4-f560-47e7-be37-b98d750da856', '唐', '["相思遙指玉霄峰，悵望江上阻萬重。","曾隔曉窗聞法鼓，幾同寒榻聽疎鐘。","別來知子長餐栢，吟處將誰對倚松。","且住人間行聖教，莫思天路便登龍。"]', '["相思遙指玉霄峰，悵望江上阻万重。","曾隔晓窗闻法鼓，幾同寒榻听疎鐘。","別来知子长餐栢，吟处將誰对倚松。","且住人间行聖教，莫思天路便登龙。"]', '诗', 'shi', '', NULL, '寄天台道友 盧士衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9acd27f7-5796-47a9-80f8-e7f1e05c527e', '花落', '花落', '530991f4-f560-47e7-be37-b98d750da856', '唐', '["迎風嘯未已，和雨落穀穀。","千枝與萬枝，不如一竿竹。"]', '["迎风嘯未已，和雨落穀穀。","千枝與万枝，不如一竿竹。"]', '诗', 'shi', '', NULL, '花落 盧士衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf5a7bf-abd6-4eb7-8902-dfbfb183c805', '鍾陵鐵柱', '鍾陵鐵柱', '530991f4-f560-47e7-be37-b98d750da856', '唐', '["千年埋沒竟何爲，變化宜將萬物齊。","安得風胡借方便，鑄成神劍斬鯨鯢。"]', '["千年埋沒竟何爲，变化宜將万物齊。","安得风胡借方便，鑄成神劍斬鯨鯢。"]', '诗', 'shi', '', NULL, '鍾陵鐵柱 盧士衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5361e2a1-f1ca-4504-a291-2729e41f0cd8', '僧房聽雨', '僧房听雨', '530991f4-f560-47e7-be37-b98d750da856', '唐', '["古寺松軒雨聲別，寒窗聽久詩魔發。","記得年前在赤城，石樓夢覺三更雪。"]', '["古寺松軒雨声別，寒窗听久诗魔發。","記得年前在赤城，石楼梦覺三更雪。"]', '诗', 'shi', '', NULL, '僧房聽雨 盧士衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61aae385-73c7-4b84-aa32-1e6135092019', '題牡丹', '題牡丹', '530991f4-f560-47e7-be37-b98d750da856', '唐', '["萬葉紅綃翦盡春，丹青任寫不如真。","風光九十無多日，難惜尊前折贈人。"]', '["万葉紅綃翦尽春，丹青任寫不如真。","风光九十無多日，难惜尊前折贈人。"]', '诗', 'shi', '', NULL, '題牡丹 盧士衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c394d83-0ccf-418d-a866-c08c9812fd03', '祖龍詞', '祖龙词', 'ac66301f-a3ce-4c4e-b98c-d148f42d9e61', '唐', '["平吞六國更何求，童女童男問十洲。","滄海不回應悵望，始知徐福解風流。"]', '["平吞六国更何求，童女童男问十洲。","滄海不回應悵望，始知徐福解风流。"]', '诗', 'shi', '', NULL, '祖龍詞 熊皦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c57820-2eb2-4e68-a513-ab011781c5bd', '謫居海上', '謫居海上', 'ac66301f-a3ce-4c4e-b98c-d148f42d9e61', '唐', '["家臨涇水隔秦川，來往關河路八千。","堪恨此身何處老，始皇橋畔又經年。"]', '["家臨涇水隔秦川，来往关河路八千。","堪恨此身何处老，始皇橋畔又經年。"]', '诗', 'shi', '', NULL, '謫居海上 熊皦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea237aed-c64d-49fb-92d3-ffea84ecfb66', '冬日原居酬光上人見訪', '冬日原居酬光上人见訪', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["吾道喪已久，吾師何此來。","門無塵事閉，卷有國風開。","野迥霜先白，庭荒葉自堆。","寒暄吟罷後，猶喜話天台。"]', '["吾道喪已久，吾師何此来。","门無塵事閉，卷有国风开。","野迥霜先白，庭荒葉自堆。","寒暄吟罷後，猶喜話天台。"]', '诗', 'shi', '', NULL, '冬日原居酬光上人見訪 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef3983c-9c07-430f-8187-b74fc5308071', '早梅', '早梅', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["江南近臘時，已亞雪中枝。","一夜欲開盡，百花猶未知。","人情皆共惜，天意欲教遲。","莫訝無濃豔，芳筵正好吹。"]', '["江南近臘时，已亞雪中枝。","一夜欲开尽，百花猶未知。","人情皆共惜，天意欲教遲。","莫訝無濃豔，芳筵正好吹。"]', '诗', 'shi', '', NULL, '早梅 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38949be4-e4e7-4cfe-a7d9-ced3e13d64f1', '懷三茅道友', '懷三茅道友', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["塵事何年解客嘲，十年容易到三茅。","長思碧洞雲窗下，曾借黃庭雪夜抄。","丹桂有心憑至論，五峰無信問深交。","杏壇仙侶應相笑，只爲浮名未肯拋。"]', '["塵事何年解客嘲，十年容易到三茅。","长思碧洞云窗下，曾借黄庭雪夜抄。","丹桂有心憑至論，五峰無信问深交。","杏壇仙侶應相笑，只爲浮名未肯拋。"]', '诗', 'shi', '', NULL, '懷三茅道友 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58468d96-fd17-4b47-9be1-a0ec543d3260', '贈胥尊師', '贈胥尊師', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["綠髮童顏羽服輕，天台王屋幾經行。","雲程去速因風起，酒債還遲待藥成。","房閉十洲煙浪闊，籙開三洞鬼神驚。","他年華表重歸日，却恐桑田已變更。"]', '["綠髮童顏羽服轻，天台王屋幾經行。","云程去速因风起，酒債還遲待藥成。","房閉十洲煙浪闊，籙开三洞鬼神驚。","他年华表重归日，却恐桑田已变更。"]', '诗', 'shi', '', NULL, '贈胥尊師 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77f44d17-757d-4cd0-a382-0b331dc5ba6d', '句', '句', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["山前猶見月，陌上未逢人。","果熟秋先落，禽寒夜未棲。","深逢野草皆爲藥，靜見樵人恐是仙。","厭聽啼鳥夢醒後，慵掃落花春盡時。","廢土有人耕不畏，古廳無訟醉何妨。"]', '["山前猶见月，陌上未逢人。","果熟秋先落，禽寒夜未棲。","深逢野草皆爲藥，静见樵人恐是仙。","厭听啼鸟梦醒後，慵掃落花春尽时。","廢土有人耕不畏，古廳無訟醉何妨。"]', '诗', 'shi', '', NULL, '句 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fabc9d62-2962-4109-98ef-bf118fdbec83', '塞上', '塞上', 'e41972fb-b889-4787-a1fe-60e372029356', '唐', '["黃沙風捲半空拋，雲動陰山雪滿郊。","探水人迴移帳就，射鵰箭落著弓抄。","鳥逢霜果飢還啄，馬渡冰河渴自跑。","占得高原肥草地，夜深生火折林梢。"]', '["黄沙风捲半空拋，云动陰山雪满郊。","探水人迴移帳就，射鵰箭落著弓抄。","鸟逢霜果飢還啄，马渡冰河渴自跑。","占得高原肥草地，夜深生火折林梢。"]', '诗', 'shi', '', NULL, '塞上 趙延壽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c86b476a-a2eb-48d2-9d38-e7ca3feecee1', '棊', '棊', 'bff80db2-8263-4a34-b459-98fda8d27272', '唐', '["野客圍棊坐，搘頤向暮秋。","不言如守默，設計似平讎。","決勝雖關勇，防危亦合憂。","看他終一局，白却少年頭。"]', '["野客圍棊坐，搘頤向暮秋。","不言如守默，設計似平讎。","決勝雖关勇，防危亦合憂。","看他終一局，白却少年头。"]', '诗', 'shi', '', NULL, '棊 高輦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7150bd-a04c-4c5a-8cf3-ddf15f46e06d', '句', '句', 'bff80db2-8263-4a34-b459-98fda8d27272', '唐', '["飄飄送下遙天雪，颯颯吹乾旅舍煙。"]', '["飄飄送下遙天雪，颯颯吹乾旅舍煙。"]', '诗', 'shi', '', NULL, '句 高輦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10fe3de9-955a-44b1-821d-db985760aa67', '與李專美', '與李專美', '6747e501-5ba0-4249-b749-ed4f79da21af', '唐', '["昭裔登庸汝未登，鳳池雞樹冷如冰。","何如且作宣徽使，免被人呼粥飯僧。"]', '["昭裔登庸汝未登，鳳池雞樹冷如冰。","何如且作宣徽使，免被人呼粥飯僧。"]', '诗', 'shi', '', NULL, '與李專美 韓昭裔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b07716a7-b91e-4ad5-9535-c4fc092dc942', '題龍窩洞', '題龙窩洞', '173399f3-48b2-4375-ac9e-255ab1c2bfd9', '唐', '["折花攜酒看龍窩，鏤玉長旌俊彥過。","他日各爲雲外客，碧紗籠却又如何。"]', '["折花携酒看龙窩，鏤玉长旌俊彥過。","他日各爲云外客，碧紗籠却又如何。"]', '诗', 'shi', '', NULL, '題龍窩洞 張仁溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1960aeb8-32c0-466c-8bde-13f47a109947', '留題座主和凝舊閣', '留題座主和凝旧閣', 'ea6cb42e-ef38-44a5-a2eb-c591032fdd6c', '唐', '["座主登庸歸鳳闕，門生批詔立鰲頭。","玉堂舊閣多珍玩，可作西齋潤筆不。"]', '["座主登庸归鳳闕，门生批詔立鰲头。","玉堂旧閣多珍玩，可作西斋潤笔不。"]', '诗', 'shi', '', NULL, '留題座主和凝舊閣 李瀚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e57a59e-22e9-412c-9718-c7466335d25b', '題家園', '題家园', 'afc2bb92-abb4-49f8-93b6-ded02b438d18', '唐', '["池蓮憔悴無顏色，園竹低垂減翠陰。","園竹池蓮莫惆悵，相看恰似主人心。"]', '["池蓮憔悴無顏色，园竹低垂減翠陰。","园竹池蓮莫惆悵，相看恰似主人心。"]', '诗', 'shi', '', NULL, '題家園 楊昭儉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ef29f9-e836-4464-9614-aa5165787f8c', '書從事廳屏上', '书從事廳屏上', 'c9fda4b4-d0a5-4554-803c-93f1f0d47d07', '唐', '["金殿試迴新折桂，將軍留辟向江城。","思量一醉猶難得，辜負揚州管記名。"]', '["金殿試迴新折桂，將軍留辟向江城。","思量一醉猶难得，辜負揚州管記名。"]', '诗', 'shi', '', NULL, '書從事廳屏上 劉坦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b7d057e-678d-43e0-8e83-2d1d74c04a9d', '題施璘畫竹圖', '題施璘畫竹圖', '68995203-8f53-41a3-8aa1-6bcfad137d6e', '唐', '["枯籜危根繳石頭，千竿交映近清流。","堪珍仲寶窮幽筆，留得荆湘一片秋。"]', '["枯籜危根繳石头，千竿交映近清流。","堪珍仲寶窮幽笔，留得荆湘一片秋。"]', '诗', 'shi', '', NULL, '題施璘畫竹圖 韋遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b1cf8d0-62d6-4166-a330-44cc2ec51025', '陪遊鳳皇臺獻詩', '陪游鳳皇台獻诗', 'cc18ac52-ef7c-48ef-8bf3-a5853dd72854', '唐', '["嵯峨壓洪泉，岝峉撐碧落。","宜哉秦始皇，不驅亦不鑿。","上有布政臺，八顧背城郭。","山蹙龍虎健，水黑螭蜃作。","白虹欲吞人，赤驥相𤍿㩧。","畫棟泥金碧，石路盤墝埆。","倒挂哭月猿，危立思天鶴。","鑿池養蛟龍，栽桐棲鸑鷟。","梁間燕教雛，石罅蛇懸殼。","養花如養賢，去草如去惡。","日晚嚴城鼓，風來蕭寺鐸。","掃地驅塵埃，翦蒿除鳥雀。","金桃帶葉摘，綠李和衣嚼。","貞竹無盛衰，媚柳先搖落。","塵飛景陽井，草合臨春閣。","芙蓉如佳人，迴首似調謔。","當軒有直道，無人肯駐脚。","夜半鼠窸窣，天陰鬼敲啄。","松孤不易立，石醜難安著。","自憐啄木鳥，去蠹終不錯。","晚風吹梧桐，樹頭鳴嚗嚗。","峨峨江令石，青苔何淡薄。","不話興亡事，舉首思眇邈。","吁哉未到此，褊劣同尺蠖。","籠鶴羨鳧毛，猛虎愛蝸角。","一日賢太守，與我觀橐籥。","往往獨自語，天帝相唯諾。","風雲偶不來，寰宇銷一略。","我欲烹長鯨，四海爲鼎鑊。","我欲取大鵬，天地爲矰繳。","安得生羽翰，雄飛上寥廓。"]', '["嵯峨壓洪泉，岝峉撐碧落。","宜哉秦始皇，不驱亦不鑿。","上有布政台，八顧背城郭。","山蹙龙虎健，水黑螭蜃作。","白虹欲吞人，赤驥相𤍿㩧。","畫棟泥金碧，石路盤墝埆。","倒挂哭月猿，危立思天鹤。","鑿池養蛟龙，栽桐棲鸑鷟。","梁间燕教雛，石罅蛇懸殼。","養花如養賢，去草如去惡。","日晚嚴城鼓，风来蕭寺鐸。","掃地驱塵埃，翦蒿除鸟雀。","金桃带葉摘，綠李和衣嚼。","貞竹無盛衰，媚柳先搖落。","塵飞景陽井，草合臨春閣。","芙蓉如佳人，迴首似調謔。","當軒有直道，無人肯駐脚。","夜半鼠窸窣，天陰鬼敲啄。","松孤不易立，石醜难安著。","自怜啄木鸟，去蠹終不錯。","晚风吹梧桐，樹头鳴嚗嚗。","峨峨江令石，青苔何淡薄。","不話兴亡事，舉首思眇邈。","吁哉未到此，褊劣同尺蠖。","籠鹤羨鳧毛，猛虎愛蝸角。","一日賢太守，與我观橐籥。","往往独自語，天帝相唯諾。","风云偶不来，寰宇銷一略。","我欲烹长鯨，四海爲鼎鑊。","我欲取大鵬，天地爲矰繳。","安得生羽翰，雄飞上寥廓。"]', '诗', 'shi', '', NULL, '陪遊鳳皇臺獻詩 宋齊丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06e90fad-906e-46d3-8487-bf00cda8d6ca', '贈仰山慧度禪師', '贈仰山慧度禪師', 'cc18ac52-ef7c-48ef-8bf3-a5853dd72854', '唐', '["初聞如自解，及見勝初聞。","兩鬢堆殘雪，一身披斷雲。","道應齊古佛，高不揖吾君。","稽首清涼月，蕭然萬象分。"]', '["初闻如自解，及见勝初闻。","兩鬢堆殘雪，一身披斷云。","道應齊古佛，高不揖吾君。","稽首清涼月，蕭然万象分。"]', '诗', 'shi', '', NULL, '贈仰山慧度禪師 宋齊丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08f6ae6f-be3d-4d11-88c0-456ac5f203c3', '陪華林園試小妓羯鼓', '陪华林园試小妓羯鼓', 'cc18ac52-ef7c-48ef-8bf3-a5853dd72854', '唐', '["切斷牙牀鏤紫金，最宜平穩玉槽深。","因逢淑景開佳宴，爲出花奴奏雅音。","掌底輕璁孤鵲噪，枝頭乾快亂蟬吟。","開元天子曾如此，今日將軍好用心。"]', '["切斷牙牀鏤紫金，最宜平穩玉槽深。","因逢淑景开佳宴，爲出花奴奏雅音。","掌底轻璁孤鵲噪，枝头乾快亂蟬吟。","开元天子曾如此，今日將軍好用心。"]', '诗', 'shi', '', NULL, '陪華林園試小妓羯鼓 宋齊丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c07e1dd-a16e-432b-816e-5becb1557d30', '句', '句', 'cc18ac52-ef7c-48ef-8bf3-a5853dd72854', '唐', '["大似賢臣扶社稷，遇明則見暗還藏。"]', '["大似賢臣扶社稷，遇明則见暗還藏。"]', '诗', 'shi', '', NULL, '句 宋齊丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22c53cbd-efbc-4f7e-9ddd-5aa173459759', '早朝', '早朝', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["銅壺滴漏初晝，高閣雞鳴半空。","催啓五門金鎖，猶垂三殿簾櫳。","階前御柳搖綠，仗下宮花散紅。","鴛瓦數行曉日，鸞旗百尺春風。","侍臣踏舞重拜，聖壽南山永同。"]', '["銅壺滴漏初晝，高閣雞鳴半空。","催啓五门金鎖，猶垂三殿簾櫳。","階前御柳搖綠，仗下宮花散紅。","鴛瓦數行晓日，鸾旗百尺春风。","侍臣踏舞重拜，聖壽南山永同。"]', '诗', 'shi', '', NULL, '早朝 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('814d881b-1203-4732-8e9f-3aef2c2e2cf3', '句', '句', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["青樓阿監應相笑，書記登壇又却回。"]', '["青楼阿監應相笑，书記登壇又却回。"]', '诗', 'shi', '', NULL, '句 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2919e4ef-8da8-4185-ad9c-8bff0920eeeb', '感懷詩二章 一', '感懷诗二章 一', '32eb2807-6231-496d-ad1c-c603369da4ff', '唐', '["僕本江北人，今作江南客。","再去江北遊，舉目無相識。","金風吹我寒，秋月爲誰白。","不如歸去來，江南有人憶。"]', '["僕本江北人，今作江南客。","再去江北游，舉目無相識。","金风吹我寒，秋月爲誰白。","不如归去来，江南有人憶。"]', '诗', 'shi', '', NULL, '感懷詩二章 一 韓熙載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b707000e-1430-4cea-8954-7c5122e00bf2', '感懷詩二章 二', '感懷诗二章 二', '32eb2807-6231-496d-ad1c-c603369da4ff', '唐', '["未到故鄉時，將爲故鄉好。","及至親得歸，爭如身不到。","目前相識無一人，出入空傷我懷抱。","風雨蕭蕭旅館秋，歸來窗下和衣倒。","夢中忽到江南路，尋得花邊舊居處。","桃臉蛾眉笑出門，爭向前頭擁將去。"]', '["未到故乡时，將爲故乡好。","及至親得归，爭如身不到。","目前相識無一人，出入空傷我懷抱。","风雨蕭蕭旅館秋，归来窗下和衣倒。","梦中忽到江南路，尋得花邊旧居处。","桃臉蛾眉笑出门，爭向前头擁將去。"]', '诗', 'shi', '', NULL, '感懷詩二章 二 韓熙載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('156f1bd4-e618-4f41-b1ab-2b1a419ca8a2', '溧水無相寺贈僧', '溧水無相寺贈僧', '32eb2807-6231-496d-ad1c-c603369da4ff', '唐', '["無相景幽遠，山屏四面開。","憑師領鶴去，待我挂冠來。","藥爲依時採，松宜繞舍栽。","林泉自多興，不是效劉雷。"]', '["無相景幽远，山屏四面开。","憑師領鹤去，待我挂冠来。","藥爲依时採，松宜繞舍栽。","林泉自多兴，不是效劉雷。"]', '诗', 'shi', '', NULL, '溧水無相寺贈僧 韓熙載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('883fd778-5607-4cf5-bbad-2cf9ec2b0118', '書歌妓泥金帶', '书歌妓泥金带', '32eb2807-6231-496d-ad1c-c603369da4ff', '唐', '["風柳搖搖無定枝，陽臺雲雨夢中歸。","他年蓬島音塵斷，留取尊前舊舞衣。"]', '["风柳搖搖無定枝，陽台云雨梦中归。","他年蓬島音塵斷，留取尊前旧舞衣。"]', '诗', 'shi', '', NULL, '書歌妓泥金帶 韓熙載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18f70208-5a28-4c02-b8ef-0cb1dda12c13', '送徐鉉流舒州', '送徐鉉流舒州', '32eb2807-6231-496d-ad1c-c603369da4ff', '唐', '["昔年悽斷此江湄，風滿征帆淚滿衣。","今日重憐鶺鴒羽，不堪波上又分飛。"]', '["昔年悽斷此江湄，风满征帆泪满衣。","今日重怜鶺鴒羽，不堪波上又分飞。"]', '诗', 'shi', '', NULL, '送徐鉉流舒州 韓熙載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b362b1-0dbe-4571-9b58-e179b9cfd7ec', '句', '句', '32eb2807-6231-496d-ad1c-c603369da4ff', '唐', '["幾人平地上，看我半天中。"]', '["幾人平地上，看我半天中。"]', '诗', 'shi', '', NULL, '句 韓熙載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d041545-4f66-490b-8099-44aa8a820e8c', '登祝融峰', '登祝融峰', '8768290b-c7cc-42c3-8ee3-9500900af820', '唐', '["欲上祝融峰，先登古石橋。","鑿開巇嶮處，取路到丹霄。"]', '["欲上祝融峰，先登古石橋。","鑿开巇嶮处，取路到丹霄。"]', '诗', 'shi', '', NULL, '登祝融峰 李徵古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc3267e5-7cae-484d-beef-796a19bcefbb', '七歲吟', '七歲吟', '458918d8-a1b6-44cb-9338-181d6089e74f', '唐', '["朝遊滄海東，暮歸何太速。","祗因騎折白龍腰，謫向人間三十六。"]', '["朝游滄海东，暮归何太速。","祗因騎折白龙腰，謫向人间三十六。"]', '诗', 'shi', '', NULL, '七歲吟 潘佑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f46dcbe8-c58a-446e-8082-fcdcffe727ad', '送許處士堅往茅山', '送許处士堅往茅山', '458918d8-a1b6-44cb-9338-181d6089e74f', '唐', '["天壇雲似雪，玉洞水如琴。","白雲與流水，千載清人心。","君攜布囊去，路長風滿林。","一入華陽洞，千秋那可尋。"]', '["天壇云似雪，玉洞水如琴。","白云與流水，千載清人心。","君携布囊去，路长风满林。","一入华陽洞，千秋那可尋。"]', '诗', 'shi', '', NULL, '送許處士堅往茅山 潘佑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54d8ab7a-622e-4dbb-9cb5-5159d4497fce', '送人往宣城', '送人往宣城', '458918d8-a1b6-44cb-9338-181d6089e74f', '唐', '["江畔送行人，千山生暮氛。","謝安團扇上，爲畫敬亭雲。"]', '["江畔送行人，千山生暮氛。","謝安團扇上，爲畫敬亭云。"]', '诗', 'shi', '', NULL, '送人往宣城 潘佑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('949fa54d-0f8e-46fb-9194-b42dbc1811f7', '失題', '失題', '458918d8-a1b6-44cb-9338-181d6089e74f', '唐', '["誰家舊宅春無主，深院簾垂杏花雨。","香飛綠瑣人未歸，巢燕承塵默無語。"]', '["誰家旧宅春無主，深院簾垂杏花雨。","香飞綠瑣人未归，巢燕承塵默無語。"]', '诗', 'shi', '', NULL, '失題 潘佑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2caf0313-abe1-4ec1-acd0-c02009f0dcb2', '句', '句', '458918d8-a1b6-44cb-9338-181d6089e74f', '唐', '["勸君此醉直須歡，明朝又是花狼藉。"]', '["勸君此醉直須歡，明朝又是花狼藉。"]', '诗', 'shi', '', NULL, '句 潘佑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99583e4b-a4a3-4498-8768-6d2edd91bd68', '寄孟賓于', '寄孟賓于', 'ff01fb75-c92d-4a5e-a9b8-da557c8ca673', '唐', '["初攜書劒別湘潭，金榜標名第十三。","昔日聲名喧洛下，近來詩價滿江南。","長爲邑令情終屈，縱處曹郎志未甘。","莫學馮唐便休去，明君晚事未爲慚。"]', '["初携书劒別湘潭，金榜標名第十三。","昔日声名喧洛下，近来诗價满江南。","长爲邑令情終屈，縱处曹郎志未甘。","莫学馮唐便休去，明君晚事未爲慚。"]', '诗', 'shi', '', NULL, '寄孟賓于 李昉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd7eb14d-cb20-4aa1-82fc-b9944057863b', '送孟賓于', '送孟賓于', '800e891d-0ef0-41ba-a68b-c2edaa4cd910', '唐', '["曾聞洛下綴神仙，火樹南棲幾十年。","白首自忻丹桂在，詩名已得四方傳。","行隨秋渚將歸雁，吟傍梅花欲雪天。","今日還家莫惆悵，不同初上渡頭船。"]', '["曾闻洛下綴神仙，火樹南棲幾十年。","白首自忻丹桂在，诗名已得四方傳。","行隨秋渚將归雁，吟傍梅花欲雪天。","今日還家莫惆悵，不同初上渡头船。"]', '诗', 'shi', '', NULL, '送孟賓于 馬致恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0e56e1e-22a7-4afa-8f2b-9da47aff3e0e', '奉和聖製元日大雪登樓', '奉和聖製元日大雪登楼', 'a98a8437-a502-46eb-901c-351c1f1e8d4a', '唐', '["恰當歲日紛紛落，天寶瑤花助物華。","自古最先標瑞牒，有誰輕擬比楊花。","密飄粉署光同冷，靜壓青松勢欲斜。","豈但小臣添興詠，狂歌醉舞一家家。"]', '["恰當歲日紛紛落，天寶瑤花助物华。","自古最先標瑞牒，有誰轻擬比楊花。","密飄粉署光同冷，静壓青松勢欲斜。","豈但小臣添兴詠，狂歌醉舞一家家。"]', '诗', 'shi', '', NULL, '奉和聖製元日大雪登樓 張義方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e5a98d-f8ae-4b5a-8fed-ee9651d6f57a', '中酒寄劉行軍', '中酒寄劉行軍', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["甚矣頻頻醉，神昏體亦虛。","肺傷徒問藥，髮落不盈梳。","戀寢嫌明室，修生媿道書。","西峯老僧語，相勸合何如。"]', '["甚矣頻頻醉，神昏體亦虛。","肺傷徒问藥，髮落不盈梳。","戀寢嫌明室，修生媿道书。","西峯老僧語，相勸合何如。"]', '诗', 'shi', '', NULL, '中酒寄劉行軍 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('430c58cd-8ce9-45e6-b188-27c66665bef4', '白雁', '白雁', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["東溪一白雁，毛羽何皎潔。","薄暮浴清波，斜陽共明滅。","差池失羣久，幽獨依人切。","旅食賴菰蒲，單棲怯霜雪。","邊風昨夜起，顧影空哀咽。","不及牆上烏，相將繞雙闕。"]', '["东溪一白雁，毛羽何皎潔。","薄暮浴清波，斜陽共明滅。","差池失羣久，幽独依人切。","旅食賴菰蒲，單棲怯霜雪。","邊风昨夜起，顧影空哀咽。","不及牆上烏，相將繞雙闕。"]', '诗', 'shi', '', NULL, '白雁 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50795a4e-7de6-4bf7-9d23-bdba4df0353e', '早春寄懷', '早春寄懷', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["家山歸未得，又是看春過。","老覺光陰速，閑悲世路多。","風和吹岸柳，雪盡見庭莎。","欲向東溪醉，狂眠一放歌。"]', '["家山归未得，又是看春過。","老覺光陰速，闲悲世路多。","风和吹岸柳，雪尽见庭莎。","欲向东溪醉，狂眠一放歌。"]', '诗', 'shi', '', NULL, '早春寄懷 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d848298e-f251-4ff7-9613-d7bc3da5490d', '春日東山正堂作', '春日东山正堂作', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["身閑贏得出，天氣漸暄和。","蜀馬登山穩，南朝古寺多。","早花微弄色，新酒欲生波。","從此唯行樂，閑愁奈我何。"]', '["身闲贏得出，天氣漸暄和。","蜀马登山穩，南朝古寺多。","早花微弄色，新酒欲生波。","從此唯行乐，闲愁奈我何。"]', '诗', 'shi', '', NULL, '春日東山正堂作 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10de17d0-7021-438f-9009-40f766eadfe3', '春日小園晨看兼招同舍', '春日小园晨看兼招同舍', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["最有杏花繁，枝枝若手摶。","須知一春促，莫厭百迴看。","鳥囀風潛息，蜂遲露未乾。","可容排飲否，兼折贈頭冠。"]', '["最有杏花繁，枝枝若手摶。","須知一春促，莫厭百迴看。","鸟囀风潛息，蜂遲露未乾。","可容排饮否，兼折贈头冠。"]', '诗', 'shi', '', NULL, '春日小園晨看兼招同舍 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daaff867-cd1e-4616-a2df-5edcc90ed68f', '惜花寄孫員外', '惜花寄孫員外', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["朝始一枝開，暮復一枝落。","只恐雨淋漓，又見春蕭索。","侵晨結駟攜酒徒，尋芳踏盡長安衢。","思量少壯不自樂，他日白頭空歎吁。"]', '["朝始一枝开，暮复一枝落。","只恐雨淋漓，又见春蕭索。","侵晨結駟携酒徒，尋芳踏尽长安衢。","思量少壯不自乐，他日白头空歎吁。"]', '诗', 'shi', '', NULL, '惜花寄孫員外 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eab45f3a-d018-4ecb-8d18-532640c1ceca', '春日病中', '春日病中', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["纔得歸閑去，還教病臥頻。","無由全勝意，終是負青春。","綠柳漸拂地，黃鶯如喚人。","方爲醫者勸，斷酒已經旬。"]', '["纔得归闲去，還教病臥頻。","無由全勝意，終是負青春。","綠柳漸拂地，黄鶯如喚人。","方爲醫者勸，斷酒已經旬。"]', '诗', 'shi', '', NULL, '春日病中 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fef28786-86fb-443d-b3f2-2700a8d625cb', '毆妓', '毆妓', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["自爲專房甚，怱怱有所傷。","當時心已悔，徹夜手猶香。","恨枕堆雲髻，啼襟揾月黃。","起來猶忍惡，剪破繡鴛鴦。"]', '["自爲專房甚，怱怱有所傷。","當时心已悔，徹夜手猶香。","恨枕堆云髻，啼襟揾月黄。","起来猶忍惡，剪破繡鴛鴦。"]', '诗', 'shi', '', NULL, '毆妓 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41799d3-50e1-4067-be68-84cb21afaab6', '踏青罇前', '踏青罇前', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["期君速行樂，不要旋還家。","永日雖無雨，東風自落花。","詩毫黏酒淡，歌袖向人斜。","薄暮忘歸路，垂楊噪亂鵶。"]', '["期君速行乐，不要旋還家。","永日雖無雨，东风自落花。","诗毫黏酒淡，歌袖向人斜。","薄暮忘归路，垂楊噪亂鵶。"]', '诗', 'shi', '', NULL, '踏青罇前 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a8fb253-5414-42a3-acd5-3e9ef673286d', '正月晦日', '正月晦日', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["莫倦尋春去，都無百日遊。","更堪正月過，已是一分休。","泉暖聲纔出，雲寒勢未收。","晚來重作雪，翻爲杏花愁。"]', '["莫倦尋春去，都無百日游。","更堪正月過，已是一分休。","泉暖声纔出，云寒勢未收。","晚来重作雪，翻爲杏花愁。"]', '诗', 'shi', '', NULL, '正月晦日 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b64961c-38ee-45bc-8903-ffaef335fb89', '惜花', '惜花', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["白髮今如此，紅芳莫更催。","預愁多日謝，翻怕十分開。","點滴無時雨，荒涼滿地苔。","閑堦一桮酒，惟待故人來。"]', '["白髮今如此，紅芳莫更催。","預愁多日謝，翻怕十分开。","点滴無时雨，荒涼满地苔。","闲堦一桮酒，惟待故人来。"]', '诗', 'shi', '', NULL, '惜花 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6858d85e-df5a-4d83-9332-61794820725a', '金谷園落花', '金谷园落花', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["愁見清明後，紛紛蓋地紅。","惜看難過日，自落不因風。","蝶散餘香在，鶯啼半樹空。","堪悲一尊酒，從此似西東。"]', '["愁见清明後，紛紛蓋地紅。","惜看难過日，自落不因风。","蝶散餘香在，鶯啼半樹空。","堪悲一尊酒，從此似西东。"]', '诗', 'shi', '', NULL, '金谷園落花 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd13e8d5-fced-41b5-bbe1-1d5660aee5fb', '柳花寄宋明府', '柳花寄宋明府', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["每愛江城裏，青春向盡時。","一迴新雨歇，是處好風吹。","破石黏蟲網，高樓撲酒旗。","遙知陶令宅，五樹正離披。"]', '["每愛江城裏，青春向尽时。","一迴新雨歇，是处好风吹。","破石黏蟲網，高楼撲酒旗。","遙知陶令宅，五樹正離披。"]', '诗', 'shi', '', NULL, '柳花寄宋明府 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3385b1-ff12-4c71-b7b8-84b2593a1299', '送人', '送人', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["相見未逾月，堪悲遠別離。","非君誰顧我，萬里又南之。","雨逼清明日，花陰杜宇時。","愁看挂帆處，鷗鳥共遲遲。"]', '["相见未逾月，堪悲远別離。","非君誰顧我，万里又南之。","雨逼清明日，花陰杜宇时。","愁看挂帆处，鷗鸟共遲遲。"]', '诗', 'shi', '', NULL, '送人 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0b3ccc2-bfff-4e19-9a0a-bb0030f6546c', '閑遊', '闲游', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["攜酒復攜觴，朝朝一似忙。","馬諳頻到路，僧借舊眠牀。","道勝他圖薄，身閑白日長。","扁舟動歸思，高處見滄浪。"]', '["携酒复携觴，朝朝一似忙。","马諳頻到路，僧借旧眠牀。","道勝他圖薄，身闲白日长。","扁舟动归思，高处见滄浪。"]', '诗', 'shi', '', NULL, '閑遊 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e80f32a4-ebf5-4ab0-afcf-b09e159a2ebd', '栢梁隔句韻詩', '栢梁隔句韻诗', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["不喜長亭柳，枝枝擬送君。","惟憐北窗□，樹樹解留人。","圓缺都如月，東西只似雲。","愁看離席散，歸蓋動行塵。"]', '["不喜长亭柳，枝枝擬送君。","惟怜北窗□，樹樹解留人。","圓缺都如月，东西只似云。","愁看離席散，归蓋动行塵。"]', '诗', 'shi', '', NULL, '栢梁隔句韻詩 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c014ad-5e4f-47c9-9a80-3ac7320c79be', '贈趙學士', '贈趙学士', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["常欽趙夫子，遠作五侯賓。","見面到今日，操心如古人。","醉同華席少，吟訪野僧頻。","寂寂長河畔，荒齋與廟隣。"]', '["常欽趙夫子，远作五侯賓。","见面到今日，操心如古人。","醉同华席少，吟訪野僧頻。","寂寂长河畔，荒斋與廟隣。"]', '诗', 'shi', '', NULL, '贈趙學士 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e216b0f6-abd9-48f6-bb92-547a6c142b0b', '春陰', '春陰', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["老雨不肯休，東風勢還作。","未放草蒙茸，已遣花蕭索。","浮生何苦勞，觸事妨行樂。","寄語達生人，須知酒勝藥。"]', '["老雨不肯休，东风勢還作。","未放草蒙茸，已遣花蕭索。","浮生何苦勞，觸事妨行乐。","寄語達生人，須知酒勝藥。"]', '诗', 'shi', '', NULL, '春陰 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96eea1d5-da49-46fc-9f8b-2b729959e72f', '春日金谷園', '春日金谷园', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["火急召親賓，歡遊莫厭頻。","日長徒似歲，花過即非春。","晚雨來何定，東風自不勻。","須知三箇月，不是負芳晨。"]', '["火急召親賓，歡游莫厭頻。","日长徒似歲，花過即非春。","晚雨来何定，东风自不勻。","須知三箇月，不是負芳晨。"]', '诗', 'shi', '', NULL, '春日金谷園 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dac0699b-eeca-4e71-8001-80d7ba4e9106', '夏日酬祥松二公見訪', '夏日酬祥松二公见訪', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["多謝空門客，時時出草堂。","從容非有約，淡薄不相忘。","池映春篁老，簷垂夏果香。","西峯正清霽，自與拂吟牀。"]', '["多謝空门客，时时出草堂。","從容非有約，淡薄不相忘。","池映春篁老，簷垂夏果香。","西峯正清霽，自與拂吟牀。"]', '诗', 'shi', '', NULL, '夏日酬祥松二公見訪 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('211bc9e5-75b6-4da9-be84-45521d0bd47a', '懷贈操禪師', '懷贈操禪師', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["嘗憶曹溪子，龕居面碧嵩。","杉松新夏後，雨雹夜禪中。","道匪因經悟，心能向物空。","秋來得音信，又在剡山東。"]', '["嘗憶曹溪子，龕居面碧嵩。","杉松新夏後，雨雹夜禪中。","道匪因經悟，心能向物空。","秋来得音信，又在剡山东。"]', '诗', 'shi', '', NULL, '懷贈操禪師 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c58422a-13e8-4a56-b139-d0f7c28c647a', '閑居秋思呈祥松二字', '闲居秋思呈祥松二字', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["秋光雖即好，客思轉悠哉。","去國身將老，流年雁又來。","葉紅堆晚徑，菊冷藉空罍。","不得師相訪，難將道自開。"]', '["秋光雖即好，客思轉悠哉。","去国身將老，流年雁又来。","葉紅堆晚徑，菊冷藉空罍。","不得師相訪，难將道自开。"]', '诗', 'shi', '', NULL, '閑居秋思呈祥松二字 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4ac580a-af1f-48ba-bada-f4cb33428560', '賦得冬日青溪草堂四十字', '賦得冬日青溪草堂四十字', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["莫道無幽致，常來到日西。","地雖當北闕，天與設東溪。","疎葦寒多折，驚鳧去不齊。","坐中皆作者，長愛覓分題。"]', '["莫道無幽致，常来到日西。","地雖當北闕，天與設东溪。","疎葦寒多折，驚鳧去不齊。","坐中皆作者，长愛覓分題。"]', '诗', 'shi', '', NULL, '賦得冬日青溪草堂四十字 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf139b23-fe98-48b3-8b60-b12d7c4b3773', '溪齋', '溪斋', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["水木遶吾廬，搴簾晚檻虛。","衰條寒露鵲，幽果落驚魚。","愛酒貧還甚，趨時老更疎。","乖慵自有素，不是忽簪裾。"]', '["水木遶吾廬，搴簾晚檻虛。","衰條寒露鵲，幽果落驚鱼。","愛酒貧還甚，趨时老更疎。","乖慵自有素，不是忽簪裾。"]', '诗', 'shi', '', NULL, '溪齋 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0030fc9-0c71-42c3-9d3b-221f155ba287', '留題愛敬寺', '留題愛敬寺', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["野性竟未改，何以居朝廷。","空爲百官首，但愛千峯青。","南風新雨後，與客攜觴行。","斜陽惜歸去，萬壑啼鳥聲。"]', '["野性竟未改，何以居朝廷。","空爲百官首，但愛千峯青。","南风新雨後，與客携觴行。","斜陽惜归去，万壑啼鸟声。"]', '诗', 'shi', '', NULL, '留題愛敬寺 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c043722-16b0-4de6-a3bd-68cd3a9c2a4f', '小園', '小园', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["小園吾所好，栽植忘勞形。","晚果經秋赤，寒蔬近社青。","竹蘿荒引蔓，土井淺生萍。","更欲從人勸，憑高置草亭。"]', '["小园吾所好，栽植忘勞形。","晚果經秋赤，寒蔬近社青。","竹蘿荒引蔓，土井淺生萍。","更欲從人勸，憑高置草亭。"]', '诗', 'shi', '', NULL, '小園 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f09e72a-fdd1-4e96-bee9-061ebe3396df', '宿山房', '宿山房', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["石窗燈欲盡，松檻月還明。","就枕渾無睡，披衣却出行。","巖高泉亂滴，林動鳥時驚。","倏忽山鐘曙，喧喧僕馬聲。"]', '["石窗灯欲尽，松檻月還明。","就枕渾無睡，披衣却出行。","巖高泉亂滴，林动鸟时驚。","倏忽山鐘曙，喧喧僕马声。"]', '诗', 'shi', '', NULL, '宿山房 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49241607-83c3-4d27-b8f1-eb65a63bdd6e', '金陵所居青溪草堂閑興', '金陵所居青溪草堂闲兴', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["窗外皆連水，杉松欲作林。","自憐趨競地，獨有愛閑心。","素壁題看遍，危冠醉不簪。","江僧暮相訪，簾卷見秋岑。"]', '["窗外皆連水，杉松欲作林。","自怜趨競地，独有愛闲心。","素壁題看遍，危冠醉不簪。","江僧暮相訪，簾卷见秋岑。"]', '诗', 'shi', '', NULL, '金陵所居青溪草堂閑興 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94af9972-9a17-4f27-993b-2556503f58fc', '闕下偶書寄孫員外', '闕下偶书寄孫員外', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["長安驅馳地，貴賤共悠悠。","白日誰相促，勞生自不休。","鳳翔雙闕曉，蟬噪六街秋。","獨有南宮客，時來話釣舟。"]', '["长安驱驰地，貴賤共悠悠。","白日誰相促，勞生自不休。","鳳翔雙闕晓，蟬噪六街秋。","独有南宮客，时来話釣舟。"]', '诗', 'shi', '', NULL, '闕下偶書寄孫員外 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cce7d01a-5e76-420a-9ed6-d50efcc8f651', '寄魏郎中', '寄魏郎中', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["碌碌但隨羣，蒿蘭任不分。","未嘗矜有道，求遇向吾君。","逸駕秋尋寺，長歌醉望雲。","高齋紙屏古，塵暗北山文。"]', '["碌碌但隨羣，蒿蘭任不分。","未嘗矜有道，求遇向吾君。","逸駕秋尋寺，长歌醉望云。","高斋紙屏古，塵暗北山文。"]', '诗', 'shi', '', NULL, '寄魏郎中 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d737630-e386-4505-85f5-4b323a1d37c2', '病中書懷寄王二十六', '病中书懷寄王二十六', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["落葉滿山州，閑眠病未瘳。","窗陰連竹枕，藥氣染茶甌。","路匪人遮去，官須自覓休。","焉宜更羸老，扶杖作公侯。"]', '["落葉满山州，闲眠病未瘳。","窗陰連竹枕，藥氣染茶甌。","路匪人遮去，官須自覓休。","焉宜更羸老，扶杖作公侯。"]', '诗', 'shi', '', NULL, '病中書懷寄王二十六 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d741e7d5-1b00-4480-bea0-6405f505950b', '採菊', '採菊', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["簇簇竟相鮮，一枝開幾番。","味甘資麴糵，香好勝蘭蓀。","古道風搖遠，荒籬露壓繁。","盈筐時採得，服餌近知門。"]', '["簇簇竟相鲜，一枝开幾番。","味甘資麴糵，香好勝蘭蓀。","古道风搖远，荒籬露壓繁。","盈筐时採得，服餌近知门。"]', '诗', 'shi', '', NULL, '採菊 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde2f140-5dcb-45b1-be3e-2c44525b74fa', '送王郎中之官吉水', '送王郎中之官吉水', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["南望廬陵郡，山連五嶺長。","吾君憐遠俗，從事輟名郎。","移戶多無土，春蠶不滿筐。","惟應勞贊畫，溪峒況彊梁。"]', '["南望廬陵郡，山連五嶺长。","吾君怜远俗，從事輟名郎。","移戶多無土，春蠶不满筐。","惟應勞贊畫，溪峒況彊梁。"]', '诗', 'shi', '', NULL, '送王郎中之官吉水 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('395dfe8f-d365-4004-aa64-1a9ace4fe391', '孤雁', '孤雁', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["欲食不敢食，合栖猶未栖。","聞風亦驚過，避繳恨飛低。","水闊緣湘因，雲寒過磧迷。","悲鳴感人意，不見夜烏啼。"]', '["欲食不敢食，合栖猶未栖。","闻风亦驚過，避繳恨飞低。","水闊緣湘因，云寒過磧迷。","悲鳴感人意，不见夜烏啼。"]', '诗', 'shi', '', NULL, '孤雁 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de2c988f-b1d7-4f6f-9941-360a899b75dc', '贈送致仕郎中', '贈送致仕郎中', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["鶴立瘦稜稜，髭長白似銀。","衣冠皆古製，氣貌異常人。","聽雪添詩思，看山滯酒巡。","西峯重歸路，唯許野僧親。"]', '["鹤立瘦稜稜，髭长白似銀。","衣冠皆古製，氣貌異常人。","听雪添诗思，看山滯酒巡。","西峯重归路，唯許野僧親。"]', '诗', 'shi', '', NULL, '贈送致仕郎中 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32d62146-5646-4252-ba15-854c9df4344e', '宿友人山居寄司徒相公 一', '宿友人山居寄司徒相公 一', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["雨雪正霏霏，令人不憶歸。","地爐僧坐暖，山枿火聲肥。","隔紙烘茶蘂，移鐺剝芋衣。","知君在霄漢，此興得還稀。"]', '["雨雪正霏霏，令人不憶归。","地爐僧坐暖，山枿火声肥。","隔紙烘茶蘂，移鐺剝芋衣。","知君在霄漢，此兴得還稀。"]', '诗', 'shi', '', NULL, '宿友人山居寄司徒相公 一 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd74f109-f401-4227-817a-f7dd923efc3f', '宿友人山居寄司徒相公 二', '宿友人山居寄司徒相公 二', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["郢客相尋夜，荒庭雪灑篙。","虛堂看向曙，吟坐共忘勞。","溪凍聲全減，燈寒焰不高。","他人莫相笑，未易會吾曹。"]', '["郢客相尋夜，荒庭雪灑篙。","虛堂看向曙，吟坐共忘勞。","溪凍声全減，灯寒焰不高。","他人莫相笑，未易會吾曹。"]', '诗', 'shi', '', NULL, '宿友人山居寄司徒相公 二 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcd224b0-89c8-4371-93cd-0c715002720e', '感故府二首 一', '感故府二首 一', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["戚戚復戚戚，期懷安可釋。","百年金石心，中路生死隔。","新墳應草合，舊地空苔色。","白日燈熒熒，凝塵滿几席。"]', '["戚戚复戚戚，期懷安可釋。","百年金石心，中路生死隔。","新墳應草合，旧地空苔色。","白日灯熒熒，凝塵满几席。"]', '诗', 'shi', '', NULL, '感故府二首 一 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02723ded-c993-41ed-bd0c-b8f559e9bda1', '感故府二首 二', '感故府二首 二', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["悒悒復悒悒，思君安可及。","永日在堦前，披衣隨風立。","高樓暮角斷，遠樹寒鴉集。","惆悵幾行書，遺蹤墨猶濕。"]', '["悒悒复悒悒，思君安可及。","永日在堦前，披衣隨风立。","高楼暮角斷，远樹寒鴉集。","惆悵幾行书，遺蹤墨猶濕。"]', '诗', 'shi', '', NULL, '感故府二首 二 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc93d6a1-981e-409f-8652-cdfcb41e9783', '田家三首 一', '田家三首 一', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["畢歲知無事，兵銷復舊丁。","竹門桑徑狹，春日稻畦青。","犬吠隈籬落，雞飛上碓桯。","歸田起□思，蛙叫草冥冥。"]', '["畢歲知無事，兵銷复旧丁。","竹门桑徑狹，春日稻畦青。","犬吠隈籬落，雞飞上碓桯。","归田起□思，蛙叫草冥冥。"]', '诗', 'shi', '', NULL, '田家三首 一 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d678d3db-4821-4880-a373-85b3d19f5735', '田家三首 二', '田家三首 二', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["不識城中路，熙熙樂有年。","木槃擎社酒，瓦鼓送神錢。","霜落牛歸屋，禾收雀滿田。","遙陂過秋水，閑閣釣魚船。"]', '["不識城中路，熙熙乐有年。","木槃擎社酒，瓦鼓送神錢。","霜落牛归屋，禾收雀满田。","遙陂過秋水，闲閣釣鱼船。"]', '诗', 'shi', '', NULL, '田家三首 二 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('649f46d0-c827-4fb0-942d-dec4c4840a67', '田家三首 三', '田家三首 三', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["長愛田家事，時時欲一過。","垣籬皆樹槿，廳院亦堆禾。","病果因風落，寒蔬向日多。","遙聞數聲笛，牛晚下前坡。"]', '["长愛田家事，时时欲一過。","垣籬皆樹槿，廳院亦堆禾。","病果因风落，寒蔬向日多。","遙闻數声笛，牛晚下前坡。"]', '诗', 'shi', '', NULL, '田家三首 三 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee6d7492-2367-4e5f-a3ad-1b7d81b6e765', '新竹', '新竹', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["嫋嫋薰風軟，娟娟湛露光。","參差仙子仗，迤邐羽林槍。","迥去侵花地，斜來破蘚牆。","籜乾猶抱翠，粉膩若塗裝。","逕曲莖難數，陰疎葉未長。","嬾嫌吟客倚，甘畏夏蟲傷。","映水如爭立，當軒自著行。","北庭尊酒興，還爲此君狂。"]', '["嫋嫋薰风軟，娟娟湛露光。","參差仙子仗，迤邐羽林槍。","迥去侵花地，斜来破蘚牆。","籜乾猶抱翠，粉膩若塗裝。","逕曲莖难數，陰疎葉未长。","嬾嫌吟客倚，甘畏夏蟲傷。","映水如爭立，當軒自著行。","北庭尊酒兴，還爲此君狂。"]', '诗', 'shi', '', NULL, '新竹 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1fa8bf6-82b6-4c5b-9741-075c14f73e5a', '歸燕詞', '归燕词', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["羽翼勢雖微，雲霄亦可期。","飛翻自有路，鴻鵠莫相嗤。","待侶臨書幌，尋泥傍藻池。","衝人穿柳徑，捕蝶遶花枝。","廣廈來應徧，深宮去不疑。","雕梁聲上下，煙浦影參差。","舊地人潛換，新巢雀謾窺。","雙雙暮歸處，疎雨滿江湄。"]', '["羽翼勢雖微，云霄亦可期。","飞翻自有路，鴻鵠莫相嗤。","待侶臨书幌，尋泥傍藻池。","衝人穿柳徑，捕蝶遶花枝。","廣廈来應徧，深宮去不疑。","雕梁声上下，煙浦影參差。","旧地人潛換，新巢雀謾窺。","雙雙暮归处，疎雨满江湄。"]', '诗', 'shi', '', NULL, '歸燕詞 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('885206a6-c0a5-4f13-8f78-327815ce2140', '題魏壇二首 一', '題魏壇二首 一', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["不遇至真傳道要，曾看真誥亦何爲。","舊碑經亂沈荒澗，靈篆因耕出故基。","蛙黽自喧澆藥井，牛羊閑過放生池。","蕭條夕景空壇畔，朽檜枝斜綠蔓垂。"]', '["不遇至真傳道要，曾看真誥亦何爲。","旧碑經亂沈荒澗，靈篆因耕出故基。","蛙黽自喧澆藥井，牛羊闲過放生池。","蕭條夕景空壇畔，朽檜枝斜綠蔓垂。"]', '诗', 'shi', '', NULL, '題魏壇二首 一 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d28001d-793e-47ea-885c-371ec9145af5', '題魏壇二首 二', '題魏壇二首 二', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["一尋遺跡到仙鄉，雲鶴沈沈思渺茫。","丹井歲深生草木，芝田春廢臥牛羊。","雨淋殘畫摧荒壁，鼠引飢虵落壞梁。","薄暮欲歸仍佇立，菖蒲風起水泱泱。"]', '["一尋遺跡到仙乡，云鹤沈沈思渺茫。","丹井歲深生草木，芝田春廢臥牛羊。","雨淋殘畫摧荒壁，鼠引飢虵落壞梁。","薄暮欲归仍佇立，菖蒲风起水泱泱。"]', '诗', 'shi', '', NULL, '題魏壇二首 二 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbdfa90f-36bb-4661-bf03-c661bf6fbdd4', '東樓看雪', '东楼看雪', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["一上高樓醉復醒，日西江雪更冥冥。","化風吹火全無氣，平望惟松少露青。","臘內不妨南地少，夜長應得小窗聽。","因思舊隱匡廬日，閑看杉檉掩石扃。"]', '["一上高楼醉复醒，日西江雪更冥冥。","化风吹火全無氣，平望惟松少露青。","臘內不妨南地少，夜长應得小窗听。","因思旧隐匡廬日，闲看杉檉掩石扃。"]', '诗', 'shi', '', NULL, '東樓看雪 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b598b29c-4f70-435d-846c-5ad0f19efc4d', '落花', '落花', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["惜花無計又花殘，獨遶芳叢不忍看。","暖豔動隨鶯翅落，冷香愁雜燕泥乾。","綠珠倚檻魂初散，巫峽歸雲夢又闌。","忍把一尊重命樂，送春招客亦何歡。"]', '["惜花無計又花殘，独遶芳叢不忍看。","暖豔动隨鶯翅落，冷香愁杂燕泥乾。","綠珠倚檻魂初散，巫峽归云梦又闌。","忍把一尊重命乐，送春招客亦何歡。"]', '诗', 'shi', '', NULL, '落花 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63302b0f-792a-4dcc-bea7-6651839bb5a7', '春雪', '春雪', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["南國春寒朔氣迴，霏霏還阻百花開。","全移暖律何方去，似誤新鶯昨日來。","平野旋銷難蔽草，遠林高綴却遮梅。","不知金勒誰家子，只待晴明賞帝臺。"]', '["南国春寒朔氣迴，霏霏還阻百花开。","全移暖律何方去，似誤新鶯昨日来。","平野旋銷难蔽草，远林高綴却遮梅。","不知金勒誰家子，只待晴明賞帝台。"]', '诗', 'shi', '', NULL, '春雪 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2500ec18-5118-4c60-9d0e-827c27bc23dc', '重戲和春雪寄沈員外', '重戲和春雪寄沈員外', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["誰道江南要雪難，半春猶得倚樓看。","却遮遲日偷鶯暖，密灑西風借鶴寒。","散漫不容梨豔去，輕明應笑玉華乾。","和來瓊什雖無敵，且是儂家比興殘。"]', '["誰道江南要雪难，半春猶得倚楼看。","却遮遲日偷鶯暖，密灑西风借鹤寒。","散漫不容梨豔去，轻明應笑玉华乾。","和来瓊什雖無敵，且是儂家比兴殘。"]', '诗', 'shi', '', NULL, '重戲和春雪寄沈員外 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d2ce5a-3f52-4e25-b8c7-0b5c395a7b9b', '春日尊前示從事', '春日尊前示從事', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["州中案牘魚鱗密，界上軍書竹節稠。","眼底好花渾似雪，甕頭春酒漫如油。","東君不爲留遲日，清鏡唯知促白頭。","最覺此春無氣味，不如庭草解忘憂。"]', '["州中案牘鱼鱗密，界上軍书竹節稠。","眼底好花渾似雪，甕头春酒漫如油。","东君不爲留遲日，清镜唯知促白头。","最覺此春無氣味，不如庭草解忘憂。"]', '诗', 'shi', '', NULL, '春日尊前示從事 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf5c9f8-dd95-460e-a41f-af31d586d521', '尊前', '尊前', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["官爲將相復何求，世路多端早合休。","漸老更知春可惜，正歡唯怕客難留。","雨催草色還依舊，晴放花枝始自由。","莫厭百壺相勸倒，免教無事結閑愁。"]', '["官爲將相复何求，世路多端早合休。","漸老更知春可惜，正歡唯怕客难留。","雨催草色還依旧，晴放花枝始自由。","莫厭百壺相勸倒，免教無事結闲愁。"]', '诗', 'shi', '', NULL, '尊前 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f85fe346-311e-4df1-9372-9ffde856db78', '薔薇二首 一', '薔薇二首 一', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["萬蘂爭開照檻光，詩家何物可相方。","錦江風撼雲霞碎，仙子衣飄黼黻香。","裛露早英濃壓架，背人狂蔓暗穿牆。","綵牋蠻榼旬休日，欲召親賓看一場。"]', '["万蘂爭开照檻光，诗家何物可相方。","錦江风撼云霞碎，仙子衣飄黼黻香。","裛露早英濃壓架，背人狂蔓暗穿牆。","綵牋蠻榼旬休日，欲召親賓看一場。"]', '诗', 'shi', '', NULL, '薔薇二首 一 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeed933b-535b-4678-873e-950374568c82', '薔薇二首 二', '薔薇二首 二', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["拂簷拖地對前墀，蝶影蜂聲爛熳時。","萬倍馨香勝玉蘂，一生顏色笑西施。","忘歸醉客臨高架，恃寵佳人索好枝。","將並舞腰誰得及，惹衣傷手盡從伊。"]', '["拂簷拖地对前墀，蝶影蜂声爛熳时。","万倍馨香勝玉蘂，一生顏色笑西施。","忘归醉客臨高架，恃寵佳人索好枝。","將並舞腰誰得及，惹衣傷手尽從伊。"]', '诗', 'shi', '', NULL, '薔薇二首 二 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85a6623e-0b79-4396-9cf4-fdeb8f5589f3', '殘牡丹', '殘牡丹', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["腸斷題詩如執別，芳茵愁更繞闌鋪。","風飄金蘂看全落，露滴檀英又暫蘇。","失意婕妤妝漸薄，背身妃子病難扶。","迴看池館春休也，又是迢迢看畫圖。"]', '["腸斷題诗如執別，芳茵愁更繞闌鋪。","风飄金蘂看全落，露滴檀英又暫蘇。","失意婕妤妝漸薄，背身妃子病难扶。","迴看池館春休也，又是迢迢看畫圖。"]', '诗', 'shi', '', NULL, '殘牡丹 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f125e89-3225-4935-bcd7-3a27b3975b6a', '春雨二首 一', '春雨二首 一', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["春霖未免妨遊賞，唯到詩家自有情。","花徑不通新草合，蘭舟初動曲池平。","淨緣高樹莓苔色，飢集虛廊燕雀聲。","閑憶昔年爲客處，悶留山館阻行行。"]', '["春霖未免妨游賞，唯到诗家自有情。","花徑不通新草合，蘭舟初动曲池平。","淨緣高樹莓苔色，飢集虛廊燕雀声。","闲憶昔年爲客处，悶留山館阻行行。"]', '诗', 'shi', '', NULL, '春雨二首 一 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6159a192-4c05-478b-804f-654ebb514aef', '春雨二首 二', '春雨二首 二', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["蕭蕭春雨密還疎，景象三時固不如。","寒入遠林鶯翅重，暖抽新麥土膏虛。","細濛臺榭微兼日，潛漲漣漪欲動魚。","唯稱乖慵多睡者，掩門中酒覽閑書。"]', '["蕭蕭春雨密還疎，景象三时固不如。","寒入远林鶯翅重，暖抽新麦土膏虛。","細濛台榭微兼日，潛漲漣漪欲动鱼。","唯稱乖慵多睡者，掩门中酒覽闲书。"]', '诗', 'shi', '', NULL, '春雨二首 二 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26859c26-4330-4704-acaa-2961b2ff0f04', '醉中惜花更書與諸從事', '醉中惜花更书與諸從事', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["公退尋芳已是遲，莫因他事更來稀。","未經旬日唯憂落，算有開時不合歸。","歌檻宴餘風褭褭，閑園吟散雨霏霏。","高樓鼓絕重門閉，長爲拋迴恨解衣。"]', '["公退尋芳已是遲，莫因他事更来稀。","未經旬日唯憂落，算有开时不合归。","歌檻宴餘风褭褭，闲园吟散雨霏霏。","高楼鼓絕重门閉，长爲拋迴恨解衣。"]', '诗', 'shi', '', NULL, '醉中惜花更書與諸從事 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fba7a4e-5ee0-4ba6-bc7f-56a9570954b3', '和判官喜雨', '和判官喜雨', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["去禱山川尚未還，雲雷尋作遠聲寒。","人情便似秋登悅，天色休勞夜起看。","高檻氣濃藏柳郭，小庭流擁沒花壇。","須知太守重牆內，心極農夫望處歡。"]', '["去禱山川尚未還，云雷尋作远声寒。","人情便似秋登悅，天色休勞夜起看。","高檻氣濃藏柳郭，小庭流擁沒花壇。","須知太守重牆內，心極農夫望处歡。"]', '诗', 'shi', '', NULL, '和判官喜雨 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2448723-48a4-4953-8125-26010aa28a06', '離闕下日感恩', '離闕下日感恩', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["二年塵冒處中台，喜得南歸退不才。","即路敢期皇子送，出關猶有御書來。","未知天地恩何報，翻對江山思莫開。","斜日葦汀凝立處，遠波微颺翠如苔。"]', '["二年塵冒处中台，喜得南归退不才。","即路敢期皇子送，出关猶有御书来。","未知天地恩何報，翻对江山思莫开。","斜日葦汀凝立处，远波微颺翠如苔。"]', '诗', 'shi', '', NULL, '離闕下日感恩 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d20ad00a-b082-42a9-8746-602ca4d0a5be', '細雨遙懷故人', '細雨遙懷故人', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["江雲未散東風暖，溟濛正在高樓見。","細柳緣堤少過人，平蕪隔水時飛燕。","我有近詩誰與和，憶君狂醉愁難破。","昨夜南窗不得眠，閑堦點滴迴燈坐。"]', '["江云未散东风暖，溟濛正在高楼见。","細柳緣堤少過人，平蕪隔水时飞燕。","我有近诗誰與和，憶君狂醉愁难破。","昨夜南窗不得眠，闲堦点滴迴灯坐。"]', '诗', 'shi', '', NULL, '細雨遙懷故人 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b859b5a3-5a70-411c-95a2-b77d3fc8d5fd', '春水', '春水', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["萬派爭流雨過時，晚來春靜更逶迤。","輕鷗散遶夫差國，遠樹微分夏禹祠。","青岸漸平濡柳帶，舊溪應暖負蓴絲。","風鬟倚檝誰家子，愁看鴛鴦望所之。"]', '["万派爭流雨過时，晚来春静更逶迤。","轻鷗散遶夫差国，远樹微分夏禹祠。","青岸漸平濡柳带，旧溪應暖負蓴絲。","风鬟倚檝誰家子，愁看鴛鴦望所之。"]', '诗', 'shi', '', NULL, '春水 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c411a89d-2577-4088-959a-ffb5927cde5c', '蝶', '蝶', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["粉蝶翩翩若有期，南園長是到春歸。","閑依柳帶參差起，困傍桃花獨自飛。","潛被燕驚還散亂，偶因人逐入簾幃。","晚來欲雨東風急，迴看池塘影漸稀。"]', '["粉蝶翩翩若有期，南园长是到春归。","闲依柳带參差起，困傍桃花独自飞。","潛被燕驚還散亂，偶因人逐入簾幃。","晚来欲雨东风急，迴看池塘影漸稀。"]', '诗', 'shi', '', NULL, '蝶 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d882c545-6957-4bd4-8cf4-8f412c49d72a', '中春寫懷寄沈彬員外', '中春寫懷寄沈彬員外', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["省從騎竹學謳吟，便殢光陰役此心。","寓目不能閑一日，閉門長勝得千金。","窗懸夜雨殘燈在，庭掩春風落絮深。","唯有故人同此興，近來何事嬾相尋。"]', '["省從騎竹学謳吟，便殢光陰役此心。","寓目不能闲一日，閉门长勝得千金。","窗懸夜雨殘灯在，庭掩春风落絮深。","唯有故人同此兴，近来何事嬾相尋。"]', '诗', 'shi', '', NULL, '中春寫懷寄沈彬員外 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c622bbb-4810-4a02-9b03-9c19c636f7e3', '鍾山寺避暑勉二三子', '鍾山寺避暑勉二三子', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["樓臺雖少景何深，滿地青苔勝布金。","松影晚留僧共坐，水聲閑與客同尋。","清涼會擬歸蓮社，沈湎終須棄竹林。","長愛寄吟經案上，石窗秋霽向千岑。"]', '["楼台雖少景何深，满地青苔勝布金。","松影晚留僧共坐，水声闲與客同尋。","清涼會擬归蓮社，沈湎終須棄竹林。","长愛寄吟經案上，石窗秋霽向千岑。"]', '诗', 'shi', '', NULL, '鍾山寺避暑勉二三子 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bbc5827-0e78-4514-905b-95818e4732b2', '道林寺', '道林寺', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["雖向鍾峯數寺連，就中奇勝出其間。","不教幽樹妨閑地，別著高窗向遠山。","蓮沼水從雙澗入，客堂僧自九華還。","無因得結香燈社，空向王門玷玉班。"]', '["雖向鍾峯數寺連，就中奇勝出其间。","不教幽樹妨闲地，別著高窗向远山。","蓮沼水從雙澗入，客堂僧自九华還。","無因得結香灯社，空向王门玷玉班。"]', '诗', 'shi', '', NULL, '道林寺 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2af938a-ec66-4d45-be35-cac49777111f', '和致仕沈郎中', '和致仕沈郎中', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["欲謀休退尚因循，且向東溪種白蘋。","謬應星辰居四輔，終期冠褐作閑人。","城中隔日趨朝嬾，楚外千峯入夢頻。","殘照晚庭沈醉醒，靜吟斜倚老松身。"]', '["欲謀休退尚因循，且向东溪種白蘋。","謬應星辰居四輔，終期冠褐作闲人。","城中隔日趨朝嬾，楚外千峯入梦頻。","殘照晚庭沈醉醒，静吟斜倚老松身。"]', '诗', 'shi', '', NULL, '和致仕沈郎中 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f84b4da-a372-48d8-ad2f-ff44b0870f16', '醉中詠梅花', '醉中詠梅花', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["十月清霜尚未寒，雪英重疊已如摶。","還悲獨詠東園裏，老作南州刺史看。","北客見皆驚節氣，郡僚癡欲望盃盤。","交親罕至長安遠，一醉如泥豈自歡。"]', '["十月清霜尚未寒，雪英重叠已如摶。","還悲独詠东园裏，老作南州刺史看。","北客见皆驚節氣，郡僚癡欲望盃盤。","交親罕至长安远，一醉如泥豈自歡。"]', '诗', 'shi', '', NULL, '醉中詠梅花 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cac2fe6-686f-4688-83f1-da7bfa1e062e', '閑出書懷', '闲出书懷', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["閑遊何用問東西，寓興皆非有所期。","斷酒只攜僧共去，看山從聽馬行遲。","溪田雨漲禾生耳，原野鶯啼黍熟時。","應有交親長笑我，獨輕人事鬢將衰。"]', '["闲游何用问东西，寓兴皆非有所期。","斷酒只携僧共去，看山從听马行遲。","溪田雨漲禾生耳，原野鶯啼黍熟时。","應有交親长笑我，独轻人事鬢將衰。"]', '诗', 'shi', '', NULL, '閑出書懷 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee276a25-8216-4377-a74d-45a581aae9d3', '寺居陸處士相訪感懷却寄二三友人', '寺居陸处士相訪感懷却寄二三友人', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["湘寺閑居亦半年，就中昨夜好潸然。","人歸遠岫疎鐘後，雪打高杉古屋前。","投足正逢他國亂，冥心未解祖師禪。","爐煙向冷孤燈下，唯有寒吟到曙天。"]', '["湘寺闲居亦半年，就中昨夜好潸然。","人归远岫疎鐘後，雪打高杉古屋前。","投足正逢他国亂，冥心未解祖師禪。","爐煙向冷孤灯下，唯有寒吟到曙天。"]', '诗', 'shi', '', NULL, '寺居陸處士相訪感懷却寄二三友人 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c1c6580-3df1-44d0-a207-2362f407f742', '春雪', '春雪', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["隨風竟日勢漫漫，特地繁於故歲看。","幽榭凍黏花屋重，短簷斜濕燕巢寒。","閑聽不寐詩魂爽，淨喫無厭酒肺乾。","莫道便爲桑麥藥，亦勝焦涸到春殘。"]', '["隨风竟日勢漫漫，特地繁於故歲看。","幽榭凍黏花屋重，短簷斜濕燕巢寒。","闲听不寐诗魂爽，淨喫無厭酒肺乾。","莫道便爲桑麦藥，亦勝焦涸到春殘。"]', '诗', 'shi', '', NULL, '春雪 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca81a07-cd0a-40e9-8e5f-b4136ada501c', '惜花', '惜花', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["淡淡西園日又垂，一尊何忍負芳枝。","莫言風雨長相促，直是晴明得幾時。","心破只愁鶯踐落，眼穿唯怕客來遲。","年年使我成狂叟，腸斷紅牋幾首詩。"]', '["淡淡西园日又垂，一尊何忍負芳枝。","莫言风雨长相促，直是晴明得幾时。","心破只愁鶯踐落，眼穿唯怕客来遲。","年年使我成狂叟，腸斷紅牋幾首诗。"]', '诗', 'shi', '', NULL, '惜花 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c52be58f-f2e9-4b41-9178-44aa28c15cb7', '梅花寄所親', '梅花寄所親', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["一氣才新物未知，每慙青律與先吹。","雪霜迷素猶嫌早，桃杏雖紅且後時。","雲鬢自黏飄處粉，玉鞭誰指出牆枝。","老夫多病無風味，只向尊前詠舊詩。"]', '["一氣才新物未知，每慙青律與先吹。","雪霜迷素猶嫌早，桃杏雖紅且後时。","云鬢自黏飄处粉，玉鞭誰指出牆枝。","老夫多病無风味，只向尊前詠旧诗。"]', '诗', 'shi', '', NULL, '梅花寄所親 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9615461-b95b-4c77-80b1-b0a34a84b7e2', '登昇元閣', '登昇元閣', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["登高始覺太虛寬，白雪須知唱和難。","雲渡瑣窗金牓濕，月移珠箔水精寒。","九天星象簾前見，六代城池直下觀。","唯有上層人未到，金烏飛過拂闌干。"]', '["登高始覺太虛寬，白雪須知唱和难。","云渡瑣窗金牓濕，月移珠箔水精寒。","九天星象簾前见，六代城池直下观。","唯有上層人未到，金烏飞過拂闌干。"]', '诗', 'shi', '', NULL, '登昇元閣 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a649c5a-a616-4085-9a94-d3b80b1e0c80', '雪有作', '雪有作', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["霏霏奕奕滿寒空，況是難逢值臘中。","未白已堪張宴會，漸繁偏好去簾櫳。","庭莎易集看盈地，池柳難裝旋逐風。","長愛清華入詩句，預愁遲日放消融。"]', '["霏霏奕奕满寒空，況是难逢值臘中。","未白已堪張宴會，漸繁偏好去簾櫳。","庭莎易集看盈地，池柳难裝旋逐风。","长愛清华入诗句，預愁遲日放消融。"]', '诗', 'shi', '', NULL, '雪有作 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ba734c9-fa8a-4fd3-9dfe-38e0f961a755', '宮詞', '宮词', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["自遠凝旒守上陽，舞衣頓減舊朝香。","簾垂粉閣春將盡，門掩梨花日漸長。","草色深濃封輦路，水聲低咽轉宮牆。","君王一去不迴駕，皓齒青蛾空斷腸。"]', '["自远凝旒守上陽，舞衣頓減旧朝香。","簾垂粉閣春將尽，门掩梨花日漸长。","草色深濃封輦路，水声低咽轉宮牆。","君王一去不迴駕，皓齒青蛾空斷腸。"]', '诗', 'shi', '', NULL, '宮詞 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c1a0c6e-5881-44de-a4a5-bf3388c44919', '晚春送牡丹', '晚春送牡丹', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["攜觴邀客遶朱闌，腸斷殘春送牡丹。","風雨數來留不得，離披將謝忍重看。","氛氳蘭麝香初減，零落雲霞色漸乾。","借問少年能幾許，不須推酒厭桮盤。"]', '["携觴邀客遶朱闌，腸斷殘春送牡丹。","风雨數来留不得，離披將謝忍重看。","氛氳蘭麝香初減，零落云霞色漸乾。","借问少年能幾許，不須推酒厭桮盤。"]', '诗', 'shi', '', NULL, '晚春送牡丹 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fafbb7ae-fa9f-4f1e-83ed-71d959a7e4e6', '歲暮晚泊望廬山不見因懷岳僧呈察判', '歲暮晚泊望廬山不见因懷岳僧呈察判', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["貪程只爲看廬阜，及到停舟恨頗濃。","雲暗半空藏萬仞，雪迷雙瀑在中峯。","林端莫辨曾遊路，鳥際微聞向暮鐘。","長愧昔年招我入，共尋香社見芙蓉。"]', '["貪程只爲看廬阜，及到停舟恨頗濃。","云暗半空藏万仞，雪迷雙瀑在中峯。","林端莫辨曾游路，鸟際微闻向暮鐘。","长愧昔年招我入，共尋香社见芙蓉。"]', '诗', 'shi', '', NULL, '歲暮晚泊望廬山不見因懷岳僧呈察判 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea521fb1-4996-42b3-82b5-d02a6a4a0de4', '重臺蓮', '重台蓮', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["斜倚秋風絕比倫，千英和露染難勻。","自爲祥瑞生南國，誰把丹青寄北人。","明月幾宵同綠水，牡丹無路出紅塵。","憐伊不算多時立，贏得馨香暗上身。"]', '["斜倚秋风絕比倫，千英和露染难勻。","自爲祥瑞生南国，誰把丹青寄北人。","明月幾宵同綠水，牡丹無路出紅塵。","怜伊不算多时立，贏得馨香暗上身。"]', '诗', 'shi', '', NULL, '重臺蓮 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69b1b7d2-a95f-4c14-afc6-4712ea03c4c1', '迎神', '迎神', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["攂蠻鼉，吟塞笛，女巫結束分行立。","空中再拜神且來，滿奠椒漿齊獻揖。","陰風窣窣吹紙錢，妖巫瞑目傳神言。","與君降福爲豐年，莫教賽祀虧常筵。"]', '["攂蠻鼉，吟塞笛，女巫結束分行立。","空中再拜神且来，满奠椒漿齊獻揖。","陰风窣窣吹紙錢，妖巫瞑目傳神言。","與君降福爲豐年，莫教賽祀虧常筵。"]', '诗', 'shi', '', NULL, '迎神 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de26ce37-27b5-4252-85d6-e28fcd4f940f', '春詞', '春词', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["日高閑步下堂階，細草春莎沒繡鞋。","折得玫瑰花一朵，憑君簪向鳳皇釵。"]', '["日高闲步下堂階，細草春莎沒繡鞋。","折得玫瑰花一朵，憑君簪向鳳皇釵。"]', '诗', 'shi', '', NULL, '春詞 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00cb362d-2814-40dc-a7e7-c75d1dcdf307', '獨夜作', '独夜作', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["佳人一去無消息，夢覺香殘愁復入。","空庭悄悄月如霜，獨倚闌干伴花立。"]', '["佳人一去無消息，梦覺香殘愁复入。","空庭悄悄月如霜，独倚闌干伴花立。"]', '诗', 'shi', '', NULL, '獨夜作 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14aafa71-90cf-4156-9c6e-f26b8be6c3d5', '竹', '竹', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["瓊節高吹宿鳳枝，風流交我立忘歸。","最憐瑟瑟斜陽下，花影相和滿客衣。"]', '["瓊節高吹宿鳳枝，风流交我立忘归。","最怜瑟瑟斜陽下，花影相和满客衣。"]', '诗', 'shi', '', NULL, '竹 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db4fe9b-99dd-4c06-9f44-8ef674165e93', '清明日', '清明日', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["他皆攜酒尋芳去，我獨關門好靜眠。","唯有楊花似相覓，因風時復到牀前。"]', '["他皆携酒尋芳去，我独关门好静眠。","唯有楊花似相覓，因风时复到牀前。"]', '诗', 'shi', '', NULL, '清明日 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71901041-e74d-48b4-b41f-15456b4ea1b1', '宮詞', '宮词', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["宮門長閉舞衣閑，略識君王鬢便斑。","却羨落花春不管，御溝流得到人間。"]', '["宮门长閉舞衣闲，略識君王鬢便斑。","却羨落花春不管，御溝流得到人间。"]', '诗', 'shi', '', NULL, '宮詞 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c4582b-dc80-4b42-9254-c5bbedc3c0ca', '送喻鍊師歸茅山', '送喻鍊師归茅山', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["休糧知幾載，臉色似桃紅。","半醉離城去，單衣行雪中。","水聲茅洞曉，雲影石房空。","莫學秦時客，音書便不通。"]', '["休糧知幾載，臉色似桃紅。","半醉離城去，單衣行雪中。","水声茅洞晓，云影石房空。","莫学秦时客，音书便不通。"]', '诗', 'shi', '', NULL, '送喻鍊師歸茅山 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28108a90-daca-4cea-82f3-62d11e7800cc', '和元宗元日大雪登樓', '和元宗元日大雪登楼', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["紛紛忽降當元曾，著物輕明似月華。","狂灑玉墀初散絮，密黏宮樹未妨花。","迥封雙闕千尋峭，冷壓南山萬仞斜。","寧意傳來中使出，御題先賜老僧家。"]', '["紛紛忽降當元曾，著物轻明似月华。","狂灑玉墀初散絮，密黏宮樹未妨花。","迥封雙闕千尋峭，冷壓南山万仞斜。","寧意傳来中使出，御題先賜老僧家。"]', '诗', 'shi', '', NULL, '和元宗元日大雪登樓 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01643106-a50d-43ae-8e94-369cf471c3db', '遊棲霞寺', '游棲霞寺', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["養花天氣近平分，瘦馬來敲白下門。","曉色未開山意遠，春容猶淡月華昏。","琅琊冷落存遺跡，籬舍稀疎帶舊村。","此地幾經人聚散，只今王謝獨名存。"]', '["養花天氣近平分，瘦马来敲白下门。","晓色未开山意远，春容猶淡月华昏。","琅琊冷落存遺跡，籬舍稀疎带旧村。","此地幾經人聚散，只今王謝独名存。"]', '诗', 'shi', '', NULL, '遊棲霞寺 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea08fb0-5cec-4d60-83b9-edfe83ad9f5a', '答湯悅', '答湯悅', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["司空猶不作，那敢作司徒。","幸有山翁號，如何不見呼。"]', '["司空猶不作，那敢作司徒。","幸有山翁號，如何不见呼。"]', '诗', 'shi', '', NULL, '答湯悅 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec93488-8070-465d-95c1-0de241f0b2d3', '金山', '金山', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["不嗟白髮曾遊此，不歎征帆無了期。","盡日憑闌誰會我，祗悲不見韓垂詩。"]', '["不嗟白髮曾游此，不歎征帆無了期。","尽日憑闌誰會我，祗悲不见韓垂诗。"]', '诗', 'shi', '', NULL, '金山 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f5ef1be-c754-4000-86b5-be933da334cc', '送李冠', '送李冠', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["勻如春澗長流水，怨似秋枝欲斷蟬。","可惜人間容易聽，清聲不到御樓前。"]', '["勻如春澗长流水，怨似秋枝欲斷蟬。","可惜人间容易听，清声不到御楼前。"]', '诗', 'shi', '', NULL, '送李冠 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f70dd26c-8e11-4e27-97ae-4ee31eb7ac20', '遊宋興寺東巖', '游宋兴寺东巖', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["幾年不到東巖下，舊住僧亡屋亦無。","寒日蕭條何物在，朽松經燒石池枯。"]', '["幾年不到东巖下，旧住僧亡屋亦無。","寒日蕭條何物在，朽松經燒石池枯。"]', '诗', 'shi', '', NULL, '遊宋興寺東巖 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7b33b0a-c92b-4382-b620-3b7021025f1f', '批周宗書後', '批周宗书後', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["偶罷阿衡來典郡，固無閑可物應官。","憑君爲報羣胥道，莫作循州刺史看。"]', '["偶罷阿衡来典郡，固無闲可物應官。","憑君爲報羣胥道，莫作循州刺史看。"]', '诗', 'shi', '', NULL, '批周宗書後 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c904c1a-dbc8-4ef0-a843-08be459c9d39', '題信果觀壁', '題信果观壁', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["春來漲水流而活，曉色西山勢似行。","玉洞主人經劫在，攜竿步步就長生。"]', '["春来漲水流而活，晓色西山勢似行。","玉洞主人經劫在，携竿步步就长生。"]', '诗', 'shi', '', NULL, '題信果觀壁 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8128bebe-c97f-465f-942b-a9b6c63e0216', '送八分書與友人繼以詩', '送八分书與友人繼以诗', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["跁跒爲詩跁跒書，不封將去寄仙都。","仙翁拍手應相笑，得似秦朝次仲無。"]', '["跁跒爲诗跁跒书，不封將去寄仙都。","仙翁拍手應相笑，得似秦朝次仲無。"]', '诗', 'shi', '', NULL, '送八分書與友人繼以詩 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e86bdcc3-6013-4905-a780-a195f4bb3bbd', '句', '句', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["桃花流水須長信，不學劉郎去又來。","粟多未必全爲計，師老須防有伏兵。","徧尋雲壑重題石，欲下山門更倚松。"]', '["桃花流水須长信，不学劉郎去又来。","粟多未必全爲計，師老須防有伏兵。","徧尋云壑重題石，欲下山门更倚松。"]', '诗', 'shi', '', NULL, '句 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a00fa54-aa77-4726-9ea0-0866cc72208b', '蟠溪懷古', '蟠溪懷古', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["良哉呂尚父，深隱始歸周。","釣石千年在，春風一水流。","松根盤蘚石，花影臥沙鷗。","誰更懷韜術，追思古渡頭。"]', '["良哉呂尚父，深隐始归周。","釣石千年在，春风一水流。","松根盤蘚石，花影臥沙鷗。","誰更懷韜術，追思古渡头。"]', '诗', 'shi', '', NULL, '蟠溪懷古 孟賓于 shi');
